window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["N4"]={"deck":"N4","slides":[{"p":1,"title":"표지: 4주차 Attention and the Transformer Architecture","terms":["Attention","Transformer"],"pass1":[{"kind":"say","lines":["4주차 강의 표지예요. 제목은 Week 4. Attention and the Transformer Architecture 예요.","우리말로 '**어텐션(Attention)**과 **트랜스포머(Transformer)** 구조' 라는 뜻이에요.","오늘 배우는 것이 요즘 인공지능의 뼈대예요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":2,"title":"Reminder: 자료 배포 금지 안내","terms":[],"pass1":[{"kind":"say","lines":["매주 나오는 안내 쪽이에요. 강의 자료에 저작권이 있으니 밖에 배포하지 말라는 뜻이에요.","화면이나 소리에 문제가 있으면 바로 알려 달라는 내용도 있어요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":3,"title":"Contents: 오늘의 네 부분","terms":["Sequence-to-Sequence Model","Attention","Self-Attention","Transformer"],"pass1":[{"kind":"say","lines":["오늘 수업은 네 부분이에요. 앞부분이 다음 부분의 문제를 만들어 주는 순서예요."]},{"kind":"points","head":"네 부분을 한 줄씩","items":["1. Sequence-to-Sequence and its Bottleneck = **시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**과 그 병목","2. Attention = **어텐션(Attention)**. 오늘의 메인이에요","3. Self-Attention = **셀프 어텐션(Self-Attention)**. RNN 을 아예 빼요","4. The Transformer = **트랜스포머(Transformer)**. 진짜 블록을 조립해요"]}],"pass2":[{"kind":"compare","head":"영어 제목과 우리말 뜻","cols":["영어","우리말"],"rows":[["Sequence-to-Sequence","줄줄이 들어와 줄줄이 나가는 구조"],["Bottleneck","병목, 좁은 통로"],["Attention","주목하기, 어디를 볼지 정하기"],["Self-Attention","자기 자신에게 주목하기"]]}],"pass3":[{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 오늘 수업이 끝날 때면 여러분이 트랜스포머를 이해하고, 라지 랭귀지 모델이 어떻게 되는지 알아볼 수 있게 될 거예요.","교수님: 사실상 이 **트랜스포머(Transformer)**를 좀 크게 쌓으면 그게 **LLM(대규모 언어 모델)**이다, 이렇게 보셔도 돼요."]}],"pass4":[]},{"p":4,"title":"지난주 복습과 오늘 할 일","terms":["Recurrent Neural Network (RNN)","Vanishing Gradient","Attention","Self-Attention","Parallelization"],"pass1":[{"kind":"say","lines":["지난주에 신경망, **역전파(Backpropagation)**, **언어 모델(Language Model (LM))**, 그리고 **RNN(순환 신경망)**까지 배웠어요.","멈춰 선 자리는 **기울기 소실(Vanishing Gradient)**이었어요. **RNN(순환 신경망)**은 먼 거리 정보를 나르지 못하고, 병렬 계산도 안 돼요.","오늘은 그걸 정확히 고치는 두 아이디어, **어텐션(Attention)**(2015)과 **셀프 어텐션(Self-Attention)**(2017)을 배워요."]},{"kind":"figure","head":"오늘 가는 길","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"26\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">오늘 가는 길<\/text><rect x=\"8\" y=\"50\" width=\"104\" height=\"40\" rx=\"2\" class=\"box b1\"/><text x=\"60.0\" y=\"74.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">RNN 의 한계<\/text><text x=\"60\" y=\"108\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">1 먼 거리<\/text><text x=\"60\" y=\"126\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">2 순차 계산<\/text><text x=\"60\" y=\"144\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">3 정보 병목<\/text><line x1=\"114\" y1=\"70\" x2=\"137.6\" y2=\"70.0\" class=\"e2 b2\"/><polygon points=\"144,70 136.0,66.0 136.0,74.0\" class=\"arrow b2\"/><rect x=\"146\" y=\"50\" width=\"104\" height=\"40\" rx=\"2\" class=\"box2 b2\"/><text x=\"198.0\" y=\"74.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">어텐션 2015<\/text><text x=\"198\" y=\"108\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">입력을 다시<\/text><text x=\"198\" y=\"126\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">직접 본다<\/text><line x1=\"252\" y1=\"70\" x2=\"275.6\" y2=\"70.0\" class=\"e2 b3\"/><polygon points=\"282,70 274.0,66.0 274.0,74.0\" class=\"arrow b3\"/><rect x=\"284\" y=\"50\" width=\"104\" height=\"40\" rx=\"2\" class=\"box2 b3\"/><text x=\"336.0\" y=\"74.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b3\">셀프 어텐션 2017<\/text><text x=\"336\" y=\"108\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">RNN 을 뺀다<\/text><text x=\"336\" y=\"126\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">병렬로 계산<\/text><line x1=\"390\" y1=\"70\" x2=\"413.6\" y2=\"70.0\" class=\"e2 b4\"/><polygon points=\"420,70 412.0,66.0 412.0,74.0\" class=\"arrow b4\"/><rect x=\"392\" y=\"50\" width=\"80\" height=\"40\" rx=\"2\" class=\"box2 b4\"/><text x=\"432.0\" y=\"74.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">트랜스포머<\/text><text x=\"432\" y=\"108\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">= LLM 의<\/text><text x=\"432\" y=\"126\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">기본 블록<\/text><line x1=\"10\" y1=\"176\" x2=\"470\" y2=\"176\" class=\"e b4\"/><text x=\"240\" y=\"200\" font-size=\"14\" text-anchor=\"middle\" class=\"t b4\">문제 → 해결 → 새 문제 → 해결 의 순서예요<\/text><text x=\"240\" y=\"226\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">주문: 글을 토큰으로 자르고, 벡터로 바꾸고, 다음 토큰을 맞혀요<\/text><\/svg>","caption":"문제가 생기면 부품을 하나 더하는 식으로 트랜스포머까지 가요.","builds":4}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Last week: neural networks, backpropagation, language modeling, RNNs","지난주에 배운 네 가지"],["Where we stopped: vanishing gradients","멈춘 자리는 **기울기 소실(Vanishing Gradient)**"],["an RNN cannot carry information across a long distance","RNN 은 먼 거리로 정보를 못 나른다"],["and it cannot be parallelised","그리고 **병렬화(Parallelization)**도 안 된다"],["By the end: you should be able to draw the Transformer block from memory","수업이 끝나면 트랜스포머 블록을 외워서 그릴 수 있어야 한다"]]},{"kind":"points","head":"맨 아래 한 줄의 뜻","items":["From 'read it all, then speak' to 'look back at every word, every step'","'다 읽고 나서 말하기' 에서 '매 단계마다 모든 단어를 다시 보기' 로 바뀐다는 뜻이에요.","이게 **어텐션(Attention)**의 한 줄 요약이에요."]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.07,"say":"Last week 줄: 지난주에 배운 네 가지를 늘어놨어요."},{"x":0.05,"y":0.26,"w":0.9,"h":0.09,"say":"Where we stopped 줄: **기울기 소실(Vanishing Gradient)** 때문에 멈췄다는 뜻이에요."},{"x":0.05,"y":0.36,"w":0.9,"h":0.07,"say":"Today 줄: 오늘 배울 두 아이디어가 **어텐션(Attention)**(2015)과 **셀프 어텐션(Self-Attention)**(2017)이에요."},{"x":0.05,"y":0.43,"w":0.9,"h":0.07,"say":"By the end 줄: 트랜스포머 블록을 외워서 그릴 수 있어야 한다는 목표예요."},{"x":0.05,"y":0.5,"w":0.9,"h":0.07,"say":"Also today 줄: 팀 프로젝트 안내. 4인 1조, 자유 주제, 다음 주까지 팀을 알려 달라는 뜻이에요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: RNN 은 이전 정보를 은닉 상태에 담아 전달하지만, 시퀀스가 길어질수록 먼 거리 정보를 전달하기 어려워요.","교수님: 두 번째는 계산을 순서대로 해야 한다는 거예요. t 번째를 계산하려면 t-1 이 먼저 끝나야 해요.","교수님: 컴퓨터 사이언스를 하시는 분들은 순차 계산을 늘 경계하고, 병렬 파이프라인을 머릿속에 그려 주세요."]},{"kind":"bg","src":"기초 다지기 7단원","lines":["**기울기 소실(Vanishing Gradient)**은 1보다 작은 수를 여러 번 곱하는 것과 같아요. 0.5를 열 번 곱하면 0.001 이 돼요.","그래서 **시간 역전파(Backpropagation Through Time (BPTT))**로 먼 과거까지 거슬러 갈수록 학습 신호가 거의 사라져요."]}],"pass4":[{"kind":"check","q":"오늘 배우는 두 아이디어가 고치려는 RNN 의 약점 두 가지는?","choices":["먼 거리 정보 전달과 순차 계산","어휘 크기와 토큰화","과적합과 정규화","학습률과 배치 크기"],"a":0,"why":"슬라이드가 vanishing gradients 와 cannot be parallelised 라고 적었어요. **기울기 소실(Vanishing Gradient)**과 **병렬화(Parallelization)** 불가예요."},{"kind":"english","head":"답안 문장","en":"**RNN(순환 신경망)**은 먼 거리 의존을 다루기 어렵고 순차 계산이라 병렬화가 안 되는데, **어텐션(Attention)**과 **셀프 어텐션(Self-Attention)**이 이 두 약점을 각각 해결한다.","ko":"어텐션은 먼 거리를 직접 잇고, 셀프 어텐션은 순서를 없애 병렬 계산을 가능하게 해요.","tip":"'먼 거리 + 병렬' 두 단어만 기억하면 4주차 전체가 따라와요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**어텐션(Attention)**은 2015년, **셀프 어텐션(Self-Attention)**(트랜스포머)은 2017년이에요. 두 해를 바꿔 쓰지 않아요."]}]},{"p":5,"title":"Part 1 구분 슬라이드: Sequence-to-Sequence and its Bottleneck","terms":["Sequence-to-Sequence Model","Machine Translation (MT)","Encoder","Decoder"],"pass1":[{"kind":"say","lines":["Part 1 이 시작돼요. 제목은 **시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**과 그 병목이에요.","부제 'machine translation, the encoder-decoder, how to decode' 는 **기계 번역(Machine Translation (MT))**, **인코더(Encoder)**와 **디코더(Decoder)**, 그리고 디코딩 방법이라는 뜻이에요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":6,"title":"지난주에 멈춘 자리: RNN 의 세 가지 문제","terms":["Recurrent Neural Network (RNN)","Hidden State","Vanishing Gradient","Information Bottleneck","Parallelization"],"pass1":[{"kind":"say","lines":["**RNN(순환 신경망)**은 줄줄이 들어온 것을 한 걸음씩 읽으며 **은닉 상태(Hidden State)**에 요약을 들고 다녀요.","여기에는 못 풀었던 문제가 둘, 그리고 오늘 새로 보는 문제가 하나 더 있어요."]},{"kind":"points","head":"문제 세 가지를 아주 쉽게","items":["1. 멀리 있는 단어끼리 서로 닿기 어려워요","2. 앞 계산이 끝나야 뒤 계산을 할 수 있어요","3. 입력 전체가 벡터 하나에 다 들어가야 해요"]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Long-range dependency + Vanishing Gradients","먼 거리 의존과 **기울기 소실(Vanishing Gradient)**"],["Sequential Calculation","순차 계산, 앞에서 뒤로 한 칸씩"],["NEW Information Bottleneck","새 문제인 **정보 병목(Information Bottleneck)**"],["All information from the input sequence must fit into ONE vector","입력의 모든 정보가 벡터 하나에 들어가야 한다"]]},{"kind":"points","head":"세 문제와 오늘의 처방","items":["먼 거리 문제 → **어텐션(Attention)**이 입력의 모든 자리를 직접 이어 줘요","순차 계산 문제 → **셀프 어텐션(Self-Attention)**이 한꺼번에 계산하게 해 줘요(**병렬화(Parallelization)**)","**정보 병목(Information Bottleneck)** → **어텐션(Attention)**이 매 단계마다 새 요약을 만들어 줘요"]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 줄: RNN 은 한 스텝씩 읽고 은닉 상태를 들고 다닌다는 복습이에요."},{"x":0.05,"y":0.28,"w":0.9,"h":0.09,"say":"(1) 먼 거리 의존과 기울기 소실. 지난주에 배운 문제예요."},{"x":0.05,"y":0.4,"w":0.9,"h":0.06,"say":"(2) 순차 계산. 이것도 지난주 문제예요."},{"x":0.05,"y":0.47,"w":0.9,"h":0.08,"say":"(3) NEW 표시가 붙은 정보 병목. 오늘 새로 보는 문제예요."},{"x":0.05,"y":0.6,"w":0.9,"h":0.07,"say":"맨 아래: 오늘의 두 아이디어가 정확히 이 셋을 겨냥한다는 안내예요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: t 번째 은닉 상태를 계산하려면 t-1 번째가 필요해서, 하나씩 처리해야 하는 순차 계산 자체가 좋지 않아요.","교수님: 인코더에서 긴 영어 문장을 다 읽은 다음 한국어 첫 토큰을 시작하는데, 그 모든 정보가 **은닉 상태(Hidden State)** 하나에 담겨야 해요."]}],"pass4":[{"kind":"check","q":"슬라이드가 NEW 라고 표시한 새 문제는?","choices":["정보 병목","기울기 소실","순차 계산","과적합"],"a":0,"why":"(3) 에 NEW 가 붙어 있어요. 입력 전체가 벡터 하나에 들어가야 하는 **정보 병목(Information Bottleneck)**이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**기울기 소실(Vanishing Gradient)**과 **정보 병목(Information Bottleneck)**은 다른 문제예요. 앞은 학습 신호가 사라지는 문제, 뒤는 정보를 담을 칸이 모자라는 문제예요."]}]},{"p":7,"title":"오늘의 과제: 기계 번역","terms":["Machine Translation (MT)","Vocabulary","Token","Language Model (LM)"],"pass1":[{"kind":"say","lines":["오늘 계속 쓸 예제 과제는 **기계 번역(Machine Translation (MT))**이에요.","입력 문장 x 를 보고, 다른 언어의 출력 문장 y 를 만드는 일이에요."]},{"kind":"analogy","head":"번역은 두 가지 일을 동시에 해요","scene":"아주 넓은 도서관에서 '가장 좋은 답 문장' 을 찾는 일이에요. 좋은지 판단하는 눈도 있어야 하고, 넓은 서가를 뒤지는 발도 있어야 해요.","map":[["좋은 답인지 판단하는 눈","확률 모델 P(y|x), 곧 **언어 모델(Language Model (LM))**"],["넓은 서가를 뒤지는 발","탐색(search), 곧 디코딩 방법"],["서가가 끝없이 넓다","가능한 y 가 사실상 무한히 많다"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["given a source sentence x, produce a target sentence y","원문 x 가 주어지면 목표 문장 y 를 만든다"],["Formally we want argmax P(y|x)","식으로는 P(y|x) 를 가장 크게 하는 y 를 찾는다"],["the space of possible y is infinite","가능한 y 의 공간이 사실상 무한하다"],["so we will have to search it","그래서 탐색을 해야 한다"]]},{"kind":"points","head":"argmax 라는 기호","items":["argmax 는 '가장 큰 값을 주는 것' 을 뜻해요. max 는 값 자체, argmax 는 그 값을 만든 후보예요.","argmax P(y|x) 는 확률이 가장 높은 문장 y 를 고른다는 말이에요."]}],"pass3":[{"kind":"steps","head":"후보 문장이 얼마나 많을까요","steps":["**어휘(Vocabulary)** 크기 V = 32,000 이라고 해요(요즘 모델에서 흔한 크기예요)","길이가 딱 10개 **토큰(Token)**이라고 못 박아도, 자리마다 32,000 가지예요","후보 수 = 32,000을 10번 곱한 수 = 32,000^10","이 수는 46자리 수예요. 10의 45제곱 정도예요","게다가 길이도 정해져 있지 않으니 진짜 후보는 더 많아요"],"answer":"그래서 전부 확인하는 것은 불가능하고, 똑똑한 탐색(디코딩)이 필요해요."},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: y 의 공간이 사실상 거의 무한해요. 길이도 정해져 있지 않고, 자리마다 어휘 수만큼 후보가 있으니까요.","교수님: 그래서 좋은 확률 모델을 만드는 문제이면서, 동시에 거대한 탐색 공간에서 좋은 문장을 찾는 탐색 문제이기도 해요."]},{"kind":"bg","src":"기초 다지기 5단원","lines":["P(y|x) 는 'x 가 주어졌을 때 y 가 나올 확률' 이라고 읽어요. 세로줄은 '주어졌을 때' 예요."]}],"pass4":[{"kind":"check","q":"argmax P(y|x) 가 뜻하는 것은?","choices":["확률이 가장 높은 문장 y 를 고르기","확률의 최댓값 자체","x 의 확률을 구하기","y 의 길이를 정하기"],"a":0,"why":"argmax 는 값이 아니라 그 값을 만드는 후보를 가리켜요."},{"kind":"english","head":"답안 문장","en":"**기계 번역(Machine Translation (MT))**은 P(y|x) 를 최대로 하는 목표 문장 y 를 찾는 문제이고, 후보 문장 공간이 사실상 무한해서 좋은 확률 모델과 효율적인 탐색이 함께 필요하다.","ko":"모델(판단)과 디코딩(탐색) 두 축으로 나눠 적으면 점수가 잘 나와요."}]},{"p":8,"title":"번역의 역사: 규칙에서 통계로, 다시 신경망으로","terms":["Machine Translation (MT)","Neural Machine Translation (NMT)","BLEU"],"pass1":[{"kind":"say","lines":["번역의 역사는 자연어처리 전체의 역사와 모양이 같아요.","사람이 규칙을 적던 시대에서, 말뭉치 통계를 세던 시대로, 다시 신경망 하나로 통째로 배우는 시대로 왔어요."]},{"kind":"compare","head":"세 시대","cols":["시기","방식","한 줄 설명"],"rows":[["1950s-80s","규칙 기반","사람이 문법 규칙과 이중 언어 사전을 직접 만들었어요"],["1990s-2010s","통계 기반(SMT)","말뭉치에서 P(x|y) 와 P(y) 를 세어 배웠어요"],["2014-","**신경망 기계 번역(Neural Machine Translation (NMT))**","신경망 하나를 종단간으로 학습해요"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어에서 꼭 아는 단어","items":["hand-written rules = 사람이 손으로 쓴 규칙","bilingual dictionaries = 두 언어 사전","parallel corpora = 같은 뜻의 두 언어 문장 쌍 말뭉치","phrase tables, reranking, feature engineering = 통계 번역이 따로따로 만들던 부품들","trained end-to-end = 처음부터 끝까지 한 번에 학습"]},{"kind":"points","head":"한 줄 교훈","items":["슬라이드 맨 아래: replace a pipeline with one learned model","여러 부품을 이어 붙인 파이프라인을 학습된 모델 하나로 바꾼다는 뜻이에요.","2주차 word2vec, 3주차 신경망에서도 나온 같은 이야기예요."]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"1950s-80s: 규칙과 사전의 시대예요."},{"x":0.05,"y":0.26,"w":0.9,"h":0.1,"say":"1990s-2010s: 통계 기반. 정렬 모델, 구문 표, 재순위화 같은 부품이 따로따로 있었어요."},{"x":0.05,"y":0.38,"w":0.9,"h":0.1,"say":"2014-: 신경망 기계 번역. 2년 만에 수백 명이 십 년간 만든 시스템을 앞질렀어요."},{"x":0.05,"y":0.86,"w":0.9,"h":0.06,"say":"맨 아래 한 줄: 파이프라인을 학습된 모델 하나로 바꾼다."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 규칙 기반의 가장 큰 단점은 예외가 생겼을 때 아주 취약하다는 거예요.","교수님: 구글도 네이버 파파고도 원래 통계 기반이었는데, 2015~2016년쯤 신경망 방식으로 바꿨어요.","교수님: 그래프의 세로축 점수가 **블루 점수(BLEU)**인데, 높으면 번역이 잘 된 거라고 보면 돼요(뒤에서 다시 설명해요)."]}],"pass4":[{"kind":"check","q":"슬라이드가 말하는 '계속 반복되는 교훈' 은?","choices":["파이프라인을 학습된 모델 하나로 바꾼다","규칙을 더 정교하게 쓴다","사전을 더 크게 만든다","말뭉치를 줄인다"],"a":0,"why":"replace a pipeline with one learned model 이 맨 아래 한 줄이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**신경망 기계 번역(Neural Machine Translation (NMT))**이 등장한 해는 2014년, 어텐션은 2015년, 트랜스포머는 2017년이에요. 세 해가 자주 섞여요."]}]},{"p":9,"title":"인코더 디코더 구조","terms":["Encoder","Decoder","Recurrent Neural Network (RNN)","Hidden State","Sequence-to-Sequence Model"],"pass1":[{"kind":"say","lines":["**시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**의 기본 모양이에요. **RNN(순환 신경망)** 두 개를 벡터 하나로 붙였어요.","**인코더(Encoder)**는 입력을 끝까지 읽어 요약을 만들고, **디코더(Decoder)**는 그 요약을 받아 답을 한 토큰씩 만들어요."]},{"kind":"figure","head":"인코더와 디코더","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"24\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">RNN 두 개를 벡터 하나로 붙인 것<\/text><rect x=\"14\" y=\"60\" width=\"46\" height=\"34\" rx=\"2\" class=\"n b1\"/><rect x=\"64\" y=\"60\" width=\"46\" height=\"34\" rx=\"2\" class=\"n b1\"/><rect x=\"114\" y=\"60\" width=\"46\" height=\"34\" rx=\"2\" class=\"n b1\"/><rect x=\"164\" y=\"60\" width=\"46\" height=\"34\" rx=\"2\" class=\"n b1\"/><text x=\"37\" y=\"82\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">il<\/text><text x=\"87\" y=\"82\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">a<\/text><text x=\"137\" y=\"82\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">m'<\/text><text x=\"187\" y=\"82\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b1\">entarte<\/text><line x1=\"60\" y1=\"77\" x2=\"64\" y2=\"77\" class=\"e b1\"/><line x1=\"110\" y1=\"77\" x2=\"114\" y2=\"77\" class=\"e b1\"/><line x1=\"160\" y1=\"77\" x2=\"164\" y2=\"77\" class=\"e b1\"/><text x=\"112\" y=\"116\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">인코더 RNN: 왼쪽부터 한 단어씩 읽어요<\/text><line x1=\"212\" y1=\"77\" x2=\"243.6\" y2=\"77.0\" class=\"e2 b2\"/><polygon points=\"250,77 242.0,73.0 242.0,81.0\" class=\"arrow b2\"/><text x=\"231\" y=\"60\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b2\">encoding<\/text><rect x=\"254\" y=\"60\" width=\"46\" height=\"34\" rx=\"2\" class=\"n2 b3\"/><rect x=\"304\" y=\"60\" width=\"46\" height=\"34\" rx=\"2\" class=\"n2 b3\"/><rect x=\"354\" y=\"60\" width=\"46\" height=\"34\" rx=\"2\" class=\"n2 b3\"/><rect x=\"404\" y=\"60\" width=\"46\" height=\"34\" rx=\"2\" class=\"n2 b3\"/><text x=\"277\" y=\"82\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b3\">he<\/text><text x=\"327\" y=\"82\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b3\">hit<\/text><text x=\"377\" y=\"82\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b3\">me<\/text><text x=\"427\" y=\"82\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b3\">...<\/text><line x1=\"300\" y1=\"77\" x2=\"304\" y2=\"77\" class=\"e b3\"/><line x1=\"350\" y1=\"77\" x2=\"354\" y2=\"77\" class=\"e b3\"/><line x1=\"400\" y1=\"77\" x2=\"404\" y2=\"77\" class=\"e b3\"/><text x=\"352\" y=\"116\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">디코더 RNN: 한 토큰씩 만들어요<\/text><rect x=\"200\" y=\"150\" width=\"80\" height=\"30\" rx=\"2\" class=\"n4 b4\"/><text x=\"240\" y=\"170\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b4\">벡터 하나<\/text><text x=\"240\" y=\"202\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">입력의 모든 정보가 이 칸을 지나가야 해요<\/text><text x=\"240\" y=\"226\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">여기가 정보 병목(Information Bottleneck)<\/text><\/svg>","caption":"왼쪽이 인코더, 오른쪽이 디코더, 가운데 파란 화살표가 요약 벡터예요.","builds":4},{"kind":"analogy","head":"통역사 두 명","scene":"첫 번째 사람이 프랑스어 문장을 끝까지 다 듣고 쪽지 한 장에 요약을 적어 건네요. 두 번째 사람은 그 쪽지만 보고 영어로 말해요.","map":[["끝까지 듣는 사람","**인코더(Encoder)**"],["쪽지 한 장","요약 벡터(encoding)"],["쪽지만 보고 말하는 사람","**디코더(Decoder)**"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Two RNNs","RNN 두 개"],["The encoder reads the source and compresses it into a vector","인코더가 원문을 읽어 벡터 하나로 압축한다"],["The decoder is a language model that generates the target","디코더는 목표 문장을 만드는 언어 모델이다"],["conditioned on that vector","그 벡터를 조건으로 하여"]]},{"kind":"points","head":"그림 속 낱말","items":["source sentence (input) = 원문, 곧 입력 문장","target sentence (output) = 목표 문장, 곧 출력 문장","encoding = 인코더의 마지막 은닉 상태, 곧 요약 벡터","<s> = 문장 시작을 알리는 특별한 토큰이에요"]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.09,"say":"위쪽 두 줄: 인코더는 읽어서 압축하고, 디코더는 그 벡터를 조건으로 생성한다는 설명이에요."},{"x":0.06,"y":0.5,"w":0.32,"h":0.22,"say":"왼쪽 주황 상자들: 인코더 RNN. il a m' entarte 를 한 단어씩 읽어요."},{"x":0.33,"y":0.53,"w":0.09,"h":0.1,"say":"파란 화살표와 encoding 글자: 여기서 요약 벡터가 디코더로 넘어가요."},{"x":0.41,"y":0.38,"w":0.52,"h":0.35,"say":"오른쪽 초록 상자들: 디코더 RNN. <s> 부터 시작해 he hit me with a pie 를 만들어요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 핵심은 RNN 2개를 왼쪽과 오른쪽에 연결한다는 거예요. 왼쪽이 인코더, 오른쪽이 디코더예요.","교수님: 이 벡터 하나가 굉장히 중요한 정보를 담고 있겠죠. 모든 원문 정보를 다 담고 있어야 해요.","교수님: 번역의 특징은 문장을 전부 다 입력받은 다음에 번역을 시작한다는 거예요."]},{"kind":"points","head":"슬라이드 맨 아래 출처","items":["Sutskever et al. 2014, Cho et al. 2014 가 이 구조를 제안한 논문이에요.","'two RNNs, glued at one vector' 는 'RNN 두 개를 벡터 하나로 붙였다' 는 뜻이에요."]}],"pass4":[{"kind":"check","q":"인코더의 출력이 디코더로 넘어가는 통로는?","choices":["마지막 은닉 상태 벡터 하나","입력 문장 전체","어휘 목록","손실 함수"],"a":0,"why":"그림의 encoding 이 인코더의 마지막 **은닉 상태(Hidden State)**이고, 이것이 유일한 통로예요. 여기가 나중에 병목이 돼요."},{"kind":"english","head":"답안 문장","en":"**시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**은 **인코더(Encoder)** RNN 이 입력 문장을 읽어 고정 크기 벡터 하나로 압축한다. **디코더(Decoder)** RNN 은 그 벡터를 조건으로 목표 문장을 한 토큰씩 생성한다.","ko":"'두 RNN + 벡터 하나' 라는 뼈대를 먼저 쓰고 세부를 붙여요."}]},{"p":10,"title":"디코더는 조건부 언어 모델","terms":["Conditional Language Model","Language Model (LM)","Cross-Entropy","Loss Function","End-to-End","Backpropagation"],"pass1":[{"kind":"say","lines":["**디코더(Decoder)**는 그냥 **언어 모델(Language Model (LM))**인데, 입력 문장 x 라는 조건이 하나 더 붙은 거예요.","그래서 **조건부 언어 모델(Conditional Language Model)**이라고 불러요. 하는 일은 3주차의 **다음 토큰 예측(Next Token Prediction)** 그대로예요.","학습은 3주차에 배운 교차 엔트로피 그대로예요."]},{"kind":"analogy","head":"조건이 붙은 자판 추천","scene":"휴대폰 자판이 다음 단어를 추천할 때, 원래는 내가 쓴 앞부분만 봐요. 번역기는 거기에 '원문' 이라는 조건이 하나 더 붙어요.","map":[["내가 쓴 앞부분","앞서 만든 토큰들 y1 ... y(t-1)"],["원문이라는 조건","입력 문장 x"],["추천 목록","다음 토큰의 확률 분포"]]}],"pass2":[{"kind":"formula","head":"문장 확률을 쪼개는 식","tex":"P(y \\mid x) = P(y_1 \\mid x)\\, P(y_2 \\mid y_1, x)\\, P(y_3 \\mid y_1, y_2, x) \\cdots P(y_T \\mid y_1, \\dots, y_{T-1}, x)","parts":[{"sym":"P(y \\mid x)","say":"원문 x 를 봤을 때 답 문장 y 전체가 나올 확률"},{"sym":"P(y_1 \\mid x)","say":"첫 토큰은 x 만 보고 정해요"},{"sym":"P(y_2 \\mid y_1, x)","say":"두 번째는 x 와 이미 만든 y1 을 보고 정해요"},{"sym":"\\cdots","say":"끝까지 같은 방식으로 이어져요"},{"sym":"y_T","say":"마지막 T 번째 토큰"}],"whole":"매 자리마다 x 가 조건으로 계속 붙는 것, 이게 **조건부 언어 모델(Conditional Language Model)**이에요."},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["conditioned on the source = 원문을 조건으로 삼아서","factorises the same way an LM does = 언어 모델과 똑같은 방식으로 쪼개진다","ordinary cross-entropy on the target tokens = 목표 토큰에 대한 평범한 교차 엔트로피","the gradient flows all the way back = 기울기가 끝까지 거슬러 흐른다"]},{"kind":"points","head":"3주차와 이어지는 점","items":["3주차에서 배운 **다음 토큰 예측(Next Token Prediction)**과 계산이 똑같아요. 조건 x 하나가 더 붙었을 뿐이에요.","교수님: **다음 토큰 예측(Next Token Prediction)**이 거의 모든 걸 결정한다, GPT 도 다 결국 이거다.","그래서 **언어 모델(Language Model (LM))**을 이해하면 번역 모델도 바로 이해돼요.","**자연어처리(Natural Language Processing (NLP))** 전체가 이 한 가지 위에 서 있다고 봐도 돼요.","손실을 거슬러 보내는 것도 3주차의 **시간 역전파(Backpropagation Through Time (BPTT))** 와 같은 방식이에요."]},{"kind":"points","head":"이 구조가 어디까지 가나","items":["**시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)** 에 어텐션을 붙이고, RNN 을 빼면 트랜스포머가 돼요.","트랜스포머를 크게 쌓은 것이 **LLM(대규모 언어 모델)** 이에요.","**자연어처리(Natural Language Processing (NLP))** 수업의 나머지가 전부 이 길 위에 있어요.","**시간 역전파(Backpropagation Through Time (BPTT))** 는 RNN 을 쓰는 동안만 필요하고, 트랜스포머에서는 사라져요."]}],"pass3":[{"kind":"formula","head":"학습 손실","tex":"J = \\frac{1}{T}\\sum_{t=1}^{T} J_t, \\qquad J_t = -\\log P(y_t^{*} \\mid y_{<t}^{*}, x)","parts":[{"sym":"J_t","say":"t 번째 자리의 벌점"},{"sym":"y_t^{*}","say":"t 번째 자리의 정답 토큰(별표가 정답이라는 표시예요)"},{"sym":"y_{<t}^{*}","say":"t 보다 앞의 정답 토큰들"},{"sym":"-\\log","say":"정답에 준 확률이 작을수록 커지는 벌점"},{"sym":"\\frac{1}{T}\\sum","say":"모든 자리의 벌점을 더해 자리 수로 나눈 평균"}],"whole":"**교차 엔트로피(Cross-Entropy)** 그대로예요. 3주차 **손실 함수(Loss Function)**와 같은 식이에요."},{"kind":"steps","head":"벌점을 손으로 계산해 봐요","given":"정답 확률 0.5, 0.25, 0.8, 0.1 (자연로그를 써요)","steps":["네 자리의 정답 확률이 각각 0.5, 0.25, 0.8, 0.1 이라고 해요","J1 = -log(0.5) = 0.693","J2 = -log(0.25) = 1.386","J3 = -log(0.8) = 0.223","J4 = -log(0.1) = 2.303","합 = 4.605, 자리 수 4 로 나누면 1.151"],"answer":"평균 벌점 J = 1.151 이에요. 정답 확률이 클수록 벌점이 작아요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 줄: 디코더는 원문에 조건이 걸린 언어 모델이라는 설명이에요."},{"x":0.05,"y":0.25,"w":0.9,"h":0.09,"say":"둘째 줄: 학습은 평범한 교차 엔트로피, 기울기는 디코더, 다리, 인코더까지 흐른다."},{"x":0.16,"y":0.45,"w":0.7,"h":0.09,"say":"위 식: 문장 확률을 자리별 확률의 곱으로 쪼갠 식이에요."},{"x":0.34,"y":0.58,"w":0.36,"h":0.1,"say":"아래 식: 자리별 벌점 J_t 와 그 평균 J 예요."},{"x":0.24,"y":0.85,"w":0.52,"h":0.06,"say":"맨 아래: one model, one loss, one backward pass 가 **종단간 학습(End-to-End)**의 뜻이에요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 매 단계마다 원문 x 가 추가 조건으로 들어간다는 게 기존 언어 모델과 다른 점이에요.","교수님: 끝까지 만들고 나서 한 번에 기울기가 업데이트되는 구조를 **종단간 학습(End-to-End)**라고 해요."]}],"pass4":[{"kind":"check","q":"J_t 의 값이 가장 큰 경우는?","choices":["정답 토큰에 준 확률이 0.01 일 때","0.9 일 때","0.5 일 때","1.0 일 때"],"a":0,"why":"-log(0.01) = 4.61 로 가장 커요. 정답에 준 확률이 작을수록 벌점이 커져요."},{"kind":"english","head":"답안 문장","en":"**시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**의 디코더는 원문 x 를 조건으로 하는 언어 모델이므로 P(y|x) 를 자리별 조건부 확률의 곱으로 쪼갤 수 있고, 학습 손실은 정답 토큰에 대한 교차 엔트로피의 평균이다.","ko":"'조건이 붙은 언어 모델 + 교차 엔트로피 + **종단간 학습(End-to-End)**' 세 마디로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["곱으로 쓴 식은 확률, 합으로 쓴 식은 손실이에요. 로그를 씌우면 곱이 합으로 바뀌어요.","별표가 붙은 y* 는 정답 토큰이라는 뜻이에요. 모델이 만든 토큰이 아니에요."]}]},{"p":11,"title":"학습 방법: 교사 강요","terms":["Teacher Forcing","Exposure Bias","Inference","Cross-Entropy","Loss Function"],"pass1":[{"kind":"say","lines":["학습할 때는 **교사 강요(Teacher Forcing)**를 써요. 모델이 뭐라고 예측했든, 다음 입력으로는 정답 단어를 넣어 줘요.","선생님이 옆에서 정답을 계속 알려 주는 것과 같아서 이런 이름이에요."]},{"kind":"analogy","head":"받아쓰기 연습","scene":"받아쓰기를 하다가 한 글자 틀려도 선생님이 바로 정답을 알려 주고 다음 글자로 넘어가요. 그래야 뒤쪽 연습도 제대로 할 수 있어요.","map":[["선생님이 알려 주는 정답","정답 토큰을 다음 입력으로 넣기"],["한 글자 틀려도 계속 진도","각 자리의 벌점만 따로 매기기"],["실전에서는 알려 주는 사람이 없다","**노출 편향(Exposure Bias)**"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["we feed the decoder the true previous target word","디코더에 직전의 진짜 정답 단어를 넣어 준다"],["not its own prediction","모델 자신의 예측이 아니라"],["it keeps training stable and parallel over time steps","학습이 안정되고 시점끼리 병렬로 돌아간다"],["at test time the model only ever sees its own output","시험 때는 모델이 자기 출력만 본다"],["this mismatch is called exposure bias","이 어긋남을 **노출 편향(Exposure Bias)**이라고 한다"]]},{"kind":"points","head":"왜 학습이 병렬이 되나요","items":["정답 문장을 이미 알고 있으니, 모든 자리의 입력을 처음부터 다 알 수 있어요.","그래서 자리마다 기다릴 필요 없이 한꺼번에 계산할 수 있어요.","반대로 **추론(Inference)** 때는 앞 토큰을 만들어야 다음 입력이 정해지니 순차적이에요."]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 줄: 학습 때는 진짜 정답 단어를 넣는다는 정의예요."},{"x":0.05,"y":0.25,"w":0.9,"h":0.09,"say":"Why 와 The catch: 왜 쓰는지, 그리고 대가가 무엇인지예요."},{"x":0.21,"y":0.42,"w":0.58,"h":0.09,"say":"gold targets 줄: 위쪽의 he hit me with a pie <e> 가 정답이에요."},{"x":0.21,"y":0.45,"w":0.58,"h":0.09,"say":"per-step loss 줄: 자리마다 J1 ... J7 벌점을 따로 매겨요."},{"x":0.21,"y":0.63,"w":0.58,"h":0.09,"say":"fed back in 줄: 아래쪽 입력이 모델 예측이 아니라 정답 단어예요."},{"x":0.25,"y":0.75,"w":0.5,"h":0.07,"say":"식 J = (1/T) 합 J_t 와 backprop 이 인코더까지 흐른다는 설명이에요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 가장 자연스러운 방법은 모델이 방금 예측한 단어를 다음 입력으로 넣는 건데, 학습 초반에는 모델이 잘 못하겠죠.","교수님: 그래서 각 토큰마다 지도 학습 형식으로 정답을 주는 걸 교사 강요라고 해요.","교수님: 학습 환경과 테스트 환경이 다른 이 어긋남을 익스포저 바이어스라고 합니다."]},{"kind":"bg","src":"배경 지식","lines":["강화 학습은 문장을 다 만든 뒤 마지막에 보상을 줘요. 그래서 어느 토큰이 잘했는지 알기 어려워요.","교사 강요는 자리마다 바로 벌점을 줄 수 있어서 학습이 훨씬 빠르고 안정적이에요."]}],"pass4":[{"kind":"check","q":"교사 강요의 대가로 생기는 문제는?","choices":["노출 편향","기울기 폭발","과적합","정보 병목"],"a":0,"why":"학습 때는 정답을, 시험 때는 자기 출력을 본다는 어긋남이 **노출 편향(Exposure Bias)**이에요."},{"kind":"exam","src":"N4 Check Yourself","q":"Q2. In teacher forcing, what exactly is different between training time and test time?","qko":"**교사 강요(Teacher Forcing)**에서 학습할 때와 시험할 때가 정확히 무엇이 다른가?","solve":["학습할 때는 정답 토큰(gold token)을 다음 입력으로 넣을 수 있어요","시험(추론)할 때는 정답을 모르니까 모델이 직전에 만든 토큰을 넣어야 해요","그래서 디코더가 보는 앞부분이 학습과 시험에서 달라져요","이 어긋남을 **노출 편향(Exposure Bias)**이라고 불러요"],"answer":"다음 입력이 학습에서는 정답 토큰, 시험에서는 모델 자신의 출력이라는 점이 다르다(노출 편향)."},{"kind":"english","head":"답안 문장","en":"**교사 강요(Teacher Forcing)**는 학습 시 디코더의 다음 입력으로 정답 토큰을 넣어 학습을 안정적이고 병렬적으로 만든다. 추론 시에는 모델 자신의 출력만 보므로 학습과 추론이 어긋나는 **노출 편향(Exposure Bias)**이 생긴다.","ko":"장점(안정, 병렬)과 단점(노출 편향)을 반드시 함께 써요."}]},{"p":12,"title":"디코딩 1: 탐욕적 디코딩","terms":["Greedy Decoding","Inference","Beam Search"],"pass1":[{"kind":"say","lines":["이제 학습이 끝난 모델로 문장을 만들어요. 이걸 **추론(Inference)**이라고 해요.","가장 단순한 방법이 **탐욕적 디코딩(Greedy Decoding)**이에요. 매 순간 확률이 가장 높은 토큰 하나만 골라요."]},{"kind":"figure","head":"탐욕은 되돌릴 수 없어요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"24\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">탐욕은 되돌릴 수 없어요<\/text><rect x=\"20\" y=\"54\" width=\"70\" height=\"32\" rx=\"2\" class=\"box2 b1\"/><text x=\"55.0\" y=\"74.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">he 0.6<\/text><rect x=\"20\" y=\"104\" width=\"70\" height=\"32\" rx=\"2\" class=\"box b1\"/><text x=\"55.0\" y=\"124.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b1\">I 0.4<\/text><line x1=\"92\" y1=\"70\" x2=\"121.8\" y2=\"61.7\" class=\"e2 b2\"/><polygon points=\"128,60 119.2,58.3 121.4,66.0\" class=\"arrow b2\"/><line x1=\"92\" y1=\"70\" x2=\"123.6\" y2=\"103.4\" class=\"e b2\"/><polygon points=\"128,108 125.4,99.4 119.6,104.9\" class=\"arrow b2\"/><rect x=\"130\" y=\"44\" width=\"80\" height=\"32\" rx=\"2\" class=\"box b2\"/><text x=\"170.0\" y=\"64.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">hit 0.3<\/text><rect x=\"130\" y=\"92\" width=\"80\" height=\"32\" rx=\"2\" class=\"box b2\"/><text x=\"170.0\" y=\"112.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">struck 0.2<\/text><line x1=\"92\" y1=\"120\" x2=\"123.5\" y2=\"151.5\" class=\"e b3\"/><polygon points=\"128,156 125.2,147.5 119.5,153.2\" class=\"arrow b3\"/><line x1=\"92\" y1=\"120\" x2=\"125.3\" y2=\"190.2\" class=\"e b3\"/><polygon points=\"128,196 128.2,187.1 121.0,190.5\" class=\"arrow b3\"/><rect x=\"130\" y=\"140\" width=\"80\" height=\"32\" rx=\"2\" class=\"box2 b3\"/><text x=\"170.0\" y=\"160.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b3\">was 0.9<\/text><rect x=\"130\" y=\"188\" width=\"80\" height=\"32\" rx=\"2\" class=\"box b3\"/><text x=\"170.0\" y=\"208.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">got 0.1<\/text><text x=\"300\" y=\"60\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">he hit = 0.6 x 0.3 = 0.18<\/text><text x=\"300\" y=\"86\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">I was  = 0.4 x 0.9 = 0.36<\/text><text x=\"300\" y=\"130\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">탐욕은 첫 칸에서 he 를 골라<\/text><text x=\"300\" y=\"150\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">I was 로 가는 길을 아예 잃어요<\/text><text x=\"300\" y=\"186\" font-size=\"13\" text-anchor=\"middle\" class=\"t b5\">빔 서치는 he 와 I 를<\/text><text x=\"300\" y=\"206\" font-size=\"13\" text-anchor=\"middle\" class=\"t b5\">둘 다 들고 가요<\/text><\/svg>","caption":"첫 칸에서 확률이 높은 he 를 고르면 더 좋은 I was 길을 영영 잃어요.","builds":5},{"kind":"analogy","head":"갈림길에서 눈앞만 보기","scene":"산에서 갈림길마다 지금 당장 더 편해 보이는 쪽으로만 가요. 나중에 막다른 길이 나와도 되돌아갈 수 없어요.","map":[["지금 당장 편한 쪽","그 자리에서 확률이 가장 높은 토큰"],["되돌아갈 수 없음","한 번 고르면 취소 못 함"],["전체로는 더 좋은 길","전체 문장 확률이 더 높은 다른 후보"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["At each step take the single most likely word","매 단계마다 가장 그럴듯한 단어 하나를 고른다"],["Fast, and often fine","빠르고, 대개는 괜찮다"],["it cannot take anything back","아무것도 되돌릴 수 없다"],["one confident wrong word early on poisons everything that follows","앞에서 자신 있게 틀린 단어 하나가 뒤 전체를 망친다"],["one path through an exponentially large tree","기하급수적으로 큰 나무에서 길 하나만 따라가기"]]},{"kind":"points","head":"greedy 라는 단어","items":["greedy 는 '욕심 많은, 탐욕스러운' 이라는 뜻이에요.","알고리즘 수업에서 말하는 그 탐욕 알고리즘과 같은 생각이에요.","지금 이 순간 제일 좋아 보이는 것만 고르는 방식이에요."]}],"pass3":[{"kind":"steps","head":"탐욕이 놓치는 예를 손으로","given":"첫 자리 he 0.6 / I 0.4, 둘째 자리 위와 같음","steps":["첫 자리 확률: he 0.6, I 0.4 → 탐욕은 he 를 골라요","he 뒤: hit 0.3, struck 0.2","I 뒤: was 0.9, got 0.1","he hit 의 전체 확률 = 0.6 x 0.3 = 0.18","I was 의 전체 확률 = 0.4 x 0.9 = 0.36","전체로 보면 I was 가 두 배나 좋은데, 탐욕은 그 길을 아예 못 봐요"],"answer":"국소적으로 최선이 전체적으로 최선을 보장하지 않아요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 줄: 매 단계 가장 그럴듯한 단어 하나를 고른다. 빠르고 대개 괜찮다."},{"x":0.05,"y":0.24,"w":0.9,"h":0.06,"say":"둘째 줄: 되돌릴 수 없다. 앞에서 틀리면 뒤가 다 망가진다."},{"x":0.06,"y":0.5,"w":0.9,"h":0.13,"say":"가운데 상자들: he hit 까지는 초록(좋음)인데 a 부터 빨강으로 바뀌어요."},{"x":0.23,"y":0.65,"w":0.56,"h":0.06,"say":"빨간 글씨: 3단계에서 a 를 골랐지만 좋은 이어짐은 me with a pie 였어요."},{"x":0.2,"y":0.73,"w":0.6,"h":0.06,"say":"그래서 여러 후보를 함께 탐색하자는 제안으로 이어져요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 매 순간은 좋은 선택이지만, 우리가 원하는 건 전체 P(y|x) 를 높이는 거예요.","교수님: 로컬 베스트가 글로벌 베스트를 보장하지 않는다는 건 너무 자명하죠."]}],"pass4":[{"kind":"check","q":"탐욕적 디코딩의 가장 큰 약점은?","choices":["한 번 고른 토큰을 되돌릴 수 없다","계산이 너무 느리다","어휘가 커야 한다","학습이 불안정하다"],"a":0,"why":"슬라이드 문장 it cannot take anything back 이 그대로 답이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**탐욕적 디코딩(Greedy Decoding)**는 '나쁜 방법' 이 아니에요. 빠르고 대개 괜찮아서 요즘 **LLM(대규모 언어 모델)**에서도 많이 써요."]}]},{"p":13,"title":"디코딩 2: 빔 서치","terms":["Beam Search","Beam Size","Length Normalization","Greedy Decoding"],"pass1":[{"kind":"say","lines":["**빔 서치(Beam Search)**는 후보 하나 대신 좋은 후보 k 개를 함께 들고 가요.","이 k 를 **빔 크기(Beam Size)**라고 해요. 보통 5에서 10 을 써요."]},{"kind":"analogy","head":"등산로 여러 개를 함께 살피기","scene":"갈림길마다 길 하나만 고르지 않고, 지금까지 가장 유망한 두 길을 계속 들고 가면서 비교해요.","map":[["들고 가는 길 개수","**빔 크기(Beam Size)**"],["지금까지의 점수","로그 확률의 합"],["길이 하나만 남을 때","k = 1, 곧 탐욕적 디코딩"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Keep the k best partial hypotheses at every step","매 단계마다 가장 좋은 부분 후보 k 개를 남긴다"],["Typical k is 5 to 10","보통 k 는 5에서 10"],["Score is a sum of log-probabilities","점수는 로그 확률의 합이다"],["longer sequences score lower","길수록 점수가 낮아진다"],["divide by length before comparing finished hypotheses","끝난 후보를 비교하기 전에 길이로 나눈다(**길이 정규화(Length Normalization)**)"]]},{"kind":"formula","head":"부분 후보의 점수","tex":"\\text{score}(y_{1:t}) = \\sum_{i=1}^{t} \\log P(y_i \\mid y_{<i}, x)","parts":[{"sym":"\\log P","say":"각 자리에서 고른 토큰의 확률에 로그를 씌운 값"},{"sym":"\\sum","say":"지금까지 고른 토큰들의 로그 확률을 모두 더해요"},{"sym":"y_{1:t}","say":"첫 토큰부터 t 번째까지의 부분 문장"}],"whole":"확률은 1보다 작으니 로그는 음수예요. 그래서 길어질수록 점수가 계속 내려가요."}],"pass3":[{"kind":"look","head":"슬라이드의 나무를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 줄: 매 단계 k 개를 남긴다, 보통 5에서 10."},{"x":0.05,"y":0.24,"w":0.9,"h":0.06,"say":"둘째 줄: 점수는 로그 확률의 합, 길면 낮아지니 길이로 나눠 비교한다."},{"x":0.17,"y":0.53,"w":0.09,"h":0.07,"say":"<s> 0.0 에서 출발해요."},{"x":0.28,"y":0.45,"w":0.1,"h":0.2,"say":"t=1: he -0.7 과 I -1.3 두 개를 남겨요(k=2)."},{"x":0.4,"y":0.4,"w":0.12,"h":0.3,"say":"t=2: he hit -1.6 과 I was -2.9 가 살아남고, 점선 상자는 버려요."},{"x":0.54,"y":0.4,"w":0.14,"h":0.28,"say":"t=3: he hit me -2.5 와 I was hit -3.5."},{"x":0.66,"y":0.4,"w":0.16,"h":0.28,"say":"오른쪽 범례: 파랑은 살아남음, 점선은 버림, 초록은 다음으로 넓힘."},{"x":0.17,"y":0.72,"w":0.66,"h":0.09,"say":"아래 상자: 부분 후보의 점수는 로그 확률의 합이라는 식이에요."}]},{"kind":"steps","head":"길이 정규화가 왜 필요한가요","given":"후보 A(길이 3, 합 -2.5), 후보 B(길이 6, 합 -4.2)","steps":["끝난 후보 A: 토큰 3개, 로그 확률 합 -2.5","끝난 후보 B: 토큰 6개, 로그 확률 합 -4.2","합만 비교하면 -2.5 > -4.2 이므로 짧은 A 가 이겨요","길이로 나누면 A 는 -2.5 / 3 = -0.833","B 는 -4.2 / 6 = -0.700","-0.700 > -0.833 이므로 이번에는 B 가 이겨요"],"answer":"길이로 나누지 않으면 짧은 문장만 계속 뽑혀요. 그래서 길이 정규화를 해요."},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 보통 빔은 5에서 10 정도를 많이 쓰고, 그림에서는 k 를 2로 둔 거예요.","교수님: 로그 확률이 음수라 길이가 길어질수록 점수가 계속 낮아져요. 그래서 길이 정규화를 해요.","교수님: 빔 서치는 빔 크기를 2, 3만 해도 확실히 그리디보다 훨씬 오래 걸려요. 항상 좋은 건 아니고 트레이드 오프가 있어요."]},{"kind":"bg","src":"배경 지식","lines":["로그 확률을 쓰는 이유는 아주 작은 확률을 여러 번 곱하면 컴퓨터에서 0 으로 내려앉기 때문이에요.","곱을 로그로 바꾸면 합이 되고, 숫자가 안정돼요(기초 다지기 4단원)."]}],"pass4":[{"kind":"exam","src":"N4 Check Yourself","q":"Q3. Beam search with k = 1 is the same as which algorithm? And why must we normalise by length?","qko":"**빔 크기(Beam Size)** k = 1 인 **빔 서치(Beam Search)**는 어떤 알고리즘과 같고, 왜 **길이 정규화(Length Normalization)**가 필요한가?","solve":["k = 1 이면 매 단계마다 후보를 하나만 남겨요","그건 매 순간 최고만 고르는 **탐욕적 디코딩(Greedy Decoding)**와 똑같아요","점수는 로그 확률의 합이고 로그 확률은 음수예요","그래서 문장이 길어질수록 점수가 계속 작아져요","나누지 않으면 짧은 문장만 뽑히니까 길이로 나눠 비교해요"],"answer":"k = 1 은 탐욕적 디코딩과 같다. 로그 확률의 합이 길이에 따라 계속 작아져 짧은 문장을 과도하게 선호하므로 길이로 나눈다."},{"kind":"check","q":"k = 2 인 빔 서치가 매 단계에서 하는 일은?","choices":["후보마다 다음 토큰을 뽑아 점수순으로 2개만 남긴다","항상 가장 높은 1개만 남긴다","모든 후보를 끝까지 남긴다","무작위로 2개를 고른다"],"a":0,"why":"빔 크기만큼만 남기고 나머지는 가지치기(pruning)해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드 그림은 교수님이 '조금 단순화시켰다' 고 한 그림이에요. 점수만 보면 he struck(-2.3)이 I was(-2.9)보다 높은데, 그림은 가지마다 하나씩 남겼어요.","원래 빔 서치 논문에는 남기는 수 n 과 뽑는 수 k 가 따로 있어요. 수업에서는 둘을 같다고 보고 k 하나로 설명해요."]}]},{"p":14,"title":"번역 평가: BLEU","terms":["BLEU","n-gram","Brevity Penalty","Machine Translation (MT)"],"pass1":[{"kind":"say","lines":["만들어 낸 번역이 좋은지 어떻게 재나요. 가장 많이 쓰인 점수가 **블루 점수(BLEU)**예요.","사람이 쓴 정답 문장(reference)과 **n-gram(엔그램)**이 얼마나 겹치는지를 세요."]},{"kind":"analogy","head":"답안지와 모범답안 겹쳐 보기","scene":"모범답안과 내 답안을 겹쳐 놓고, 한 단어짜리, 두 단어짜리, 세 단어짜리, 네 단어짜리 표현이 각각 얼마나 똑같이 나왔는지 세요.","map":[["모범답안","reference, 곧 사람이 만든 정답 번역"],["내 답안","output, 곧 모델의 번역"],["겹친 표현 세기","**n-gram(엔그램)** 정밀도 n = 1 에서 4"],["너무 짧게 써서 점수 따는 꼼수 막기","**간결성 페널티(Brevity Penalty)**"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["compares the model output against one or more human references","모델 출력을 사람이 만든 정답 하나 이상과 비교한다"],["counting overlapping n-grams (n = 1...4)","겹치는 n-gram 을 n = 1 에서 4 까지 센다"],["with a brevity penalty so the model cannot win by saying less","짧게 말해서 이기지 못하도록 간결성 페널티를 둔다"],["a good translation that uses different words scores badly","다른 말로 잘 옮긴 번역도 점수가 나쁘게 나온다"],["BLEU rewards being ordinary","BLEU 는 평범한 번역에 상을 준다"]]},{"kind":"points","head":"슬라이드의 예문","items":["reference: the cat is on the mat","output: the cat the cat on the mat","1-gram 은 많이 겹치는데 4-gram 은 하나도 안 겹쳐요.","슬라이드 막대: 0.86, 0.50, 0.20, 0.00"]}],"pass3":[{"kind":"steps","head":"2-gram 정밀도를 손으로 세어 봐요","given":"reference: the cat is on the mat / output: the cat the cat on the mat","steps":["출력의 2-gram: the cat / cat the / the cat / cat on / on the / the mat → 6개","정답의 2-gram: the cat / cat is / is on / on the / the mat → 5개","the cat 은 정답에 1번뿐이라 출력에 2번 나와도 1번만 인정해요","맞은 것: the cat 1개, on the 1개, the mat 1개 = 3개","2-gram 정밀도 = 3 / 6 = 0.50"],"answer":"슬라이드 막대의 0.50 과 같아요."},{"kind":"steps","head":"3-gram 과 4-gram 도 세어 봐요","steps":["출력의 3-gram: the cat the / cat the cat / the cat on / cat on the / on the mat → 5개","정답의 3-gram: the cat is / cat is on / is on the / on the mat → 4개","맞은 것: on the mat 1개 → 1 / 5 = 0.20","출력의 4-gram: the cat the cat / cat the cat on / the cat on the / cat on the mat → 4개","정답의 4-gram 중 같은 것이 하나도 없어요 → 0 / 4 = 0.00"],"answer":"3-gram 0.20, 4-gram 0.00. BLEU 는 네 정밀도를 곱하므로 하나가 0 이면 전체가 0 이에요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.07,"say":"정의 줄: 정답과 겹치는 n-gram 을 세고 간결성 페널티를 붙인다."},{"x":0.05,"y":0.28,"w":0.9,"h":0.09,"say":"Example 줄: 슬라이드가 든 예문과 그 결과예요."},{"x":0.05,"y":0.38,"w":0.9,"h":0.06,"say":"It is useful but imperfect: 쓸모 있지만 완벽하지 않다는 경고예요."},{"x":0.17,"y":0.52,"w":0.48,"h":0.18,"say":"가운데 상자: 위가 reference, 아래가 output 이에요."},{"x":0.68,"y":0.45,"w":0.24,"h":0.25,"say":"오른쪽 막대: n-gram 정밀도 0.86, 0.50, 0.20, 0.00."},{"x":0.23,"y":0.73,"w":0.54,"h":0.05,"say":"설명: 유니그램은 괜찮아 보여도 4-gram 은 아니다, BLEU 는 정밀도를 곱하므로 반복이 벌을 받는다."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 블루는 레퍼런스 기반 점수라서 사람이 만든 정답 문장이 꼭 하나 필요해요.","교수님: 모델이 짧은 문장만 내서 정밀도를 높이는 걸 막기 위해 너무 짧은 번역에 페널티를 주는 항이 있어요.","교수님: 요새는 좀 오래된 지표지만 이미지 캡셔닝 같은 데서는 아직도 쓰이니 알아 두면 좋아요."]}],"pass4":[{"kind":"check","q":"BLEU 에서 4-gram 정밀도가 0 이면 어떻게 되나요?","choices":["네 정밀도를 곱하므로 BLEU 가 0 이 된다","1-gram 점수만 쓴다","간결성 페널티가 사라진다","점수가 오히려 올라간다"],"a":0,"why":"슬라이드: BLEU multiplies the precisions. 하나가 0 이면 곱이 0 이에요."},{"kind":"english","head":"답안 문장","en":"**블루 점수(BLEU)**는 모델 번역과 정답 번역 사이에서 1-gram 부터 4-gram 까지의 겹침을 재고, 짧은 번역을 막으려고 **간결성 페널티(Brevity Penalty)**를 곱한다. 뜻이 같아도 표현이 다르면 점수가 낮은 한계가 있다.","ko":"정의(겹침) + 페널티(짧음 방지) + 한계(표현 다양성) 세 마디를 꼭 넣어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드의 1-gram 값은 0.86(6/7)이에요. 중복을 정답에 나온 횟수까지만 세는 규칙을 cat 에도 적용하면 5/7 = 0.71 이 돼요. 시험에서는 슬라이드 숫자를 기준으로 삼아요.","**블루 점수(BLEU)**가 높다고 언제나 번역이 더 좋은 건 아니에요. 다른 낱말로 잘 옮기면 오히려 점수가 낮아져요."]}]},{"p":15,"title":"인코더 디코더는 번역만을 위한 것이 아니에요","terms":["Sequence-to-Sequence Model","Encoder","Decoder"],"pass1":[{"kind":"say","lines":["**시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**은 특정 과제 이름이 아니라 틀(프레임워크) 이름이에요.","입력도 줄줄이, 출력도 줄줄이면 무엇이든 같은 구조로 풀 수 있어요."]},{"kind":"compare","head":"슬라이드의 다섯 가지 예","cols":["과제","인코더가 읽는 것","디코더가 쓰는 것"],"rows":[["Machine translation(번역)","원문 문장","목표 문장"],["Summarization(요약)","긴 문서","짧은 요약"],["Dialogue(대화)","앞선 대화들","다음 차례의 말"],["Speech recognition(음성 인식)","소리 신호","글로 받아쓴 것"],["Code generation(코드 생성)","자연어로 쓴 요구","프로그램 코드"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["The same architecture works whenever the input and the output are both sequences = 입력과 출력이 모두 시퀀스면 같은 구조가 통한다","they need not be the same kind of sequence = 같은 종류의 시퀀스일 필요도 없다","Learn the pattern once, reuse it for the rest of the course = 한 번 배워 두면 이 수업 내내 다시 쓴다"]},{"kind":"points","head":"같은 종류가 아니어도 된다는 말","items":["음성 인식은 소리가 들어가고 글이 나와요.","코드 생성은 우리말 요구가 들어가고 파이썬 코드가 나와요.","들어가는 것과 나오는 것의 모양(modality)이 달라도 괜찮아요."]}],"pass3":[{"kind":"look","head":"슬라이드의 표를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.08,"say":"위 줄: 입력과 출력이 모두 시퀀스이면 같은 구조가 통한다."},{"x":0.06,"y":0.37,"w":0.24,"h":0.06,"say":"왼쪽 열이 과제 이름이에요."},{"x":0.28,"y":0.37,"w":0.36,"h":0.06,"say":"가운데 주황 상자가 인코더가 읽는 것이에요."},{"x":0.64,"y":0.37,"w":0.3,"h":0.06,"say":"오른쪽 초록 상자가 디코더가 쓰는 것이에요."},{"x":0.06,"y":0.44,"w":0.88,"h":0.3,"say":"다섯 줄: 번역, 요약, 대화, 음성 인식, 코드 생성이에요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 기억해야 될 건 시퀀스 투 시퀀스는 개별 태스크가 아니라 인코더 디코더를 갖는 공통 패턴의 프레임워크라는 점이에요.","교수님: 입력과 출력이 꼭 같은 모달리티일 필요는 없어요."]}],"pass4":[{"kind":"check","q":"다음 중 seq2seq 로 풀 수 있는 과제가 아닌 것은?","choices":["이미지 한 장을 고양이인지 개인지 분류하기","긴 문서를 요약하기","소리를 글로 받아쓰기","자연어 설명으로 코드 만들기"],"a":0,"why":"분류는 출력이 시퀀스가 아니라 칸 하나예요. 나머지 셋은 출력이 시퀀스라서 seq2seq 예요."},{"kind":"english","head":"답안 문장","en":"**시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**은 입력과 출력이 모두 시퀀스인 모든 문제에 쓰이는 **인코더(Encoder)**, **디코더(Decoder)** 틀이다. 번역, 요약, 대화, 음성 인식, 코드 생성에 같은 구조가 다시 쓰인다.","ko":"과제 다섯 개를 외워 두면 나열형 문제에 그대로 써요."}]},{"p":16,"title":"정보 병목","terms":["Information Bottleneck","Encoder","Decoder","Hidden State","Attention"],"pass1":[{"kind":"say","lines":["이제 Part 1 의 결론이에요. **시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**의 진짜 약점은 **정보 병목(Information Bottleneck)**이에요.","**디코더(Decoder)**가 원문에 대해 아는 모든 것이 고정 크기 벡터 하나에 들어가야 해요."]},{"kind":"figure","head":"문장이 길어도 통로는 그대로","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"24\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">문장이 길어도 통로는 그대로<\/text><rect x=\"20\" y=\"50\" width=\"130\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"85\" y=\"68\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">20단어 문장<\/text><rect x=\"20\" y=\"140\" width=\"200\" height=\"26\" rx=\"2\" class=\"n b2\"/><text x=\"120\" y=\"158\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">200단어 문단<\/text><line x1=\"152\" y1=\"63\" x2=\"230.1\" y2=\"97.4\" class=\"e2 b3\"/><polygon points=\"236,100 230.3,93.1 227.1,100.4\" class=\"arrow b3\"/><line x1=\"222\" y1=\"153\" x2=\"234.0\" y2=\"116.1\" class=\"e2 b3\"/><polygon points=\"236,110 229.7,116.4 237.3,118.8\" class=\"arrow b3\"/><rect x=\"238\" y=\"88\" width=\"60\" height=\"30\" rx=\"2\" class=\"n4 b3\"/><text x=\"268\" y=\"108\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b3\">512칸<\/text><line x1=\"300\" y1=\"103\" x2=\"333.6\" y2=\"103.0\" class=\"e2 b4\"/><polygon points=\"340,103 332.0,99.0 332.0,107.0\" class=\"arrow b4\"/><rect x=\"342\" y=\"82\" width=\"120\" height=\"42\" rx=\"2\" class=\"box2 b4\"/><text x=\"402\" y=\"108\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">디코더<\/text><text x=\"240\" y=\"196\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">칸 수가 같으니 긴 문장일수록 더 많이 버려요<\/text><text x=\"240\" y=\"222\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">성능이 문장 길이에 따라 무너지는 이유예요<\/text><\/svg>","caption":"20단어든 200단어든 같은 칸 수의 벡터를 지나가야 해요.","builds":4},{"kind":"analogy","head":"좁은 문 하나","scene":"큰 강당에 사람이 20명이든 200명이든, 나가는 문은 똑같이 하나뿐이에요. 사람이 많을수록 더 많이 밀리고 못 나가는 사람이 생겨요.","map":[["강당 안 사람 수","입력 문장의 길이"],["문 하나","고정 크기 요약 벡터"],["못 나간 사람","버려진 정보"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Everything the decoder knows about the source has to fit in one fixed-size vector","디코더가 원문에 대해 아는 모든 것이 고정 크기 벡터 하나에 들어가야 한다"],["A 20-word sentence and a 200-word paragraph get the same number of dimensions","20단어 문장과 200단어 문단이 같은 개수의 차원을 받는다"],["performance duly collapses as sentences get longer","문장이 길어질수록 성능이 그대로 무너진다"],["stop forcing the decoder to use only that vector","디코더가 그 벡터만 쓰도록 강요하지 말자"]]},{"kind":"points","head":"fixed-size 라는 말","items":["fixed-size vector 는 '칸 수가 정해진 벡터' 예요. 예를 들어 512칸이면 언제나 512칸이에요.","입력이 길어져도 칸이 늘지 않아요. 그래서 긴 입력일수록 더 많이 버려야 해요."]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 줄: 디코더가 아는 모든 것이 고정 크기 벡터 하나에 들어가야 한다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.09,"say":"둘째 줄: 20단어든 200단어든 차원이 같아서 길면 성능이 무너진다."},{"x":0.05,"y":0.33,"w":0.9,"h":0.06,"say":"셋째 줄: 해결은 거의 자명하다. 그 벡터만 쓰도록 강요하지 않는 것."},{"x":0.09,"y":0.46,"w":0.26,"h":0.1,"say":"빨간 글씨: 하나의 고정 벡터가 원문 전체를 날라야 한다는 경고예요."},{"x":0.33,"y":0.56,"w":0.08,"h":0.09,"say":"빨간 느낌표 자리가 바로 병목이에요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 인코더는 굉장히 많은 정보를 갖고 있는데, 디코더로 전달되는 통로가 딱 하나의 고정 크기 벡터라는 게 정보 병목의 가장 큰 문제예요.","교수님: 입력이 짧으면 어느 정도 되겠지만, 문장이 길어질수록 기억해야 할 정보가 훨씬 많아져요.","교수님: 이걸 해결하기 위해서 **어텐션(Attention)**이라는 기법을 배워 보겠습니다."]}],"pass4":[{"kind":"exam","src":"N4 Check Yourself","q":"Q1. Why does a fixed-size encoder vector hurt long sentences more than short ones?","qko":"고정 크기 인코더 벡터는 왜 짧은 문장보다 긴 문장에서 더 해로운가?","solve":["입력이 10단어든 1000단어든 디코더로 가는 통로는 같은 크기의 벡터 하나예요","긴 문장일수록 담아야 할 정보(등장인물, 단어 뜻, 문장 구조)가 훨씬 많아요","칸 수는 그대로인데 담을 게 늘어나니 잃어버리는 정보가 커져요","그래서 문장이 길어질수록 번역 성능이 급격히 떨어져요"],"answer":"입력 길이와 상관없이 통로가 같은 크기라서, 긴 문장일수록 압축 과정에서 잃는 정보가 커지기 때문이다."},{"kind":"english","head":"답안 문장","en":"**시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**에서 **인코더(Encoder)**의 정보는 고정 크기 벡터 하나로만 **디코더(Decoder)**에 전달된다. 그래서 문장이 길어질수록 압축 손실이 커지는 **정보 병목(Information Bottleneck)**이 생긴다.","ko":"'고정 크기 + 유일한 통로 + 길수록 손실' 세 조각을 꼭 넣어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**정보 병목(Information Bottleneck)**은 파라미터가 부족해서 생기는 문제가 아니에요. 통로의 크기가 입력 길이에 따라 늘지 않는 게 문제예요."]}]},{"p":17,"title":"Part 2 구분 슬라이드: Attention","terms":["Attention","Encoder","Decoder"],"pass1":[{"kind":"say","lines":["Part 2 가 시작돼요. 제목은 **어텐션(Attention)**이에요.","부제 'let the decoder look back at the source, at every step' 은 '**디코더(Decoder)**가 매 단계마다 원문을 다시 보게 하자' 라는 뜻이에요.","오늘 수업의 메인이에요."]}],"pass2":[],"pass3":[],"pass4":[]},{"p":18,"title":"어텐션의 핵심 아이디어","terms":["Attention","Encoder","Decoder","Hidden State","Information Bottleneck","Context Vector"],"pass1":[{"kind":"say","lines":["생각은 아주 단순해요. **디코더(Decoder)**가 한 단어를 만들 때마다 **인코더(Encoder)**의 **은닉 상태(Hidden State)**를 전부 다시 봐요.","그리고 그중 지금 필요한 것에 더 무게를 둬요."]},{"kind":"figure","head":"어텐션의 그림","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">디코더가 매 단계마다 입력을 다시 봐요<\/text><rect x=\"20\" y=\"60\" width=\"60\" height=\"30\" rx=\"2\" class=\"n b1\"/><rect x=\"90\" y=\"60\" width=\"60\" height=\"30\" rx=\"2\" class=\"n b1\"/><rect x=\"160\" y=\"60\" width=\"60\" height=\"30\" rx=\"2\" class=\"n b1\"/><rect x=\"230\" y=\"60\" width=\"60\" height=\"30\" rx=\"2\" class=\"n b1\"/><text x=\"50\" y=\"80\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">h1<\/text><text x=\"120\" y=\"80\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">h2<\/text><text x=\"190\" y=\"80\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">h3<\/text><text x=\"260\" y=\"80\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">h4<\/text><text x=\"155\" y=\"50\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">인코더 은닉 상태 전부<\/text><rect x=\"370\" y=\"130\" width=\"70\" height=\"32\" rx=\"2\" class=\"n2 b2\"/><text x=\"405\" y=\"152\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b2\">s_t<\/text><text x=\"405\" y=\"180\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">디코더 상태<\/text><line x1=\"370\" y1=\"140\" x2=\"66.3\" y2=\"96.9\" class=\"e2 b3\"/><polygon points=\"60,96 67.4,101.1 68.5,93.2\" class=\"arrow b3\"/><line x1=\"370\" y1=\"142\" x2=\"136.3\" y2=\"97.2\" class=\"e b3\"/><polygon points=\"130,96 137.1,101.4 138.6,93.6\" class=\"arrow b3\"/><line x1=\"370\" y1=\"144\" x2=\"206.2\" y2=\"97.7\" class=\"e b3\"/><polygon points=\"200,96 206.6,102.0 208.8,94.3\" class=\"arrow b3\"/><line x1=\"370\" y1=\"146\" x2=\"275.7\" y2=\"98.9\" class=\"e b3\"/><polygon points=\"270,96 275.4,103.2 278.9,96.0\" class=\"arrow b3\"/><text x=\"150\" y=\"122\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">점수를 매기고<\/text><rect x=\"20\" y=\"196\" width=\"270\" height=\"26\" rx=\"2\" class=\"box2 b4\"/><text x=\"155\" y=\"214\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">문맥 벡터 c_t = 가중합<\/text><text x=\"395\" y=\"214\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">다음 단어 예측<\/text><line x1=\"292\" y1=\"209\" x2=\"323.6\" y2=\"209.0\" class=\"e2 b4\"/><polygon points=\"330,209 322.0,205.0 322.0,213.0\" class=\"arrow b4\"/><\/svg>","caption":"디코더 상태가 인코더 상태 전부를 훑어보고, 필요한 만큼 섞어서 문맥 벡터를 만들어요.","builds":4},{"kind":"analogy","head":"시험 볼 때 교과서 다시 펼치기","scene":"요약 노트 한 장만 들고 시험을 보는 대신, 문제마다 교과서를 펼쳐 필요한 쪽만 다시 읽는 거예요.","map":[["요약 노트 한 장","고정 크기 요약 벡터"],["문제마다 교과서를 펼침","매 디코딩 단계마다 인코더 상태 전부를 다시 봄"],["필요한 쪽만 더 오래 읽음","관련 있는 자리에 큰 가중치"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["At every decoder step, look at all the encoder states","디코더의 매 단계마다 모든 인코더 상태를 본다"],["and decide which ones matter right now","그리고 지금 어떤 것이 중요한지 정한다"],["The decoder no longer depends on one summary vector","디코더가 더 이상 요약 벡터 하나에 매이지 않는다"],["it builds a fresh summary at every step","매 단계마다 새 요약을 만든다"],["Direct connections from every output step to every input word","모든 출력 단계에서 모든 입력 단어로 직접 연결"]]},{"kind":"points","head":"무엇이 달라졌나요","items":["전: **인코더(Encoder)**의 마지막 상태 하나만 **디코더(Decoder)**에게 갔어요","후: 자리마다의 **은닉 상태(Hidden State)**를 전부 남겨 두고, 매 단계 필요한 만큼 골라요","그래서 매 단계마다 서로 다른 **문맥 벡터(Context Vector)**가 새로 만들어져요"]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.07,"say":"첫 점: 매 디코더 단계마다 모든 인코더 상태를 보고 무엇이 중요한지 정한다."},{"x":0.05,"y":0.28,"w":0.9,"h":0.09,"say":"둘째 점: 요약 벡터 하나에 매이지 않고 매 단계마다 새 요약을 만든다."},{"x":0.05,"y":0.86,"w":0.9,"h":0.06,"say":"맨 아래: 모든 출력 단계에서 모든 입력 단어로 가는 직접 연결."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 디코더가 단어를 하나하나 생성할 때마다 인코더의 모든 은닉 상태를 다시 바라봅니다.","교수님: '나는 너를 사랑해' 에서 '너를' 을 만들 때는 you 에 더 강하게 걸려야 해요.","교수님: 두 번째 토큰이라서 두 번째가 높은 게 아니에요. 지금 만드는 토큰과 관련 있는 자리가 높아요."]}],"pass4":[{"kind":"check","q":"어텐션이 붙으면 디코더가 보는 것은?","choices":["인코더의 모든 자리 은닉 상태","인코더의 마지막 상태 하나","입력 문장의 글자 그대로","어휘 목록"],"a":0,"why":"슬라이드: look at all the encoder states. 마지막 하나가 아니라 전부예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**어텐션(Attention)**이 **RNN(순환 신경망)**을 없앤 것은 아니에요. 2015년 구조에서는 인코더와 디코더가 여전히 RNN 이에요."]}]},{"p":19,"title":"어텐션은 가중 평균이에요","terms":["Context Vector","Attention Weight","Weighted Sum","Hidden State","Attention"],"pass1":[{"kind":"say","lines":["**어텐션(Attention)**이 실제로 만들어 내는 결과물은 **문맥 벡터(Context Vector)** 하나예요.","이것은 **인코더(Encoder)** **은닉 상태(Hidden State)**들의 **가중합(Weighted Sum)**이에요. 가중치의 합이 1 이니 가중 평균이에요."]},{"kind":"analogy","head":"성적의 가중 평균","scene":"과목마다 학점이 다르면 그냥 평균이 아니라 학점을 곱해서 더해요. 중요한 과목이 성적에 더 많이 반영되죠.","map":[["과목 점수","인코더 은닉 상태 h_i"],["과목 학점 비중","어텐션 가중치 알파_i"],["최종 평점","**문맥 벡터(Context Vector)**"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["a weighted average of the encoder states = 인코더 상태들의 가중 평균","the weights are computed on the fly = 가중치는 그때그때 즉석에서 계산된다","and sum to one = 그리고 다 더하면 1 이다","Sharp weights = 'look here' = 날카로운 가중치는 '여기를 봐라'","Flat weights = 'everything matters a little' = 평평한 가중치는 '다 조금씩 중요하다'"]},{"kind":"compare","head":"날카로운 분포와 평평한 분포","cols":["모양","뜻","언제 나오나"],"rows":[["날카롭다","한 자리에 거의 다 몰린다","지금 만들 단어가 특정 원문 단어와 딱 짝일 때"],["평평하다","여러 자리를 조금씩 본다","여러 정보가 조금씩 필요할 때"],["전부 같다","그냥 평균 내기(mean pooling)","학습이 안 된 것과 같아요. 어텐션의 힘이 없어요"]]}],"pass3":[{"kind":"steps","head":"가중 평균을 손으로 계산해 봐요","given":"h1 ... h4 와 가중치 0.62, 0.14, 0.12, 0.12","steps":["인코더 상태 네 개를 2칸짜리로 두면 h1 = (3.0, 0.3), h2 = (0.4, 0.2), h3 = (0.1, 0.2), h4 = (0.2, 0.1)","슬라이드의 가중치는 0.62, 0.14, 0.12, 0.12 이고 합은 1.00 이에요","첫 칸: 0.62 x 3.0 + 0.14 x 0.4 + 0.12 x 0.1 + 0.12 x 0.2 = 1.952","둘째 칸: 0.62 x 0.3 + 0.14 x 0.2 + 0.12 x 0.2 + 0.12 x 0.1 = 0.25","가중치를 전부 0.25 로 두면(그냥 평균) 첫 칸은 0.925 밖에 안 돼요"],"answer":"문맥 벡터 = (1.952, 0.25). 가중치를 학습하면 h1 쪽으로 훨씬 가깝게 당겨져요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.09,"say":"첫 점: 어텐션은 문맥 벡터를 만들고, 가중치는 즉석에서 계산되며 합이 1 이다."},{"x":0.05,"y":0.29,"w":0.9,"h":0.06,"say":"둘째 점: 날카로우면 '여기를 봐라', 평평하면 '다 조금씩 중요하다'."},{"x":0.1,"y":0.44,"w":0.72,"h":0.11,"say":"파란 막대와 숫자 0.62, 0.14, 0.12, 0.12 가 어텐션 가중치예요."},{"x":0.21,"y":0.55,"w":0.62,"h":0.2,"say":"주황 상자 네 개가 인코더 상태(il, a, m', entarte)예요."},{"x":0.83,"y":0.55,"w":0.16,"h":0.2,"say":"오른쪽 파란 상자가 문맥 벡터. 인코더 상태 하나와 같은 모양이에요."},{"x":0.22,"y":0.78,"w":0.56,"h":0.06,"say":"아래 글: 균등 가중치는 평균 풀링(약함), 학습된 가중치가 어텐션(강함)."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 컨텍스트 벡터는 인코더 은닉 상태들을 그냥 평균 낸 게 아니라, 중요도를 구해서 그 가중치를 곱해 더한 가중 평균이에요.","교수님: 이 가중치는 디코딩 스텝마다 계속 바뀌어요. 이 합은 1 이겠죠.","교수님: 한 곳에 크게 몰리면 그 토큰에 집중하면 되겠다는 뜻이고, 유니폼하면 여러 정보가 조금씩 필요하다는 뜻이에요."]}],"pass4":[{"kind":"check","q":"문맥 벡터의 모양(칸 수)은?","choices":["인코더 은닉 상태 하나와 같다","인코더 상태 개수와 같다","어휘 크기와 같다","항상 1이다"],"a":0,"why":"가중 평균이니까 섞이는 벡터와 칸 수가 같아요. 슬라이드도 same shape as one encoder state 라고 적었어요."},{"kind":"english","head":"답안 문장","en":"**어텐션(Attention)**의 **문맥 벡터(Context Vector)**는 인코더 은닉 상태들의 가중 평균이며, 가중치는 디코딩 단계마다 새로 계산되고 합이 1 이다.","ko":"'가중 평균 + 단계마다 새로 + 합이 1' 세 조각을 꼭 넣어요."}]},{"p":20,"title":"비유: 소프트 딕셔너리 룩업","terms":["Query","Key","Value","Attention Weight","Attention"],"pass1":[{"kind":"say","lines":["**어텐션(Attention)**을 이해하는 가장 쉬운 비유예요. 파이썬 딕셔너리와 비교해요.","딕셔너리는 하드 룩업, **어텐션(Attention)**은 소프트 룩업이에요."]},{"kind":"figure","head":"하드 룩업과 소프트 룩업","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"120\" y=\"22\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">하드 룩업(파이썬 dict)<\/text><text x=\"360\" y=\"22\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">소프트 룩업(어텐션)<\/text><rect x=\"20\" y=\"44\" width=\"50\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"76\" y=\"44\" width=\"60\" height=\"26\" rx=\"2\" class=\"n3 b1\"/><text x=\"45\" y=\"62\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">k1<\/text><text x=\"106\" y=\"62\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">v1<\/text><rect x=\"20\" y=\"76\" width=\"50\" height=\"26\" rx=\"2\" class=\"n2 b1\"/><rect x=\"76\" y=\"76\" width=\"60\" height=\"26\" rx=\"2\" class=\"n2 b1\"/><text x=\"45\" y=\"94\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">k2<\/text><text x=\"106\" y=\"94\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">v2<\/text><rect x=\"20\" y=\"108\" width=\"50\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"76\" y=\"108\" width=\"60\" height=\"26\" rx=\"2\" class=\"n3 b1\"/><text x=\"45\" y=\"126\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">k3<\/text><text x=\"106\" y=\"126\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">v3<\/text><rect x=\"20\" y=\"140\" width=\"50\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"76\" y=\"140\" width=\"60\" height=\"26\" rx=\"2\" class=\"n3 b1\"/><text x=\"45\" y=\"158\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">k4<\/text><text x=\"106\" y=\"158\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">v4<\/text><text x=\"78\" y=\"190\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">키 하나만 맞고 값 하나만 가져와요<\/text><rect x=\"250\" y=\"44\" width=\"50\" height=\"26\" rx=\"2\" class=\"n b2\"/><rect x=\"306\" y=\"44\" width=\"60\" height=\"26\" rx=\"2\" class=\"n3 b2\"/><text x=\"275\" y=\"62\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">k1<\/text><text x=\"336\" y=\"62\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">v1<\/text><text x=\"410\" y=\"62\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">0.10<\/text><rect x=\"250\" y=\"76\" width=\"50\" height=\"26\" rx=\"2\" class=\"n b2\"/><rect x=\"306\" y=\"76\" width=\"60\" height=\"26\" rx=\"2\" class=\"n3 b2\"/><text x=\"275\" y=\"94\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">k2<\/text><text x=\"336\" y=\"94\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">v2<\/text><text x=\"410\" y=\"94\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">0.55<\/text><rect x=\"250\" y=\"108\" width=\"50\" height=\"26\" rx=\"2\" class=\"n b2\"/><rect x=\"306\" y=\"108\" width=\"60\" height=\"26\" rx=\"2\" class=\"n3 b2\"/><text x=\"275\" y=\"126\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">k3<\/text><text x=\"336\" y=\"126\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">v3<\/text><text x=\"410\" y=\"126\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">0.25<\/text><rect x=\"250\" y=\"140\" width=\"50\" height=\"26\" rx=\"2\" class=\"n b2\"/><rect x=\"306\" y=\"140\" width=\"60\" height=\"26\" rx=\"2\" class=\"n3 b2\"/><text x=\"275\" y=\"158\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">k4<\/text><text x=\"336\" y=\"158\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">v4<\/text><text x=\"410\" y=\"158\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">0.10<\/text><text x=\"330\" y=\"190\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">모든 키를 조금씩 보고 값들을 섞어요<\/text><text x=\"240\" y=\"224\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">합이 1 인 가중치로 섞은 것이 문맥 벡터예요<\/text><text x=\"240\" y=\"248\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">0.10 v1 + 0.55 v2 + 0.25 v3 + 0.10 v4<\/text><\/svg>","caption":"왼쪽은 하나만 골라 오고, 오른쪽은 전부 조금씩 섞어 와요.","builds":3},{"kind":"analogy","head":"도서관에서 책 찾기","scene":"딱 한 권만 빌려 오는 대신, 관련 있는 책 네 권을 모두 훑어보고 중요한 책을 더 오래 읽어 노트 한 장으로 정리해 오는 거예요.","map":[["찾고 싶은 주제","**쿼리(Query)**"],["책등에 붙은 제목","**키(Key)**"],["책 속 내용","**밸류(Value)**"],["정리한 노트 한 장","**문맥 벡터(Context Vector)**"]]}],"pass2":[{"kind":"points","head":"세 낱말을 한 줄씩","items":["**쿼리(Query)**: 내가 지금 무엇을 찾고 있는가","**키(Key)**: 나는 이런 정보를 갖고 있다고 광고하는 이름표","**밸류(Value)**: 내가 선택되면 실제로 건네줄 내용","슬라이드 맨 아래: Query, key, value, remember these three words, they run the rest of today"]},{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["A Python dict does a hard lookup: one key matches, you get one value","파이썬 dict 는 하드 룩업이다. 키 하나가 맞고 값 하나를 얻는다"],["Attention does a soft lookup","어텐션은 소프트 룩업을 한다"],["the query matches every key to some degree","쿼리가 모든 키와 어느 정도씩 맞는다"],["and you get a blend of all the values","그리고 모든 값을 섞은 것을 얻는다"]]}],"pass3":[{"kind":"steps","head":"슬라이드 오른쪽 숫자를 그대로 읽어 봐요","steps":["가중치가 v1 0.10, v2 0.55, v3 0.25, v4 0.10 이라고 적혀 있어요","다 더하면 0.10 + 0.55 + 0.25 + 0.10 = 1.00 이에요","가장 큰 것은 0.55 인 v2 예요(딕셔너리였다면 v2 만 가져왔겠죠)","그런데 어텐션은 v1, v3, v4 도 버리지 않아요","결과 = 0.10 v1 + 0.55 v2 + 0.25 v3 + 0.10 v4"],"answer":"가장 관련 있는 것을 제일 많이, 나머지도 조금씩 섞어 와요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 점: 파이썬 dict 는 키 하나가 맞고 값 하나를 준다(하드 룩업)."},{"x":0.05,"y":0.25,"w":0.9,"h":0.06,"say":"둘째 점: 어텐션은 모든 키와 어느 정도씩 맞고 값들을 섞어 준다(소프트 룩업)."},{"x":0.07,"y":0.42,"w":0.28,"h":0.3,"say":"왼쪽 표: k2 와 v2 만 빨간 테두리로 골라져 있어요."},{"x":0.43,"y":0.42,"w":0.5,"h":0.3,"say":"오른쪽 표: 네 칸 모두 살아 있고 오른쪽에 가중치가 붙어 있어요."},{"x":0.24,"y":0.86,"w":0.52,"h":0.06,"say":"맨 아래: 쿼리, 키, 밸류 세 낱말을 기억하라는 안내예요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 일반적인 파이썬 딕셔너리는 키를 넣으면 정확히 일치하는 키 하나를 찾고 값 하나를 가져와요.","교수님: 어텐션은 쿼리가 모든 키와 얼마나 비슷한지 점수를 계산하고, 그 점수를 가중치로 바꿔요.","교수님: k2 가 0.55 로 가장 높지만 k1, k3, k4 를 버리는 게 아니라 각각 조금씩 가중치를 받아요.","교수님: 이 세 개의 컨셉을 이해해야 뒤에 트랜스포머를 이해할 수 있고 자연어 처리를 이해할 수 있어요."]}],"pass4":[{"kind":"check","q":"소프트 룩업과 하드 룩업의 차이로 가장 알맞은 것은?","choices":["하드는 값 하나를 그대로, 소프트는 모든 값을 가중치로 섞어 준다","하드는 느리고 소프트는 빠르다","하드는 학습되고 소프트는 학습되지 않는다","하드는 벡터를 쓰고 소프트는 숫자를 쓴다"],"a":0,"why":"슬라이드: one key matches, you get one value 대 a blend of all the values."},{"kind":"english","head":"답안 문장","en":"**어텐션(Attention)**은 **쿼리(Query)**가 모든 **키(Key)**와 얼마나 맞는지를 점수로 재고, 그 점수를 합이 1 인 가중치로 바꾼 뒤 **밸류(Value)**들을 섞어 주는 소프트 룩업이다.","ko":"'하드 룩업(dict) 대 소프트 룩업(attention)' 대비로 쓰면 깔끔해요."}]},{"p":21,"title":"1단계: 모든 인코더 상태에 점수 매기기","terms":["Attention Score","Dot Product","Hidden State","Decoder","Encoder"],"pass1":[{"kind":"say","lines":["**어텐션(Attention)**은 세 단계예요. 첫 단계는 점수 매기기예요.","지금 **디코더(Decoder)** 상태 s 를 인코더 상태 h 하나하나와 비교해 **어텐션 점수(Attention Score)**를 만들어요.","가장 단순한 방법이 **내적(Dot Product)**예요."]}],"pass2":[{"kind":"formula","head":"1단계 점수 식","tex":"e^{(t)}_i = s_t^{\\top} h_i \\in \\mathbb{R}","parts":[{"sym":"e^{(t)}_i","say":"디코딩 t 단계에서 i 번째 인코더 자리에 준 점수"},{"sym":"s_t","say":"지금 디코더의 상태 벡터. 무엇을 찾는지를 담고 있어요"},{"sym":"h_i","say":"i 번째 인코더 자리의 은닉 상태"},{"sym":"s_t^{\\top} h_i","say":"두 벡터의 내적. 같은 자리끼리 곱해서 모두 더해요"},{"sym":"\\in \\mathbb{R}","say":"결과는 실수 하나예요. 벡터가 아니에요"}],"whole":"입력 단어 하나당 숫자 하나가 나오고, 디코딩 단계마다 다시 계산해요."},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Take the current decoder state s and score it against every encoder state h = 지금 디코더 상태로 모든 인코더 상태에 점수를 매긴다","The simplest score is a dot product = 가장 단순한 점수는 내적이다","A large score means 'this source word is relevant to what I am about to say' = 점수가 크면 그 원문 단어가 지금 말하려는 것과 관련 있다는 뜻","One number per source word, recomputed at every decoder step = 원문 단어마다 숫자 하나, 디코더 단계마다 다시 계산"]}],"pass3":[{"kind":"steps","head":"슬라이드의 점수를 손으로 만들어 봐요","given":"s = (1, 2), h1 ... h4 는 위와 같음","steps":["칸이 두 개뿐인 아주 작은 예로 해 봐요. 디코더 상태 s = (1, 2)","인코더 상태 h1 = (3.0, 0.3), h2 = (0.4, 0.2), h3 = (0.1, 0.2), h4 = (0.2, 0.1)","e1 = 1 x 3.0 + 2 x 0.3 = 3.0 + 0.6 = 3.6","e2 = 1 x 0.4 + 2 x 0.2 = 0.4 + 0.4 = 0.8","e3 = 1 x 0.1 + 2 x 0.2 = 0.1 + 0.4 = 0.5","e4 = 1 x 0.2 + 2 x 0.1 = 0.2 + 0.2 = 0.4"],"answer":"점수 (3.6, 0.8, 0.5, 0.4). 슬라이드에 적힌 숫자와 똑같아요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 점: 지금 디코더 상태로 모든 인코더 상태에 점수를 매긴다. 가장 단순한 건 내적."},{"x":0.05,"y":0.25,"w":0.9,"h":0.06,"say":"둘째 점: 큰 점수는 지금 말하려는 것과 관련 있다는 뜻."},{"x":0.2,"y":0.36,"w":0.2,"h":0.06,"say":"scores e_i = s_t^T h_i 라고 식이 적혀 있어요."},{"x":0.2,"y":0.45,"w":0.42,"h":0.09,"say":"숫자 3.6, 0.8, 0.5, 0.4 가 네 자리의 점수예요."},{"x":0.63,"y":0.5,"w":0.14,"h":0.14,"say":"오른쪽 초록 상자가 디코더 상태 s_t 예요."},{"x":0.24,"y":0.73,"w":0.4,"h":0.07,"say":"encoder states h1 ... hN 이라고 묶어 놓았어요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 다 프로덕트, 곧 내적을 한다는 말은 s_t 와 h_i 가 얼마나 비슷한지를 보는 거예요.","교수님: 3.6 이 가장 높다는 건 지금 디코더 상태가 첫 번째 토큰과 가장 비슷하다는 뜻이에요.","교수님: 이 점수를 관련도 점수, 셀리언스 스코어, 어텐션 스코어라고 부르는데 다 같은 말이에요."]},{"kind":"bg","src":"기초 다지기 2단원","lines":["**내적(Dot Product)**은 같은 자리끼리 곱해서 모두 더하는 계산이에요. (1,2)와 (3,0.3)의 내적은 1x3 + 2x0.3 = 3.6 이에요.","두 화살표가 같은 쪽을 볼수록 값이 커져요."]}],"pass4":[{"kind":"check","q":"s = (2, 1), h = (1, 3) 일 때 점수는?","choices":["5","6","3","2"],"a":0,"why":"2x1 + 1x3 = 5 예요. 같은 자리끼리 곱해서 더해요."},{"kind":"english","head":"답안 문장","en":"어텐션 1단계는 디코더 상태 s_t 와 각 인코더 상태 h_i 의 **내적(Dot Product)**으로 **어텐션 점수(Attention Score)** e_i 를 구하는 것이며, 원문 단어마다 숫자 하나가 나오고 디코딩 단계마다 다시 계산된다.","ko":"'내적 + 단어마다 숫자 하나 + 매 단계 재계산' 을 기억해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**어텐션 점수(Attention Score)**는 아직 확률이 아니에요. 합이 1 도 아니고 음수도 될 수 있어요. 확률로 바꾸는 것이 2단계예요."]}]},{"p":22,"title":"2단계: 소프트맥스로 분포 만들기","terms":["Softmax","Attention Distribution","Attention Weight","Attention Score"],"pass1":[{"kind":"say","lines":["점수는 그냥 숫자라서 '얼마나 볼지' 로 쓸 수 없어요. 합이 1 이 되게 만들어야 해요.","우리가 아는 방법은 하나뿐이에요. **소프트맥스(Softmax)**예요."]},{"kind":"analogy","head":"표를 득표율로 바꾸기","scene":"후보들이 받은 표 개수는 그냥 숫자예요. 이것을 전체로 나눠 퍼센트로 바꾸면 비교하기 좋아지죠.","map":[["표 개수","**어텐션 점수(Attention Score)**"],["퍼센트로 바꾸기","**소프트맥스(Softmax)**"],["득표율 표","**어텐션 분포(Attention Distribution)**"]]}],"pass2":[{"kind":"formula","head":"2단계 소프트맥스","tex":"\\alpha^{(t)} = \\mathrm{softmax}\\!\\left(e^{(t)}\\right) \\in \\mathbb{R}^{N}","parts":[{"sym":"e^{(t)}","say":"1단계에서 구한 점수들을 한 줄로 모은 것"},{"sym":"\\mathrm{softmax}","say":"각 점수에 exp 를 씌우고 전체 합으로 나눠요"},{"sym":"\\alpha^{(t)}","say":"결과가 **어텐션 분포(Attention Distribution)**예요. 각 칸이 **어텐션 가중치(Attention Weight)**"},{"sym":"\\mathbb{R}^{N}","say":"N 은 입력 문장의 자리 수예요. 자리마다 가중치가 하나씩"}],"whole":"결과는 모두 0 과 1 사이이고, 다 더하면 정확히 1 이에요."},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Softmax turns the raw scores into a probability distribution = 소프트맥스가 날것 점수를 확률 분포로 바꾼다","over the source positions = 원문의 자리들에 대하여","this is the attention distribution = 이것이 어텐션 분포다","It sums to one, so it really is 'how much of my attention goes where' = 합이 1 이니 정말로 '내 주의가 어디로 얼마나 가는지' 다"]}],"pass3":[{"kind":"steps","head":"소프트맥스를 손으로 계산해 봐요","given":"점수 (3.6, 0.8, 0.5, 0.4)","steps":["점수는 앞에서 구한 (3.6, 0.8, 0.5, 0.4) 예요","각 점수에 exp 를 씌워요: exp(3.6) = 36.60, exp(0.8) = 2.23, exp(0.5) = 1.65, exp(0.4) = 1.49","다 더하면 36.60 + 2.23 + 1.65 + 1.49 = 41.96","각각을 합으로 나눠요: 36.60 / 41.96 = 0.872","나머지는 2.23 / 41.96 = 0.053, 1.65 / 41.96 = 0.039, 1.49 / 41.96 = 0.036","반올림하면 0.87, 0.05, 0.04, 0.04 이고 합은 1 이에요"],"answer":"어텐션 분포 = (0.87, 0.05, 0.04, 0.04). 슬라이드 숫자와 같아요."},{"kind":"steps","head":"점수를 키우거나 줄이면 어떻게 될까요","steps":["같은 점수에 0.4 를 곱해서 (1.44, 0.32, 0.20, 0.16) 으로 줄이면","가장 큰 가중치가 0.53 으로 내려가요. 분포가 평평해져요","반대로 3 을 곱해서 (10.8, 2.4, 1.5, 1.2) 로 키우면","가장 큰 가중치가 0.9996 까지 올라가요. 거의 한 칸만 보게 돼요","점수의 크기(스케일)가 분포의 날카로움을 결정해요"],"answer":"이 성질이 Part 3 에서 루트 d_k 로 나누는 이유가 돼요. 미리 기억해 둬요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 점: 소프트맥스가 점수를 원문 자리들에 대한 확률 분포로 바꾼다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.06,"say":"둘째 점: 합이 1 이니 주의가 어디로 가는지를 그대로 읽을 수 있다."},{"x":0.18,"y":0.34,"w":0.4,"h":0.14,"say":"위쪽 파란 막대와 0.87, 0.05, 0.04, 0.04 가 어텐션 분포예요."},{"x":0.2,"y":0.53,"w":0.42,"h":0.1,"say":"아래쪽 3.6, 0.8, 0.5, 0.4 는 1단계의 점수예요."},{"x":0.24,"y":0.76,"w":0.52,"h":0.08,"say":"식 알파 = softmax(e) 가 이 쪽의 핵심이에요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 3.6, 0.8 이런 건 합이 1 이 아니잖아요. 1 로 만들어 주는 방법을 소프트맥스로 해요.","교수님: 첫 번째가 3.6 이라 소프트맥스 값이 0.87 로 가장 커요.","교수님: 소프트맥스가 단순한 점수를 상대적인 중요도 분포로 바꿔 준다는 게 2단계예요."]},{"kind":"bg","src":"기초 다지기 6단원","lines":["**소프트맥스(Softmax)**는 exp 를 씌워 모두 양수로 만든 뒤 전체 합으로 나눠요.","그래서 결과가 항상 0 보다 크고 다 더하면 1 이 돼요."]}],"pass4":[{"kind":"exam","src":"N4 Check Yourself","q":"Q4 (일부). Which of the four attention equations makes the weights sum to 1?","qko":"어텐션 네 식 중 가중치의 합을 1 로 만들어 주는 것은?","solve":["1단계는 점수를 만들 뿐 합이 1 이 아니에요","2단계 **소프트맥스(Softmax)**가 exp 를 씌우고 전체 합으로 나눠요","그래서 결과가 모두 0 과 1 사이이고 합이 정확히 1 이 돼요","3단계는 그 가중치로 가중합을 할 뿐이에요"],"answer":"두 번째 식, 곧 소프트맥스로 정규화하는 단계."},{"kind":"check","q":"점수를 전부 3배로 키우면 어텐션 분포는?","choices":["더 날카로워진다(한 곳에 몰린다)","더 평평해진다","그대로다","합이 3이 된다"],"a":0,"why":"exp 때문에 차이가 훨씬 커져요. 최대 가중치가 0.87 에서 0.9996 으로 올라가요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**어텐션 점수(Attention Score)**와 **어텐션 가중치(Attention Weight)**는 다른 것이에요. 점수는 소프트맥스 전, 가중치는 소프트맥스 후예요."]}]},{"p":23,"title":"3단계: 가중합을 만들고 예측하기","terms":["Context Vector","Weighted Sum","Attention Weight","Decoder","tanh","Softmax"],"pass1":[{"kind":"say","lines":["마지막 단계예요. 각 인코더 상태에 가중치를 곱해서 모두 더해요.","그 결과가 **문맥 벡터(Context Vector)** c_t 예요.","그다음 **디코더(Decoder)** 상태와 나란히 붙여서(concat) 다음 단어를 예측해요."]},{"kind":"analogy","head":"영양제 섞기","scene":"네 가지 원료를 정해진 비율로 섞어 한 병을 만들어요. 비율이 달라지면 나오는 맛도 달라지죠.","map":[["원료 네 가지","인코더 상태 h1 ... h4"],["섞는 비율","어텐션 가중치 알파"],["완성된 한 병","**문맥 벡터(Context Vector)**"]]}],"pass2":[{"kind":"formula","head":"3단계 가중합","tex":"c_t = \\sum_{i=1}^{N} \\alpha^{(t)}_i h_i \\in \\mathbb{R}^{h}","parts":[{"sym":"\\alpha^{(t)}_i","say":"2단계에서 구한 i 번째 어텐션 가중치"},{"sym":"h_i","say":"i 번째 인코더 은닉 상태"},{"sym":"\\sum_{i=1}^{N}","say":"모든 자리에 대해 곱한 것을 더해요"},{"sym":"c_t","say":"결과인 **문맥 벡터(Context Vector)**"},{"sym":"\\mathbb{R}^{h}","say":"칸 수가 인코더 상태 하나와 같아요"}],"whole":"가중치가 큰 자리의 내용이 많이 들어가요."},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Multiply each encoder state by its weight and add them up = 각 인코더 상태에 그 가중치를 곱하고 더한다","that is the context vector = 그것이 문맥 벡터다","Concatenate it with the decoder state = 디코더 상태와 이어 붙인다","and predict the next word from the pair = 그 둘로 다음 단어를 예측한다","Three steps, and the bottleneck is gone = 세 단계면 병목이 사라진다"]}],"pass3":[{"kind":"steps","head":"문맥 벡터를 손으로 만들어 봐요","given":"가중치 (0.872, 0.053, 0.039, 0.036)","steps":["가중치는 (0.872, 0.053, 0.039, 0.036), 상태는 h1 = (3.0, 0.3) 등이에요","첫 칸: 0.872 x 3.0 + 0.053 x 0.4 + 0.039 x 0.1 + 0.036 x 0.2","= 2.616 + 0.021 + 0.004 + 0.007 = 2.648","둘째 칸: 0.872 x 0.3 + 0.053 x 0.2 + 0.039 x 0.2 + 0.036 x 0.1","= 0.262 + 0.011 + 0.008 + 0.004 = 0.284"],"answer":"문맥 벡터 c_t = (2.648, 0.284). h1 에 가중치가 몰려서 h1 과 거의 같은 쪽을 봐요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 점: 각 인코더 상태에 가중치를 곱하고 더하면 그것이 문맥 벡터."},{"x":0.05,"y":0.25,"w":0.9,"h":0.06,"say":"둘째 점: 디코더 상태와 이어 붙여서 다음 단어를 예측한다."},{"x":0.68,"y":0.33,"w":0.2,"h":0.09,"say":"오른쪽 위 concat [c_t; s_t] 라는 표시예요."},{"x":0.68,"y":0.44,"w":0.2,"h":0.13,"say":"he 라는 예측 결과가 나와요."},{"x":0.66,"y":0.57,"w":0.22,"h":0.11,"say":"파란 상자 context c_t 가 3단계의 결과물이에요."},{"x":0.4,"y":0.74,"w":0.3,"h":0.1,"say":"식 c_t = 합(알파_i h_i) 가 이 쪽의 핵심이에요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 마지막 3단계는 알파에다가 h 를 곱해서 가중치 합을 하는 거예요.","교수님: 첫 번째 가중치가 0.87 이면 이 **문맥 벡터(Context Vector)**에는 첫 번째 원문 정보가 87퍼센트만큼 담겨 있다고 보면 돼요.","교수님: 문맥 벡터로 어떻게 예측하는지는 설계의 문제예요. **하이퍼볼릭 탄젠트(tanh)**를 한 번 더 쓰기도 해요. 위의 세 개가 중요해요."]}],"pass4":[{"kind":"check","q":"가중치가 (0.87, 0.05, 0.04, 0.04) 일 때 문맥 벡터에 가장 많이 담기는 것은?","choices":["h1","h2","h3","h4"],"a":0,"why":"가중치가 가장 큰 자리의 내용이 가장 많이 들어가요."},{"kind":"english","head":"답안 문장","en":"어텐션은 점수 계산, **소프트맥스(Softmax)** 정규화, **가중합(Weighted Sum)**의 세 단계로 **문맥 벡터(Context Vector)**를 만든다. 이를 디코더 상태와 이어 붙여 다음 토큰을 예측하므로 **정보 병목(Information Bottleneck)**이 사라진다.","ko":"세 단계 이름을 순서대로 쓰는 것이 채점 포인트예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**문맥 벡터(Context Vector)**는 가중치들이 아니라 벡터예요. 가중치는 숫자 N 개, 문맥 벡터는 은닉 상태와 같은 칸 수의 벡터예요."]}]},{"p":24,"title":"어텐션의 네 식","terms":["Attention Score","Attention Distribution","Context Vector","Softmax","tanh"],"pass1":[{"kind":"say","lines":["이 쪽이 Part 2 에서 가장 중요한 쪽이에요.","Score, normalise, mix, predict. 점수, 정규화, 섞기, 예측 네 줄이에요.","오늘 남은 시간에 배우는 모든 것이 이 네 줄의 변형이에요."]},{"kind":"points","head":"네 줄을 우리말로","items":["1. 점수: 지금 상태와 각 입력 자리가 얼마나 맞는지 내적으로 재요","2. 정규화: 소프트맥스로 합이 1 인 가중치로 바꿔요","3. 섞기: 그 가중치로 인코더 상태를 가중합해서 문맥 벡터를 만들어요","4. 예측: 문맥 벡터와 디코더 상태를 함께 써서 다음 단어를 고릅니다"]}],"pass2":[{"kind":"formula","head":"1번과 2번","tex":"e^{(t)}_i = s_t^{\\top} h_i \\in \\mathbb{R}, \\qquad \\alpha^{(t)} = \\mathrm{softmax}\\!\\left(e^{(t)}\\right) \\in \\mathbb{R}^{N}","parts":[{"sym":"e^{(t)}_i","say":"자리마다 숫자 하나인 점수"},{"sym":"s_t^{\\top} h_i","say":"내적. 디코더 상태와 인코더 상태의 닮은 정도"},{"sym":"\\mathrm{softmax}","say":"합이 1 이 되게 만드는 함수"},{"sym":"\\alpha^{(t)}","say":"합이 1 인 어텐션 가중치 N 개"}],"whole":"1번은 날것 점수, 2번은 합이 1 인 분포예요."},{"kind":"formula","head":"3번과 4번","tex":"c_t = \\sum_{i=1}^{N} \\alpha^{(t)}_i h_i, \\qquad \\tilde{s}_t = \\tanh\\!\\left(W_c [c_t; s_t]\\right) \\;\\rightarrow\\; \\hat{y}_t = \\mathrm{softmax}(U \\tilde{s}_t)","parts":[{"sym":"c_t","say":"문맥 벡터. 인코더 상태들의 가중합"},{"sym":"[c_t; s_t]","say":"문맥 벡터와 디코더 상태를 위아래로 이어 붙인 것"},{"sym":"W_c","say":"이어 붙인 것을 한 번 섞어 주는 가중치 행렬"},{"sym":"\\tanh","say":"-1 과 1 사이로 눌러 주는 활성화 함수"},{"sym":"U","say":"어휘 크기만큼의 점수를 만드는 출력 가중치"},{"sym":"\\hat{y}_t","say":"다음 토큰의 확률 분포"}],"whole":"4번은 설계에 따라 바뀔 수 있어요. 교수님도 위의 세 줄이 핵심이라고 했어요."}],"pass3":[{"kind":"look","head":"슬라이드의 네 식을 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"맨 위 한 줄: Score, normalise, mix, predict. 나머지는 전부 이 네 줄의 변형이다."},{"x":0.32,"y":0.3,"w":0.34,"h":0.09,"say":"첫 식: 점수 e_i = s_t^T h_i."},{"x":0.28,"y":0.4,"w":0.42,"h":0.09,"say":"둘째 식: 알파 = softmax(e), 합이 1 인 분포."},{"x":0.32,"y":0.52,"w":0.34,"h":0.14,"say":"셋째 식: c_t = 합(알파_i h_i), 문맥 벡터."},{"x":0.14,"y":0.7,"w":0.72,"h":0.09,"say":"넷째 식: tanh 로 섞고 소프트맥스로 다음 단어를 예측."},{"x":0.28,"y":0.86,"w":0.44,"h":0.05,"say":"맨 아래: 이 식들을 Q/K/V 옷을 입고 다시 만나게 된다는 예고예요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 스코어, 노멀라이즈, 믹스, 프레딕트, 이 네 단계가 어텐션에서 가장 중요한 거다.","교수님: 첫 번째는 지금 소스 위치와 얼마나 관련 있는가를 내적으로 나타내고, 두 번째는 가중치를 구하고, 세 번째는 가중합으로 섞고, 마지막은 예측이에요.","교수님: 마지막 예측 부분은 설계의 문제라서 위의 세 개가 중요해요."]},{"kind":"bg","src":"배경 지식","lines":["[c_t; s_t] 처럼 세미콜론으로 쓴 것은 두 벡터를 세로로 이어 붙였다는 뜻이에요(concatenation).","칸이 3개인 벡터와 3개인 벡터를 이으면 6칸짜리 벡터가 돼요."]}],"pass4":[{"kind":"exam","src":"N4 Check Yourself","q":"Q4. Write the four attention equations from memory. Which one makes the weights sum to 1?","qko":"어텐션의 네 식을 외워서 쓰시오. 가중치의 합을 1 로 만드는 것은 어느 식인가?","solve":["1) 점수: e_i = s_t 와 h_i 의 내적","2) 정규화: 알파 = softmax(e)","3) 섞기: c_t = 합(알파_i h_i)","4) 예측: 문맥 벡터와 디코더 상태로 다음 토큰의 확률을 계산","합을 1 로 만드는 것은 2번, 소프트맥스 정규화 단계예요"],"answer":"네 식은 점수, 소프트맥스 정규화, 가중합, 예측이고, 합을 1 로 만드는 것은 두 번째 소프트맥스 식이다."},{"kind":"english","head":"답안 문장","en":"어텐션은 점수 계산, 소프트맥스 정규화, 가중합, 예측의 네 단계로 이루어지며, 두 번째 단계인 소프트맥스가 가중치의 합을 1 로 만든다.","ko":"네 단어 스코어, 노멀라이즈, 믹스, 프레딕트를 그대로 외워요.","tip":"영어 네 단어를 먼저 외우고 우리말을 붙이면 빨라요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드가 'Write these down' 이라고 적었어요. 교수님이 가장 강조한 쪽이니 식을 손으로 여러 번 써 봐요."]}]},{"p":25,"title":"어텐션이 우리에게 준 것 네 가지","terms":["Attention","Information Bottleneck","Gradient","Vanishing Gradient","Interpretability"],"pass1":[{"kind":"say","lines":["**어텐션(Attention)**을 붙이면 무엇이 좋아지나요. 슬라이드는 네 가지를 들어요.","성능, 병목 제거, 짧은 기울기 경로, 해석 가능성이에요."]},{"kind":"figure","head":"기울기 경로가 짧아져요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">기울기가 가야 할 길이 짧아져요<\/text><text x=\"60\" y=\"58\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">RNN<\/text><rect x=\"110\" y=\"44\" width=\"40\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"160\" y=\"44\" width=\"40\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"210\" y=\"44\" width=\"40\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"260\" y=\"44\" width=\"40\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"310\" y=\"44\" width=\"40\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"360\" y=\"44\" width=\"40\" height=\"26\" rx=\"2\" class=\"n b1\"/><line x1=\"400\" y1=\"57\" x2=\"156.4\" y2=\"57.0\" class=\"e b1\"/><polygon points=\"150,57 158.0,61.0 158.0,53.0\" class=\"arrow b1\"/><text x=\"275\" y=\"92\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">먼 곳까지 가려면 여러 걸음을 거쳐요 (길이 n)<\/text><text x=\"60\" y=\"148\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">어텐션<\/text><rect x=\"110\" y=\"134\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"360\" y=\"134\" width=\"40\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><line x1=\"360\" y1=\"147\" x2=\"158.4\" y2=\"147.0\" class=\"e2 b2\"/><polygon points=\"152,147 160.0,151.0 160.0,143.0\" class=\"arrow b2\"/><text x=\"255\" y=\"182\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">출력과 입력이 한 걸음으로 바로 이어져요 (길이 1)<\/text><line x1=\"20\" y1=\"206\" x2=\"460\" y2=\"206\" class=\"e b3\"/><text x=\"240\" y=\"230\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">곱셈 횟수가 줄어드니 기울기 소실을 비켜 가요<\/text><\/svg>","caption":"RNN 은 여러 걸음을 거쳐야 하는데, 어텐션은 한 걸음으로 이어져요.","builds":3},{"kind":"compare","head":"네 가지 이득","cols":["영어","우리말","한 줄 설명"],"rows":[["Performance","성능","어텐션을 붙이자마자 특히 긴 문장에서 크게 좋아졌어요"],["No bottleneck","병목 제거","디코더가 요약을 거치지 않고 원문을 직접 읽어요"],["Shorter gradient paths","짧은 기울기 경로","출력에서 입력으로 바로 가는 길이 생겨요"],["Interpretability","해석 가능성","가중치를 그림으로 찍으면 어디를 봤는지 보여요"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어에서 꼭 아는 표현","items":["beat NMT without it immediately = 어텐션 없는 신경망 번역을 바로 이겼다","and by a lot on long sentences = 특히 긴 문장에서 큰 차이로","reads the source directly instead of through a summary = 요약을 거치지 않고 원문을 직접 읽는다","the vanishing-gradient problem is bypassed, not patched = 기울기 소실 문제를 땜질한 게 아니라 비켜 갔다","rare in deep learning, and free here = 딥러닝에서 드문 일인데 여기서는 공짜로 얻었다"]},{"kind":"points","head":"bypassed 와 patched 의 차이","items":["patched 는 '구멍을 메웠다', bypassed 는 '돌아가는 길을 냈다' 는 뜻이에요.","**어텐션(Attention)**은 **RNN(순환 신경망)**의 긴 경로를 고친 게 아니라, 짧은 새 길을 하나 더 만든 거예요.","그래서 기울기가 곱셈을 훨씬 적게 거쳐요."]},{"kind":"points","head":"아직 남은 것: 병렬화","items":["네 가지 이득에 **병렬화(Parallelization)**는 들어 있지 않아요.","**인코더(Encoder)**와 **디코더(Decoder)**가 아직 **RNN(순환 신경망)**이라 자리를 순서대로 돌아야 해요. 그래서 **병렬화(Parallelization)**가 안 돼요.","**병렬화(Parallelization)**는 Part 3 의 셀프 어텐션에 가서야 생겨요."]},{"kind":"points","head":"여전히 하는 일은 같아요","items":["**디코더(Decoder)**는 여전히 조건이 붙은 **언어 모델(Language Model (LM))**이에요.","**어텐션(Attention)**은 그 **언어 모델(Language Model (LM))**이 참고할 자료를 더 잘 찾아 주는 장치예요.","**기계 번역(Machine Translation (MT))**에서 나왔지만 입력과 출력이 시퀀스인 모든 **언어 모델(Language Model (LM))**에 쓸 수 있어요."]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"1. Performance. 어텐션을 붙인 신경망 번역이 즉시, 그리고 긴 문장에서 크게 이겼다."},{"x":0.05,"y":0.26,"w":0.9,"h":0.06,"say":"2. No bottleneck. 디코더가 요약 대신 원문을 직접 읽는다."},{"x":0.05,"y":0.33,"w":0.9,"h":0.1,"say":"3. Shorter gradient paths. 모든 출력에서 모든 입력으로 직접 연결, 기울기 소실을 비켜 간다."},{"x":0.05,"y":0.44,"w":0.9,"h":0.07,"say":"4. Interpretability. 가중치가 모델이 무엇을 봤는지 보여 주는 그림이 된다."},{"x":0.28,"y":0.86,"w":0.44,"h":0.05,"say":"맨 아래: 가중 평균 하나에서 네 가지 이득을 얻었다."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 어텐션만 싹 붙여도 성능이 정말로 압도적으로 올라가요. 혁명적인 메커니즘이에요.","교수님: 중간 은닉 상태 하나가 병목이었는데 그게 아예 사라져 버렸어요.","교수님: 딥러닝에서 해석 가능한 XAI 가 쉽지 않은데, 어텐션은 해석 가능성이 되는 드문 경우 중 하나예요."]},{"kind":"steps","head":"경로 길이를 숫자로 느껴 봐요","given":"n = 20, 한 걸음마다 0.5 씩 줄어든다고 가정","steps":["입력 길이 n = 20 인 문장을 생각해요","RNN 에서 첫 단어의 정보가 마지막까지 가려면 은닉 상태를 20번 거쳐야 해요","역전파도 같은 길을 거꾸로 20번 곱하며 돌아와요","곱해지는 값이 0.5 정도라면 0.5 를 20번 곱한 값은 약 0.00000095 예요","어텐션은 출력에서 입력으로 한 걸음이라 곱셈이 거의 없어요"],"answer":"경로 길이가 n 에서 1 로 줄어드는 것이 어텐션의 세 번째 이득이에요."}],"pass4":[{"kind":"exam","src":"N4 Check Yourself","q":"Q5. Attention gives a direct path from every output step to every input word. Why does that help the gradient?","qko":"어텐션이 모든 출력 단계에서 모든 입력 단어로 직접 경로를 만들어 주는데, 그게 왜 기울기에 도움이 되나?","solve":["RNN 에서는 먼 위치의 정보까지 기울기가 가려면 여러 순환 단계를 연속으로 거쳐야 해요","단계마다 곱셈이 쌓여서 기울기가 아주 작아지거나 아주 커져요","어텐션은 디코딩 단계마다 인코더 자리로 가는 짧은 직접 경로를 더해 줘요","거쳐야 하는 곱셈 횟수가 n 에서 1 로 확 줄어요","그래서 먼 정보까지 학습하기가 훨씬 쉬워져요"],"answer":"기울기가 거쳐야 하는 곱셈 단계 수가 n 에서 1 로 줄어들어 기울기 소실을 비켜 갈 수 있기 때문이다."},{"kind":"english","head":"답안 문장","en":"**어텐션(Attention)**은 성능 향상, **정보 병목(Information Bottleneck)** 제거, 기울기 경로 단축, **해석 가능성(Interpretability)** 획득이라는 네 가지 이득을 준다.","ko":"나열형 문제에 그대로 쓸 수 있게 네 가지를 순서대로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**어텐션(Attention)**은 **기울기 소실(Vanishing Gradient)**을 '해결' 한 게 아니라 '비켜 갔다(bypassed)' 고 적혀 있어요. 표현을 정확히 써요."]}]},{"p":26,"title":"정렬을 공짜로 배워요","terms":["Alignment","Attention","Interpretability","Machine Translation (MT)"],"pass1":[{"kind":"say","lines":["**어텐션(Attention)**에서 가장 신기한 현상이에요.","아무도 가르쳐 주지 않았는데 모델이 스스로 **정렬(Alignment)**을 배워요."]},{"kind":"analogy","head":"아무도 안 가르친 짝 맞추기","scene":"영어와 우리말 문장 쌍을 아주 많이 보다 보면, 누가 알려 주지 않아도 you 와 '너를' 이 늘 함께 나온다는 것을 저절로 알게 돼요.","map":[["많은 문장 쌍","번역 학습 데이터"],["저절로 알게 되는 짝","**정렬(Alignment)**"],["아무도 안 알려 줌","정렬에 대한 별도 감독(supervision)이 없음"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Statistical MT needed a separate alignment model","통계 기반 번역은 별도의 정렬 모델이 필요했다"],["an entire research area of its own","그것 자체가 하나의 연구 분야였다"],["to decide which source word produced which target word","어떤 원문 단어가 어떤 목표 단어를 만들었는지 정하려고"],["Attention learns alignment as a side effect of learning to translate","어텐션은 번역을 배우는 부수 효과로 정렬을 배운다"],["Nobody supervised it","아무도 그것을 감독하지 않았다"]]},{"kind":"points","head":"slide 그림 읽는 법","items":["세로축은 모델이 만든 목표 문장(he, hit, me, with, a, pie) 이에요.","가로축은 원문(il, a, m', entarte) 이에요.","칸이 진할수록 그 자리를 많이 봤다는 뜻이에요.","예: he 는 il 을 0.85 로, pie 는 entarte 를 0.85 로 보고 있어요."]}],"pass3":[{"kind":"look","head":"슬라이드의 히트맵을 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.09,"say":"첫 점: 통계 기반 번역은 정렬 모델을 따로 만들어야 했다."},{"x":0.05,"y":0.29,"w":0.9,"h":0.06,"say":"둘째 점: 어텐션은 번역을 배우는 부수 효과로 정렬을 배운다. 아무도 감독하지 않았다."},{"x":0.29,"y":0.39,"w":0.5,"h":0.06,"say":"그림 제목: Attention learns alignment, nobody labelled it."},{"x":0.29,"y":0.44,"w":0.13,"h":0.3,"say":"왼쪽 위 진한 칸: he 가 il 을 0.85 로 봐요."},{"x":0.65,"y":0.58,"w":0.14,"h":0.18,"say":"오른쪽 아래 진한 칸들: with, a, pie 가 entarte 를 0.75, 0.80, 0.85 로 봐요."},{"x":0.22,"y":0.73,"w":0.2,"h":0.06,"say":"가로축 이름이 source, 세로축 이름이 generated target 이에요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 아이 러브 유에서 '너를' 할 때 you 에 집중하라고 감독을 주는 게 아니에요.","교수님: 그냥 학습을 하다 보면 자연스럽게 어텐션 히트맵이 딱 걸려요.","교수님: 나중에 학습이 끝나고 어텐션 맵을 찍어 보면 사람이 직접 준 것 같은 정보가 자동으로 나와서 굉장히 신기하죠."]}],"pass4":[{"kind":"check","q":"어텐션이 정렬을 배우는 방식은?","choices":["번역을 배우는 과정의 부수 효과로 저절로","정렬 정답을 따로 주고 학습해서","규칙을 손으로 적어서","사전을 참고해서"],"a":0,"why":"슬라이드: learns alignment as a side effect. 별도 감독이 없어요."},{"kind":"english","head":"답안 문장","en":"통계 기반 번역은 **정렬(Alignment)**을 위해 별도의 모델이 필요했다. **어텐션(Attention)**은 번역을 배우다 정렬을 스스로 익히고, 가중치를 그림으로 볼 수 있어 **해석 가능성(Interpretability)**도 함께 얻는다.","ko":"'별도 모델 불필요 + 부수 효과 + 시각화' 세 조각을 넣어요."}]},{"p":27,"title":"점수를 매기는 세 가지 방법","terms":["Dot Product","Attention Score","Multi-Layer Perceptron (MLP)","tanh","Transformer"],"pass1":[{"kind":"say","lines":["지금까지는 **내적(Dot Product)**으로만 점수를 냈어요. 그런데 다른 방법도 있어요.","슬라이드는 세 가지를 보여 줘요. 어텐션의 뼈대는 그대로이고 점수 함수만 바뀌어요."]},{"kind":"compare","head":"세 가지 점수 함수","cols":["이름","식","특징"],"rows":[["dot (내적)","s 와 h 의 내적","가장 싸고 빠르지만 두 벡터의 크기와 공간이 같아야 해요"],["multiplicative (Luong, 이중선형)","s 와 h 사이에 학습 행렬 W 를 끼움","조금 더 유연하게 관계를 배울 수 있어요"],["additive (Bahdanau, 덧셈형)","둘을 각각 변환해 더하고 tanh 를 씌움","가장 표현력이 크지만 가장 비싸요"]]}],"pass2":[{"kind":"formula","head":"세 식을 나란히","tex":"\\text{dot}: s^{\\top} h, \\qquad \\text{multiplicative}: s^{\\top} W h, \\qquad \\text{additive}: v^{\\top}\\tanh(W_1 h + W_2 s)","parts":[{"sym":"s^{\\top} h","say":"그냥 내적. 학습 파라미터가 없어요"},{"sym":"W","say":"학습되는 행렬 하나를 가운데에 끼워요"},{"sym":"W_1 h + W_2 s","say":"인코더 상태와 디코더 상태를 각각 변환해서 더해요"},{"sym":"\\tanh","say":"-1 과 1 사이로 눌러 주는 활성화 함수"},{"sym":"v^{\\top}","say":"마지막으로 숫자 하나로 줄여 주는 벡터"}],"whole":"셋 다 결과는 숫자 하나예요. additive 는 작은 **MLP(다층 퍼셉트론)** 하나를 쓰는 셈이에요."},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Dot product is the cheapest = 내적이 가장 싸다","but forces the encoder and decoder states to have the same size and live in the same space = 그러나 인코더와 디코더 상태의 크기가 같고 같은 공간에 있어야 한다","Bilinear (Luong) inserts a learned matrix W = 이중선형(Luong)은 학습되는 행렬 W 를 끼운다","Additive (Bahdanau) feeds both through a small MLP = 덧셈형(Bahdanau)은 둘을 작은 MLP 에 넣는다","The Transformer uses the dot product, scaled = 트랜스포머는 크기를 조절한 내적을 쓴다"]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 점: 내적은 가장 싸지만 두 상태의 크기와 공간이 같아야 한다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.05,"say":"둘째 점: 이중선형(Luong)은 학습 행렬 W 를 끼운다."},{"x":0.05,"y":0.3,"w":0.9,"h":0.05,"say":"셋째 점: 덧셈형(Bahdanau)은 작은 MLP 를 쓴다. 표현력이 크고 비싸다."},{"x":0.05,"y":0.35,"w":0.9,"h":0.05,"say":"넷째 점: 트랜스포머는 크기를 조절한 내적을 쓴다. Part 3 에서 이유를 본다."},{"x":0.13,"y":0.52,"w":0.76,"h":0.1,"say":"세 식이 나란히 적혀 있어요. dot, multiplicative, additive 순서예요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 어텐션 하면 가장 유명한 게 세 번째 바다나우 어텐션인데, 트랜스포머에서는 다시 첫 번째 내적으로 갑니다.","교수님: 트랜스포머는 파라미터가 많기 때문에 점수 계산에는 파라미터를 더 쓰지 않아요.","교수님: 이 슬라이드의 핵심은 어텐션 자체가 바뀌는 게 아니라 점수 함수가 여러 개 있을 수 있다는 거예요.","교수님: 논문을 쓰려면 이런 설계 하나하나에서 문제를 찾고 더 좋게 바꿀 수 없을까 생각하는 태도가 필요해요."]},{"kind":"bg","src":"배경 지식","lines":["Bahdanau 는 2015년 어텐션을 처음 제안한 논문의 저자 이름이에요. 녹음에서는 '바나두' 로 들려요.","Luong 은 곱셈형 점수 함수를 제안한 연구자예요."]}],"pass4":[{"kind":"check","q":"트랜스포머가 쓰는 점수 함수는?","choices":["크기를 조절한 내적","덧셈형(Bahdanau)","이중선형(Luong)","코사인 유사도"],"a":0,"why":"슬라이드: The Transformer uses the dot product, scaled. 이유는 Part 3 에서 나와요."},{"kind":"english","head":"답안 문장","en":"**어텐션 점수(Attention Score)** 함수에는 내적, 학습 행렬을 끼운 이중선형(Luong), 작은 **MLP(다층 퍼셉트론)**를 쓰는 덧셈형(Bahdanau)이 있다. 세 단계 구조는 그대로이고 점수 함수만 달라진다.","ko":"세 이름과 대표 식을 함께 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**내적(Dot Product)**만 쓰려면 두 벡터의 칸 수가 같아야 해요. 칸 수가 다르면 곱해서 더할 수가 없어요."]}]},{"p":28,"title":"어텐션은 일반적인 기법이에요","terms":["Attention","Query","Value","Context Vector"],"pass1":[{"kind":"say","lines":["번역이라는 맥락을 완전히 지우고 보면, 어텐션의 정의는 아주 일반적이에요.","'**밸류(Value)**들의 모음과 **쿼리(Query)** 하나가 있을 때, 쿼리에 따라 값들의 가중합을 만드는 것' 이에요."]},{"kind":"analogy","head":"같은 자료, 다른 질문","scene":"같은 책 한 권을 두고 '주인공은 누구지?' 라고 물을 때와 '배경은 어디지?' 라고 물을 때, 밑줄 치는 부분이 달라져요.","map":[["책 내용","값들(values)"],["지금 던지는 질문","**쿼리(Query)**"],["밑줄 친 곳을 모은 요약","**문맥 벡터(Context Vector)**"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Strip away translation and the definition is completely general = 번역을 걷어 내면 정의가 완전히 일반적이다","given a set of values and a query = 값들의 집합과 쿼리 하나가 주어지면","attention computes a weighted sum of the values = 어텐션은 값들의 가중합을 계산한다","where the weights depend on the query = 가중치는 쿼리에 따라 달라진다","The query chooses what to pull out of the values = 쿼리가 값들에서 무엇을 꺼낼지 고른다"]},{"kind":"points","head":"무엇이 고정이고 무엇이 바뀌나요","items":["**밸류(Value)**들은 그대로 있어요(인코더 상태들)","**쿼리(Query)**가 바뀌면 가중치가 바뀌고, 가중치가 바뀌면 **문맥 벡터(Context Vector)**도 바뀌어요","그래서 같은 값들을 놓고도 단계마다 다른 요약이 나와요"]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 점: 번역을 걷어 내면 정의가 완전히 일반적이다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.07,"say":"가운데 줄: 값들의 집합과 쿼리가 주어지면 쿼리에 따라 달라지는 가중치로 값들의 가중합을 낸다."},{"x":0.05,"y":0.34,"w":0.9,"h":0.08,"say":"마지막 점: 임의의 집합을 조건에 맞춰 고정 크기로 요약하는 방법이다."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 여기서 지금 각각의 디코딩 스텝마다의 s_t 가 쿼리가 되는 거예요.","교수님: 인코더 은닉 상태들은 고정돼 있는데, s_t 가 달라질 때마다 가중치가 달라지고 문맥 벡터도 달라져요.","교수님: 쿼리는 지금 내가 무엇을 찾고자 하는지이고, 어텐션은 여러 정보 중에서 필요한 것을 골라 하나의 표현으로 모아 줘요."]},{"kind":"points","head":"여기서는 키가 아직 안 보여요","items":["2015년 어텐션에서는 **키(Key)**와 **밸류(Value)**이 같은 것(인코더 상태 h)이었어요.","점수를 낼 때도 h, 가중합을 할 때도 h 를 썼어요.","Part 3 에서 이 둘을 갈라놓으면서 **쿼리(Query)**, **키(Key)**, **밸류(Value)** 세 낱말이 완성돼요."]}],"pass4":[{"kind":"check","q":"쿼리가 바뀌면 무엇이 바뀌나요?","choices":["가중치와 문맥 벡터","값들 자체","인코더의 파라미터","어휘 크기"],"a":0,"why":"값들은 그대로예요. 쿼리가 바뀌면 어디를 얼마나 볼지가 바뀌어요."},{"kind":"english","head":"답안 문장","en":"**어텐션(Attention)**은 값들의 집합과 **쿼리(Query)**가 주어졌을 때 쿼리에 따라 정해지는 가중치로 값들의 가중합을 만드는 일반적인 기법이며, 임의의 집합을 조건에 맞춰 고정 크기로 요약하는 방법이다.","ko":"번역과 상관없는 일반 정의를 한 문장으로 쓸 수 있어야 해요."}]},{"p":29,"title":"Check Yourself 1: 스스로 확인하기","terms":["Information Bottleneck","Teacher Forcing","Exposure Bias","Beam Search","Greedy Decoding","Attention","Gradient"],"pass1":[{"kind":"say","lines":["Part 1 과 Part 2 를 제대로 이해했는지 확인하는 쪽이에요.","교수님이 수업에서 다섯 문제의 답을 하나하나 말해 주었어요.","이 다섯 개를 말로 설명할 수 있으면 앞의 두 챕터는 이해한 거예요."]}],"pass2":[{"kind":"points","head":"다섯 문제를 우리말로","items":["1. 고정 크기 인코더 벡터는 왜 긴 문장에서 더 해로운가 (**정보 병목(Information Bottleneck)**)","2. **교사 강요(Teacher Forcing)**에서 학습과 시험은 정확히 무엇이 다른가","3. k = 1 인 **빔 서치(Beam Search)**는 어떤 알고리즘과 같고, 왜 **길이 정규화(Length Normalization)**가 필요한가","4. 어텐션 네 식을 외워서 쓰고, 어느 것이 합을 1 로 만드는가","5. 어텐션의 직접 경로가 왜 기울기에 도움이 되는가"]}],"pass3":[{"kind":"look","head":"슬라이드의 다섯 문제를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.07,"say":"1번: 고정 크기 인코더 벡터와 문장 길이. p.16 에서 답을 봤어요."},{"x":0.05,"y":0.27,"w":0.9,"h":0.07,"say":"2번: 교사 강요의 학습과 시험 차이. p.11 에서 답을 봤어요."},{"x":0.05,"y":0.35,"w":0.9,"h":0.08,"say":"3번: 빔 서치 k=1 과 길이 정규화. p.13 에서 답을 봤어요."},{"x":0.05,"y":0.44,"w":0.9,"h":0.07,"say":"4번: 어텐션 네 식. p.24 에서 답을 봤어요."},{"x":0.05,"y":0.52,"w":0.9,"h":0.07,"say":"5번: 직접 경로와 기울기. p.25 에서 답을 봤어요."}]},{"kind":"prof","when":"4주차 월요일 1교시","lines":["교수님: 이 다섯 문제를 잘 설명할 수 있으면 앞의 1, 2 챕터를 이해를 잘 했다고 보실 수 있어요.","교수님(3번): 빔 사이즈가 1 이면 그리디 디코딩과 같아요. 로그 확률이 음수라 문장이 길수록 점수가 작아져서 길이 정규화를 해 줘요.","교수님(5번): 어텐션을 쓰면 거의 n 에서 1 로 줄어들기 때문에 먼 정보까지 학습하기가 훨씬 쉬워져요."]}],"pass4":[{"kind":"exam","src":"N4 Check Yourself","q":"Q1 ~ Q5 (Part 1)","qko":"다섯 문제의 답을 한 줄씩 정리해요.","solve":["1. 통로가 입력 길이와 상관없이 같은 크기라서, 길수록 압축 손실이 커져요(**정보 병목(Information Bottleneck)**)","2. 학습은 정답 토큰, 시험은 모델 자신의 출력을 다음 입력으로 넣어요(**노출 편향(Exposure Bias)**)","3. k = 1 은 **탐욕적 디코딩(Greedy Decoding)**와 같고, 로그 확률 합이 길수록 작아져서 길이로 나눠요","4. 점수, 소프트맥스 정규화, 가중합, 예측. 합을 1 로 만드는 것은 소프트맥스","5. 기울기가 거쳐야 하는 곱셈이 n 번에서 1 번으로 줄어서예요"],"answer":"다섯 답을 모두 한 줄로 말할 수 있으면 Part 1, 2 는 끝이에요."},{"kind":"check","q":"교수님이 이 다섯 문제에 대해 말한 것은?","choices":["다 설명할 수 있으면 앞 두 챕터를 이해한 것","시험에는 안 나온다","너무 어려우니 건너뛰어도 된다","답이 여러 개다"],"a":0,"why":"교수님이 수업에서 다섯 개 답을 직접 말해 주면서 그렇게 정리했어요."},{"kind":"warn","head":"시험에 나올 만한 곳","items":["Check Yourself 는 교수님이 직접 낸 문제예요. 형태 그대로 시험에 나올 가능성이 가장 높은 부분이에요."]}]},{"p":30,"title":"쉬는 시간 10분","terms":["Self-Attention","Attention"],"pass1":[{"kind":"say","lines":["10분 쉬는 시간 쪽이에요. 전반전은 seq2seq, 병목, 그리고 어텐션이었어요.","이어서 나올 것은 **셀프 어텐션(Self-Attention)**이에요. 같은 생각인데 문장이 자기 자신을 바라보고, RNN 이 완전히 사라져요."]}],"pass2":[{"kind":"points","head":"전반전에서 배운 것 한 줄씩","items":["**기계 번역(Machine Translation (MT))** 을 풀려고 **시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)** 을 만들었고, 거기서 **정보 병목(Information Bottleneck)** 이 나왔어요.","학습은 **교사 강요(Teacher Forcing)**, 그 부작용은 **노출 편향(Exposure Bias)** 였어요.","생성은 **탐욕적 디코딩(Greedy Decoding)** 과 **빔 서치(Beam Search)**, 그리고 **길이 정규화(Length Normalization)** 이었어요.","**어텐션(Attention)** 은 점수, 소프트맥스, 가중합, 예측의 네 단계였어요.","점수 함수는 내적, 이중선형, 그리고 작은 **MLP(다층 퍼셉트론)** 를 쓰는 덧셈형이 있었어요."]},{"kind":"points","head":"전반전 용어 다시 부르기","items":["**기계 번역(Machine Translation (MT))**, **교사 강요(Teacher Forcing)**, **노출 편향(Exposure Bias)** 를 한 번씩 소리 내어 읽어 봐요.","**탐욕적 디코딩(Greedy Decoding)**, **빔 서치(Beam Search)**, **MLP(다층 퍼셉트론)** 도 한 번씩 읽어 봐요.","여섯 낱말을 말할 수 있으면 Part 1 과 Part 2 는 끝난 거예요.","후반전에는 여기에 쿼리, 키, 밸류가 더해져요."]},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["half-time: seq2seq, its bottleneck, and attention = 전반전은 seq2seq, 그 병목, 그리고 어텐션","Coming up: self-attention = 다음은 셀프 어텐션","the same idea, but the sequence attends to itself = 같은 생각인데 시퀀스가 자기 자신에 주목한다","and the RNN disappears entirely = 그리고 RNN 이 완전히 사라진다"]}],"pass3":[],"pass4":[]},{"p":31,"title":"Part 3 표지: Self-Attention","terms":["Self-Attention","Attention","Recurrent Neural Network (RNN)"],"pass1":[{"kind":"say","lines":["세 번째 부분 표지예요. 제목은 3 Self-Attention 이에요.","작은 글씨는 remove the recurrence, keep the attention, 곧 **RNN(순환 신경망)** 을 빼고 **어텐션(Attention)** 만 남긴다는 뜻이에요.","여기서부터가 2017년 이야기이고 **셀프 어텐션(Self-Attention)**이 주인공이에요."]}],"pass2":[{"kind":"points","head":"영어 부제의 뜻","items":["remove the recurrence = 순환(한 걸음씩 도는 것)을 없앤다","keep the attention = 어텐션은 그대로 남긴다","곧 **RNN(순환 신경망)** 은 버리고 **어텐션(Attention)** 만으로 문장을 처리한다는 선언이에요","Part 2 에서 **어텐션(Attention)**이 **정보 병목(Information Bottleneck)**을 없앴고, 이제 순환까지 없애요"]}],"pass3":[{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 여기서부터는 셀프 어텐션을 활용한 트랜스포머를 배워 보겠습니다.","교수님: 이제 RNN 은 아예 빼 버리고 어텐션만 남기면 된다.","교수님: 논문 제목이 Attention Is All You Need 예요. 어텐션만 있으면 된다는 거죠."]}],"pass4":[]},{"p":32,"title":"순환이 정말 필요할까요","terms":["Self-Attention","Attention","Recurrent Neural Network (RNN)","Hidden State","Vanishing Gradient","Gradient","Parallelization","Token"],"pass1":[{"kind":"say","lines":["질문 하나로 시작해요. **어텐션(Attention)**이 이미 출력과 입력을 직접 이어 줬어요.","그러면 **RNN(순환 신경망)** 은 아직 무슨 일을 하고 있을까요?","남은 일은 한 문장 안에서 **토큰(Token)**끼리 정보를 섞는 것뿐이에요.","그런데 그것도 어텐션이 할 수 있어요. 문장이 자기 자신을 보게 하면 돼요."]},{"kind":"analogy","head":"줄 서서 전달하기 vs 다 같이 마주 보기","scene":"교실에서 맨 앞 사람의 쪽지를 맨 뒤까지 옆 사람에게 차례로 넘기면 여섯 번을 거쳐요. 대신 모두가 동시에 서로를 바라보면 한 번에 끝나요.","map":[["옆 사람에게 차례로 넘기기","**RNN(순환 신경망)**"],["모두가 서로를 바라보기","**셀프 어텐션(Self-Attention)**"],["전달하다 희미해진 쪽지","**기울기 소실(Vanishing Gradient)**"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Do We Even Need Recurrence? = 순환이 정말 필요하긴 할까?","Attention already connects every output to every input directly = 어텐션은 이미 모든 출력을 모든 입력에 바로 이어 준다","Its job is to mix information within a sequence = RNN 의 일은 한 시퀀스 안에서 정보를 섞는 것이다","if we let a sequence attend to itself = 시퀀스가 자기 자신에 주목하게 하면","the maximum path length drops from n to 1 = 가장 긴 경로가 n 에서 1 로 줄어든다"]},{"kind":"compare","head":"RNN 과 셀프 어텐션의 차이 한눈에","cols":["보는 점","RNN","셀프 어텐션"],"rows":[["두 단어 사이 거리","떨어진 만큼 여러 걸음","언제나 1 걸음"],["계산 순서","앞 자리가 끝나야 다음","전부 동시에"],["**정보 병목(Information Bottleneck)**","어텐션으로 이미 해결됨","어텐션으로 이미 해결됨"],["기울기가 겪는 곱셈","거리만큼 여러 번","한 번"]]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 점: 어텐션은 이미 모든 출력과 모든 입력을 직접 잇는다. 그럼 RNN 은 왜 필요한가."},{"x":0.05,"y":0.25,"w":0.9,"h":0.06,"say":"둘째 점: RNN 의 일은 한 시퀀스 안에서 정보를 섞는 것인데, 어텐션도 그 일을 할 수 있다."},{"x":0.07,"y":0.54,"w":0.86,"h":0.09,"say":"주황 상자 열한 개가 The chef who went to the stores was out of food 예요."},{"x":0.17,"y":0.44,"w":0.5,"h":0.11,"say":"위쪽 초록 화살표: 셀프 어텐션이면 chef 와 was 가 1 걸음이에요."},{"x":0.17,"y":0.63,"w":0.5,"h":0.11,"say":"아래쪽 빨간 화살표: RNN 이면 6 번의 리커런트 걸음을 거쳐야 해요."},{"x":0.1,"y":0.78,"w":0.76,"h":0.05,"say":"아래 글: 선형 거리, 기울기가 O(n) 번 곱셈을 견뎌야 함, 시퀀스 안 병렬 불가"}]},{"kind":"steps","head":"경로 길이를 세어 봐요","given":"chef 와 was 사이","steps":["문장은 The chef who went to the stores was out of food 예요","chef 는 2번째, was 는 8번째 토큰이에요","RNN 은 chef 의 정보를 **은닉 상태(Hidden State)**에 실어 한 칸씩 옮겨요","who, went, to, the, stores 를 지나 was 에 닿으니 6 걸음이에요","셀프 어텐션은 was 가 chef 를 바로 쳐다봐요. 1 걸음이에요"],"answer":"6 걸음 vs 1 걸음. 곱셈 횟수가 줄어드니 **기울기 소실(Vanishing Gradient)**이 훨씬 덜해요."},{"kind":"figure","head":"거리가 n 에서 1 로","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"22\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">거리가 n 에서 1 로<\/text><rect x=\"14\" y=\"44\" width=\"68\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"48.0\" y=\"62.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">The<\/text><rect x=\"90\" y=\"44\" width=\"68\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"124.0\" y=\"62.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">chef<\/text><rect x=\"166\" y=\"44\" width=\"68\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"200.0\" y=\"62.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">who<\/text><rect x=\"242\" y=\"44\" width=\"68\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"276.0\" y=\"62.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">went<\/text><rect x=\"318\" y=\"44\" width=\"68\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"352.0\" y=\"62.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">was<\/text><rect x=\"394\" y=\"44\" width=\"68\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"428.0\" y=\"62.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">food<\/text><line x1=\"124\" y1=\"90\" x2=\"345.6\" y2=\"90.0\" class=\"e b2\"/><polygon points=\"352,90 344.0,86.0 344.0,94.0\" class=\"arrow b2\"/><text x=\"240\" y=\"112\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">RNN: chef 에서 was 까지 리커런트 6 걸음<\/text><line x1=\"124\" y1=\"146\" x2=\"345.6\" y2=\"146.0\" class=\"e2 b3\"/><polygon points=\"352,146 344.0,142.0 344.0,150.0\" class=\"arrow b3\"/><text x=\"240\" y=\"168\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">셀프 어텐션: chef 와 was 는 1 걸음<\/text><text x=\"240\" y=\"200\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">걸음이 줄면 기울기가 덜 희미해져요<\/text><text x=\"240\" y=\"224\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">그리고 앞을 기다릴 필요가 없어 병렬 계산이 돼요<\/text><\/svg>","caption":"위는 셀프 어텐션의 한 걸음, 아래는 RNN 의 여섯 걸음이에요.","builds":4},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: RNN 이 하는 중요한 역할 중 하나가 한 시퀀스 안에서 단어들 사이에 정보를 전달하는 거였어요.","교수님: 이 정보 교환 자체는 어텐션도 할 수가 있다는 거죠.","교수님: 시퀀스가 자기 자신을 바라보게 만드는 게 **셀프 어텐션(Self-Attention)**의 핵심 아이디어예요.","Part 2 의 **정보 병목(Information Bottleneck)**에 이어, 이번에는 순환 자체를 없애는 이야기예요.","교수님: 셀프 어텐션의 가장 큰 장점은 병렬로 계산할 수 있다는 거고, 이 패러럴이 핵심이에요."]}],"pass4":[{"kind":"check","q":"RNN 에서 두 단어가 6 칸 떨어져 있으면 정보가 지나야 하는 걸음 수는?","choices":["1 걸음","3 걸음","6 걸음","36 걸음"],"a":2,"why":"**RNN(순환 신경망)** 은 **은닉 상태(Hidden State)**를 한 칸씩 넘기므로 떨어진 칸 수만큼 걸어요. 셀프 어텐션은 1 걸음이에요."},{"kind":"english","head":"시험 답안 문장","en":"셀프 어텐션은 두 토큰 사이의 최대 경로 길이를 n 에서 1 로 줄여, 먼 거리 의존을 학습하기 쉽게 하고 병렬 계산을 가능하게 한다.","ko":"핵심은 두 가지, 경로 길이 1 과 병렬화(parallelization)예요.","tip":"n 에서 1, 이 한 줄만 외워도 절반은 맞아요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["셀프 어텐션이 **기울기 소실(Vanishing Gradient)**을 직접 고치는 게 아니에요. 거리를 1 로 줄여서 비켜 가는 거예요.","**병렬화(Parallelization)**는 한 시퀀스 안에서의 이야기예요. 배치끼리는 RNN 도 병렬로 돌릴 수 있어요."]}]},{"p":33,"title":"크로스 어텐션과 셀프 어텐션","terms":["Cross-Attention","Self-Attention","Query","Key","Value","Encoder","Decoder","Attention","Token"],"pass1":[{"kind":"say","lines":["이름을 정리하는 쪽이에요. Part 2 에서 배운 **어텐션(Attention)**에 이름을 붙여요.","**디코더(Decoder)**가 **인코더(Encoder)**를 바라본 것처럼 서로 다른 시퀀스를 보면 **크로스 어텐션(Cross-Attention)**이에요.","한 시퀀스가 자기 자신을 보면 **셀프 어텐션(Self-Attention)**이에요.","기계는 똑같아요. 벡터가 어디서 오느냐만 달라요."]},{"kind":"analogy","head":"남의 책 보기 vs 내 노트 다시 보기","scene":"시험 공부를 할 때 옆 사람 노트를 빌려 보는 것과, 내가 쓴 노트를 처음부터 다시 훑어보는 것은 읽는 방법은 같고 대상만 달라요.","map":[["옆 사람 노트 보기","**크로스 어텐션(Cross-Attention)**"],["내 노트 다시 보기","**셀프 어텐션(Self-Attention)**"],["읽는 방법 자체","점수, 소프트맥스, 가중합의 세 단계"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["queries come from one sequence, keys and values from another = 쿼리는 한 시퀀스에서, 키와 밸류는 다른 시퀀스에서 온다","That is 2장의 attention = 그것이 Part 2 의 어텐션이다","queries, keys and values all come from the same sequence = 쿼리, 키, 밸류가 모두 같은 시퀀스에서 온다","Every token asks every other token a question = 모든 토큰이 다른 모든 토큰에게 질문한다","Same machinery, the only change is where the vectors come from = 기계는 같고 벡터가 어디서 오는지만 바뀐다"]},{"kind":"compare","head":"두 어텐션 비교","cols":["구분","**크로스 어텐션(Cross-Attention)**","**셀프 어텐션(Self-Attention)**"],"rows":[["쿼리","디코더(만드는 쪽)","같은 문장의 토큰"],["키, 밸류","인코더(읽는 쪽)","같은 문장의 토큰"],["쓰는 곳","번역의 디코더 중간","인코더와 디코더 둘 다"]]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.06,"say":"첫 점: 크로스 어텐션은 쿼리가 한 시퀀스, 키와 밸류가 다른 시퀀스에서 온다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.06,"say":"둘째 점: 셀프 어텐션은 셋 다 같은 시퀀스에서 온다."},{"x":0.1,"y":0.33,"w":0.38,"h":0.45,"say":"왼쪽 그림: 초록 상자 s_t 하나가 아래 주황 상자 네 개를 향해 화살표를 쏴요."},{"x":0.55,"y":0.33,"w":0.4,"h":0.45,"say":"오른쪽 그림: 파란 상자들이 서로서로를 향해 화살표를 쏴요."},{"x":0.22,"y":0.85,"w":0.56,"h":0.05,"say":"아래 파란 글: 기계는 같고 벡터가 어디서 오는지만 바뀐다."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 챕터 2까지 배웠던 어텐션을 크로스 어텐션이라고 할게요.","교수님: 인코더와 디코더를 크로스해서 어텐션을 보기 때문에 크로스 어텐션이라고 명명합니다.","교수님: 셀프 어텐션은 한 시퀀스 안에서 모든 토큰들이 서로서로를 어텐션 하는 거예요."]}],"pass4":[{"kind":"check","q":"쿼리는 디코더에서, 키와 밸류는 인코더에서 오는 어텐션의 이름은?","choices":["**크로스 어텐션(Cross-Attention)**","**셀프 어텐션(Self-Attention)**","스케일드 닷프로덕트 어텐션","멀티 헤드 어텐션"],"a":0,"why":"서로 다른 두 시퀀스를 가로질러 보기 때문에 **크로스 어텐션(Cross-Attention)**이에요."},{"kind":"english","head":"시험 답안 문장","en":"크로스 어텐션은 쿼리와 키, 밸류가 서로 다른 시퀀스에서 오고, 셀프 어텐션은 셋 다 같은 시퀀스에서 온다. 계산 방식은 동일하다.","ko":"차이는 오직 벡터의 출처 한 가지예요.","tip":"크로스는 가로지른다, 셀프는 자기 자신, 이름 그대로예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**크로스 어텐션(Cross-Attention)**이 더 어려운 게 아니에요. 오히려 먼저 나온 옛날 방식이에요.","**셀프 어텐션(Self-Attention)**도 **쿼리(Query)**, **키(Key)**, **밸류(Value)** 세 가지를 그대로 써요. 새로운 계산이 아니에요."]}]},{"p":34,"title":"쿼리, 키, 밸류","terms":["Query","Key","Value","Self-Attention","Parameter","Embedding","Token","Dot Product","Attention Score"],"pass1":[{"kind":"say","lines":["**셀프 어텐션(Self-Attention)**의 심장이에요. **토큰(Token)** 하나가 세 역할을 동시에 해요.","**쿼리(Query)**는 나는 무엇을 찾고 있나, **키(Key)**는 나는 이런 것이라고 광고하는 이름표,","**밸류(Value)**는 내가 뽑히면 실제로 건네줄 내용이에요.","같은 입력 벡터에 서로 다른 행렬 세 개를 곱해서 만들어요."]},{"kind":"analogy","head":"도서관에서 책 찾기","scene":"내가 찾는 주제를 머리에 떠올리고(질문), 책등에 붙은 제목을 훑어보고(이름표), 마음에 드는 책의 내용을 읽어요(내용).","map":[["내가 찾는 주제","**쿼리(Query)**"],["책등의 제목","**키(Key)**"],["책 안의 내용","**밸류(Value)**"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Each token plays three roles at once = 각 토큰이 세 역할을 동시에 한다","three learned linear maps of the same input vector = 같은 입력 벡터에 대한 학습된 선형 변환 셋","Query, what am I looking for? = 쿼리, 나는 무엇을 찾고 있나","Key, what do I advertise? = 키, 나는 무엇을 광고하나","Value, what do I hand over if chosen? = 밸류, 뽑히면 무엇을 건네주나","shared across all positions = 모든 자리가 함께 쓴다"]},{"kind":"compare","head":"세 역할의 쓰임새","cols":["역할","질문","어디에 쓰이나"],"rows":[["**쿼리(Query)**","나는 무엇을 찾나","점수 계산의 출발점"],["**키(Key)**","나는 무엇을 광고하나","점수 계산에서 쿼리와 내적"],["**밸류(Value)**","뽑히면 무엇을 주나","가중합에 들어가는 내용"]]}],"pass3":[{"kind":"formula","head":"세 벡터 만들기","tex":"q_i = W^Q x_i,\\quad k_i = W^K x_i,\\quad v_i = W^V x_i","parts":[{"sym":"x_i","say":"i 번째 토큰의 입력 벡터, 곧 **임베딩(Embedding)** 이에요"},{"sym":"W^Q","say":"쿼리를 만드는 학습 가능한 행렬"},{"sym":"W^K","say":"키를 만드는 학습 가능한 행렬"},{"sym":"W^V","say":"밸류를 만드는 학습 가능한 행렬"},{"sym":"q_i, k_i, v_i","say":"그 토큰의 쿼리, 키, 밸류 벡터"}],"whole":"입력 하나에서 세 벡터가 나와요. 세 행렬이 학습되는 **파라미터(Parameter)**예요."},{"kind":"figure","head":"토큰 하나가 세 역할을 동시에","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"22\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">토큰 하나가 세 역할을 동시에<\/text><rect x=\"180\" y=\"40\" width=\"120\" height=\"30\" rx=\"2\" class=\"box b1\"/><text x=\"240.0\" y=\"59.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">x_i (입력 벡터)<\/text><line x1=\"200\" y1=\"76\" x2=\"126.0\" y2=\"103.8\" class=\"e2 b2\"/><polygon points=\"120,106 128.9,106.9 126.1,99.4\" class=\"arrow b2\"/><line x1=\"240\" y1=\"76\" x2=\"240.0\" y2=\"99.6\" class=\"e2 b2\"/><polygon points=\"240,106 244.0,98.0 236.0,98.0\" class=\"arrow b2\"/><line x1=\"280\" y1=\"76\" x2=\"354.0\" y2=\"103.8\" class=\"e2 b2\"/><polygon points=\"360,106 353.9,99.4 351.1,106.9\" class=\"arrow b2\"/><rect x=\"60\" y=\"108\" width=\"120\" height=\"30\" rx=\"2\" class=\"box2 b2\"/><text x=\"120.0\" y=\"127.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">q = W^Q x<\/text><rect x=\"182\" y=\"108\" width=\"116\" height=\"30\" rx=\"2\" class=\"box2 b2\"/><text x=\"240.0\" y=\"127.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">k = W^K x<\/text><rect x=\"300\" y=\"108\" width=\"120\" height=\"30\" rx=\"2\" class=\"box2 b2\"/><text x=\"360.0\" y=\"127.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">v = W^V x<\/text><text x=\"120\" y=\"160\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">무엇을 찾나<\/text><text x=\"240\" y=\"160\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">나는 이런 것<\/text><text x=\"360\" y=\"160\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">뽑히면 줄 내용<\/text><text x=\"240\" y=\"196\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">W^Q, W^K, W^V 세 행렬은 모든 자리가 함께 써요<\/text><text x=\"240\" y=\"220\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">그래서 문장이 길어져도 파라미터가 늘지 않아요<\/text><\/svg>","caption":"같은 x 에 서로 다른 행렬 셋을 곱해요.","builds":4},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: 각 토큰이 세 역할을 동시에 하고, 같은 입력 벡터의 학습된 선형 변환으로 만든다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.05,"say":"둘째 점: query 는 무엇을 찾나, key 는 무엇을 광고하나, value 는 무엇을 건네주나."},{"x":0.23,"y":0.38,"w":0.54,"h":0.07,"say":"위쪽 상자 다섯 개가 문장 Zuko made his uncle tea 예요."},{"x":0.21,"y":0.48,"w":0.42,"h":0.16,"say":"가운데 작은 식 세 줄이 q, k, v 를 만드는 공식이에요."},{"x":0.12,"y":0.7,"w":0.76,"h":0.11,"say":"아래 큰 글씨 세 식이 오늘 외워야 할 공식이에요."},{"x":0.3,"y":0.86,"w":0.4,"h":0.04,"say":"맨 아래: 세 행렬은 모든 자리가 공유한다."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 이 쿼리, 키, 밸류 3개의 컨셉을 이해해야 뒤에 트랜스포머를 이해할 수 있고 자연어 처리를 이해할 수 있어요.","교수님: 키는 사전의 색인 같은 거예요. 나는 이런 정보를 갖고 있으니 나를 찾아봐라 하고 광고하는 게 키다.","교수님: 중요한 점이 위치마다 이 행렬을 따로 만드는 게 아니고, 모든 토큰들이 공유하는 겁니다."]}],"pass4":[{"kind":"check","q":"**가중합(Weighted Sum)**에 실제로 들어가는 벡터는 무엇인가요?","choices":["**쿼리(Query)**","**키(Key)**","**밸류(Value)**","입력 임베딩 그대로"],"a":2,"why":"**키(Key)**는 점수를 만들 때만 쓰고, 실제로 더해지는 내용은 **밸류(Value)**예요."},{"kind":"exam","src":"N4 Check Yourself","q":"Q1 (Part 2). What exactly is the difference between self-attention and the attention of 2장?","qko":"셀프 어텐션과 Part 2 의 어텐션은 정확히 무엇이 다른가요?","solve":["Part 2 어텐션은 쿼리가 디코더, 키와 밸류가 인코더에서 왔어요","셀프 어텐션은 쿼리, 키, 밸류가 모두 같은 시퀀스에서 나와요","Part 2 에서는 키와 밸류가 사실 같은 h 였는데, 셀프 어텐션은 둘을 나눠요","그리고 점수를 루트 d_k 로 나누는 스케일이 추가돼요"],"answer":"출처가 같은 시퀀스인지 다른 시퀀스인지, 그리고 키와 밸류를 나눴는지가 차이예요."},{"kind":"english","head":"시험 답안 문장","en":"셀프 어텐션에서 각 토큰은 같은 입력 벡터에 W^Q, W^K, W^V 를 곱해 쿼리, 키, 밸류를 만들며, 이 세 행렬은 모든 위치가 공유한다.","ko":"만드는 법 한 줄, 공유한다 한 줄이면 충분해요.","tip":"Q 는 질문, K 는 이름표, V 는 내용. 세 글자로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**키(Key)**와 **밸류(Value)**는 다른 벡터예요. Part 2 어텐션에서는 둘이 같았을 뿐이에요.","W^Q, W^K, W^V 는 토큰마다 다른 게 아니라 문장 전체가 같은 것을 써요."]}]},{"p":35,"title":"쿼리 하나를 따라가 보기","terms":["Self-Attention","Query","Key","Value","Attention Weight","Softmax","Weighted Sum","Context Vector","Token","Dot Product"],"pass1":[{"kind":"say","lines":["**토큰(Token)** 하나를 골라 끝까지 따라가는 쪽이에요.","his 라는 토큰의 쿼리를 모든 키와 비교하고, 소프트맥스를 쓰고, 밸류를 섞어요.","그 결과가 his 의 새 벡터가 돼요. 이제 his 안에 uncle 의 정보가 들어 있어요.","Part 2 의 세 단계와 완전히 같아요."]},{"kind":"analogy","head":"반 친구들에게 한 번씩 물어보기","scene":"내가 궁금한 것을 들고 반 친구 다섯 명에게 차례로 묻고, 도움이 된 만큼 비중을 둬서 답을 하나로 합쳐요.","map":[["내 질문","**쿼리(Query)**"],["친구들의 이름표","**키(Key)**"],["친구들의 대답","**밸류(Value)**"],["합쳐진 한 문장","**문맥 벡터(Context Vector)**"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Take the query of one token = 토큰 하나의 쿼리를 가져온다","score it against every key = 모든 키에 대해 점수를 매긴다","softmax, and mix the values = 소프트맥스를 하고 밸류를 섞는다","The result replaces that token's vector = 결과가 그 토큰의 벡터를 대신한다","Every token gets rewritten as a blend of the tokens it cares about = 모든 토큰이 자기가 신경 쓴 토큰들의 혼합으로 다시 쓰인다"]},{"kind":"steps","head":"세 단계를 이름으로 확인해요","steps":["1단계, q3 와 k1 ... k5 를 **내적(Dot Product)**해서 점수를 만들어요","2단계, 그 점수를 루트 d_k 로 나누고 소프트맥스에 넣어요","3단계, 나온 **어텐션 가중치(Attention Weight)**로 v1 ... v5 를 **가중합(Weighted Sum)**해요","결과 o3 는 Part 2 의 **문맥 벡터(Context Vector)** 와 같은 것이에요"],"answer":"Part 2 의 세 단계와 같아요. o3 가 바로 그때의 **문맥 벡터(Context Vector)** 예요."}],"pass3":[{"kind":"steps","head":"어텐션 가중치를 슬라이드에서 읽어요","given":"가중치 0.05, 0.10, 0.08, 0.62, 0.15","steps":["슬라이드의 막대 다섯 개가 0.05, 0.10, 0.08, 0.62, 0.15 예요","다 더하면 0.05 + 0.10 + 0.08 + 0.62 + 0.15 = 1.00 이에요","가장 큰 값은 네 번째인 0.62 이고, 네 번째 토큰은 uncle 이에요","그래서 his 를 다시 쓸 때 uncle 의 내용을 가장 많이 가져와요"],"answer":"his 의 새 벡터 o3 는 uncle 쪽으로 크게 기울어요. his 가 uncle 을 꾸미니 자연스러워요."},{"kind":"formula","head":"이 쪽의 두 식","tex":"\\alpha_{ij} = \\mathrm{softmax}_j\\left(\\frac{q_i^{\\top} k_j}{\\sqrt{d_k}}\\right), \\quad o_i = \\sum_j \\alpha_{ij} v_j","parts":[{"sym":"q_i^{\\top} k_j","say":"i 번째 쿼리와 j 번째 키의 내적"},{"sym":"\\sqrt{d_k}","say":"키 벡터의 칸 수의 제곱근으로 나눠요"},{"sym":"\\alpha_{ij}","say":"i 가 j 를 보는 **어텐션 가중치(Attention Weight)**"},{"sym":"\\sum_j","say":"모든 자리 j 에 대해 더해요"},{"sym":"o_i","say":"i 번째 토큰의 새 표현"}],"whole":"위는 **소프트맥스(Softmax)**, 아래는 **가중합(Weighted Sum)**이에요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: 한 토큰의 쿼리로 모든 키에 점수를 매기고, 소프트맥스하고, 밸류를 섞는다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.05,"say":"둘째 점: 결과가 그 토큰의 벡터를 대신한다. his 가 uncle 의 정보를 갖게 된다."},{"x":0.02,"y":0.34,"w":0.24,"h":0.1,"say":"왼쪽 위 번호 1 상자 안의 식이 어텐션 가중치 공식이에요."},{"x":0.15,"y":0.39,"w":0.55,"h":0.12,"say":"파란 막대와 0.05, 0.10, 0.08, 0.62, 0.15 가 어텐션 가중치예요."},{"x":0.15,"y":0.54,"w":0.55,"h":0.08,"say":"초록 상자 v1 ... v5 가 밸류, 그 아래 주황 상자가 키예요."},{"x":0.71,"y":0.53,"w":0.2,"h":0.17,"say":"오른쪽 파란 o3 가 새 표현, 보라 q3 가 his 의 쿼리예요."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 히스가 봤을 때 엉클 위치의 웨이트가 0.62 로 가장 크게 나왔죠.","교수님: 현재 히스를 표현할 때 엉클의 정보를 가장 많이 참고하고 있다는 거죠.","교수님: 처음에는 인풋 x3 였는데, 셀프 어텐션 레이어를 지나면 각 토큰마다 새로운 표현 o3 가 나와요."]}],"pass4":[{"kind":"check","q":"슬라이드에서 his 가 가장 크게 바라본 토큰은?","choices":["Zuko","made","uncle","tea"],"a":2,"why":"네 번째 막대 0.62 가 uncle 자리예요. his 가 uncle 을 꾸미니 자연스러운 **어텐션 가중치(Attention Weight)**예요."},{"kind":"english","head":"시험 답안 문장","en":"셀프 어텐션은 한 토큰의 쿼리를 모든 키와 비교해 점수를 만들고, 소프트맥스로 가중치를 얻은 뒤 밸류의 가중합으로 그 토큰의 새 표현을 만든다.","ko":"점수, 소프트맥스, 가중합의 세 단계를 그대로 쓰면 돼요.","tip":"Part 2 답안에서 인코더 상태만 밸류로 바꾸면 그대로예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["자기 자신도 포함해서 점수를 매겨요. q3 는 k3 와도 내적해요.","새 표현 o3 가 x3 를 완전히 갈아엎는 게 아니라, 다른 토큰의 정보가 섞인 새 벡터가 되는 거예요."]}]},{"p":36,"title":"셀프 어텐션의 식","terms":["Self-Attention","Scaled Dot-Product Attention","Attention Score","Attention Weight","Softmax","Weighted Sum","Query","Key","Value","Dot Product"],"pass1":[{"kind":"say","lines":["Part 2 에서 본 네 줄이 그대로 돌아왔어요.","달라진 것은 q, k, v 가 모두 같은 시퀀스에서 온다는 것, 그리고 루트 d_k 로 나눈다는 것뿐이에요.","슬라이드 아래 파란 상자의 한 줄이 오늘 가장 중요한 식이에요."]},{"kind":"analogy","head":"같은 옷, 다른 무늬","scene":"Part 2 의 식과 여기 식은 같은 옷인데 무늬만 바꿔 입은 거예요.","map":[["옷","점수, 소프트맥스, 가중합의 세 단계"],["바뀐 무늬","q, k, v 가 같은 시퀀스에서 온다"],["새로 단 단추","루트 d_k 로 나누기"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["The same four lines as 2장 = Part 2 와 같은 네 줄이다","now with q, k, v all coming from the same sequence = 이제 q, k, v 가 모두 같은 시퀀스에서 온다","plus one new factor we are about to justify = 그리고 곧 설명할 새 인자 하나가 더 있다","(1) similarity scores = 유사도 점수","(2) attention weights = 어텐션 가중치","(3) weighted sum of values = 밸류의 가중합"]},{"kind":"compare","head":"세 식의 이름과 하는 일","cols":["번호","이름","하는 일"],"rows":[["(1)","**어텐션 점수(Attention Score)**","쿼리와 키를 내적하고 루트 d_k 로 나눠요"],["(2)","**어텐션 가중치(Attention Weight)**","소프트맥스로 합이 1 이 되게 만들어요"],["(3)","가중합","밸류를 가중치만큼 섞어요"]]}],"pass3":[{"kind":"formula","head":"오늘 가장 중요한 한 줄","tex":"\\mathrm{Attention}(Q,K,V) = \\mathrm{softmax}\\!\\left(\\frac{QK^{\\top}}{\\sqrt{d_k}}\\right)V","parts":[{"sym":"Q","say":"쿼리들을 줄줄이 쌓은 행렬"},{"sym":"K^{\\top}","say":"키 행렬을 눕힌 것(전치)"},{"sym":"QK^{\\top}","say":"모든 쿼리와 모든 키의 내적을 한 번에"},{"sym":"\\sqrt{d_k}","say":"점수가 너무 커지지 않게 나눠 주는 값"},{"sym":"\\mathrm{softmax}","say":"줄마다 합이 1 이 되게"},{"sym":"V","say":"밸류 행렬, 실제로 섞이는 내용"}],"whole":"이 한 줄이 **스케일드 닷프로덕트 어텐션(Scaled Dot-Product Attention)**이에요. 시험에 나오면 이대로 쓰면 돼요."},{"kind":"steps","head":"작은 숫자로 손계산을 해 봐요","given":"d_k = 4, 쿼리 하나와 키 세 개","steps":["d_k = 4 로 두면 루트 d_k = 2 예요","q3 = (1, 1, 1, 1), k1 = (1, 1, 1, 1), k2 = (1, 1, 0, 0), k3 = (0, 0, 0, 0) 이라고 해요","내적은 q3 와 k1 은 4, k2 는 2, k3 는 0 이에요","루트 d_k = 2 로 나누면 점수가 2, 1, 0 이 돼요","소프트맥스: exp(2) = 7.389, exp(1) = 2.718, exp(0) = 1, 합은 11.107 이에요","각각 나누면 0.6652, 0.2447, 0.0900 이고 다 더하면 1 이에요","밸류가 v1 = (2, 0), v2 = (0, 2), v3 = (1, 1) 이면","o3 = 0.6652 x (2,0) + 0.2447 x (0,2) + 0.0900 x (1,1) = (1.4204, 0.5794) 예요"],"answer":"새 표현 o3 = (1.4204, 0.5794). v1 쪽으로 크게 기울었어요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"맨 위 한 줄: Part 2 와 같은 네 줄인데 q, k, v 가 같은 시퀀스에서 온다."},{"x":0.18,"y":0.36,"w":0.2,"h":0.16,"say":"왼쪽 식 (1) 이 유사도 점수 e_ij 예요."},{"x":0.39,"y":0.36,"w":0.22,"h":0.16,"say":"가운데 식 (2) 가 소프트맥스로 만든 어텐션 가중치 알파예요."},{"x":0.62,"y":0.36,"w":0.2,"h":0.16,"say":"오른쪽 식 (3) 이 밸류의 가중합 o_i 예요."},{"x":0.25,"y":0.57,"w":0.47,"h":0.14,"say":"파란 상자 안의 Attention(Q, K, V) 한 줄이 핵심이에요."},{"x":0.34,"y":0.86,"w":0.32,"h":0.04,"say":"맨 아래: 알아보겠어요? 이건 Part 2 가 옷만 갈아입은 것."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 스코어 계산하고, 소프트맥스 통해서 웨이트 만들고, 웨이티드 썸 하는 구조는 그대로예요.","교수님: 다른 건 쿼리, 키, 밸류를 나눴다는 거랑 스케일드 닷 프로덕트로 루트 d_k 로 나눴다는 것뿐이에요.","교수님: 트랜스포머 논문에서는 이 루트 d_k 때문에 스케일드 닷 프로덕트 어텐션이라고 표현을 해요."]}],"pass4":[{"kind":"check","q":"Attention(Q, K, V) 식에서 소프트맥스 안에 들어가는 것은?","choices":["$QK^{\\top}/\\sqrt{d_k}$","$QV^{\\top}$","$K V^{\\top}/\\sqrt{d_k}$","$Q + K$"],"a":0,"why":"**쿼리(Query)**와 **키(Key)**의 내적을 루트 d_k 로 나눈 것이 들어가요. **밸류(Value)**는 소프트맥스 밖에서 곱해져요."},{"kind":"exam","src":"N4 Check Yourself","q":"Q3 (Part 2). Why divide by root d_k, and what goes wrong if you forget?","qko":"왜 루트 d_k 로 나누나요? 안 나누면 무엇이 잘못되나요?","solve":["내적의 분산이 d_k 라서 차원이 크면 점수가 크게 퍼져요","큰 점수를 소프트맥스에 넣으면 한 칸이 거의 1 이 되는 뾰족한 분포가 돼요","포화된 소프트맥스는 기울기가 거의 0 이라 학습이 멈춰요","루트 d_k 로 나누면 분산이 다시 1 이 돼요"],"answer":"분산을 1 로 되돌리기 위해서예요. 안 나누면 소프트맥스가 포화되어 기울기가 사라져요."},{"kind":"english","head":"시험 답안 문장","en":"스케일드 닷프로덕트 어텐션은 쿼리와 키의 내적을 루트 d_k 로 나눈 뒤 소프트맥스를 취하고, 그 가중치로 밸류를 가중합한다.","ko":"식 한 줄과 나누는 이유 한 줄을 같이 적어요.","tip":"softmax(QK^T / 루트 d_k) V, 이 순서만 지키면 돼요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["K 를 전치(눕히기)해야 행렬 곱이 맞아요. Q 가 (n, d_k) 이고 K^T 가 (d_k, n) 이에요.","나누는 것은 d_k 가 아니라 루트 d_k 예요."]}]},{"p":37,"title":"한꺼번에: 행렬 형태","terms":["Self-Attention","Query","Key","Value","Parallelization","Softmax","Attention Weight","Token"],"pass1":[{"kind":"say","lines":["이제 토큰 하나가 아니라 문장 전체를 한 번에 계산해요.","쿼리를 모두 쌓아 Q, 키를 모두 쌓아 K, 밸류를 모두 쌓아 V 라는 행렬을 만들어요.","행렬 곱 세 번이면 끝이에요. 자리를 도는 반복문이 없어요.","이게 GPU 가 잘하는 모양이고 **병렬화(Parallelization)**의 정체예요."]},{"kind":"analogy","head":"한 명씩 vs 반 전체 한 번에","scene":"성적표를 한 명씩 계산하면 오래 걸리지만, 표를 통째로 엑셀에 넣고 한 번에 계산하면 순식간이에요.","map":[["한 명씩 계산","**RNN(순환 신경망)**"],["표 통째로 한 번에","**셀프 어텐션(Self-Attention)**"],["엑셀","GPU 의 행렬 곱"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Stack all the queries into a matrix Q = 모든 쿼리를 쌓아 행렬 Q 를 만든다","Three matrix multiplications and you are done = 행렬 곱 세 번이면 끝난다","No loop over positions = 자리를 도는 반복문이 없다","which is exactly why this runs so well on a GPU = 그래서 GPU 에서 아주 잘 돈다","The whole sequence in one batched matmul = 시퀀스 전체가 한 번의 묶음 행렬 곱"]},{"kind":"compare","head":"모양(shape) 따라가기","cols":["무엇","모양","뜻"],"rows":[["Q","n x d_k","토큰 n 개, 쿼리 칸 수 d_k"],["K 전치","d_k x n","곱셈이 맞게 눕힌 것"],["점수","n x n","토큰끼리 다 비교한 표"],["A","n x n","소프트맥스 뒤, 줄마다 합 1"],["O","n x d_v","새 표현, 토큰마다 한 줄"]]}],"pass3":[{"kind":"steps","head":"모양이 맞는지 손으로 따라가 봐요","given":"n = 5, d_k = 4, d_v = 3","steps":["토큰이 5개이고 d_k = 4, d_v = 3 이라고 해요","Q 는 (5, 4), K 는 (5, 4) 예요","K 를 눕히면 K 전치는 (4, 5) 가 돼요","(5, 4) 곱하기 (4, 5) 는 (5, 5) 예요. 가운데 4 가 사라져요","소프트맥스는 모양을 바꾸지 않으니 A 도 (5, 5) 예요","V 는 (5, 3) 이므로 (5, 5) 곱하기 (5, 3) 은 (5, 3) 이에요"],"answer":"최종 O 는 (5, 3). 토큰 하나당 새 표현 한 줄이에요."},{"kind":"figure","head":"한 번의 행렬 곱으로 전부","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"22\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">한 번의 행렬 곱으로 전부<\/text><rect x=\"16\" y=\"50\" width=\"68\" height=\"54\" rx=\"2\" class=\"box2 b1\"/><text x=\"50.0\" y=\"81.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">Q<\/text><text x=\"50\" y=\"118\" font-size=\"11\" text-anchor=\"middle\" class=\"tm b1\">n x d_k<\/text><text x=\"96\" y=\"80\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">x<\/text><rect x=\"108\" y=\"50\" width=\"68\" height=\"54\" rx=\"2\" class=\"box2 b1\"/><text x=\"142.0\" y=\"81.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">K^T<\/text><text x=\"142\" y=\"118\" font-size=\"11\" text-anchor=\"middle\" class=\"tm b1\">d_k x n<\/text><line x1=\"184\" y1=\"78\" x2=\"201.6\" y2=\"78.0\" class=\"e2 b2\"/><polygon points=\"208,78 200.0,74.0 200.0,82.0\" class=\"arrow b2\"/><rect x=\"214\" y=\"50\" width=\"68\" height=\"54\" rx=\"2\" class=\"box b2\"/><text x=\"248.0\" y=\"81.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">점수<\/text><text x=\"248\" y=\"118\" font-size=\"11\" text-anchor=\"middle\" class=\"tm b2\">n x n<\/text><line x1=\"290\" y1=\"78\" x2=\"307.6\" y2=\"78.0\" class=\"e2 b3\"/><polygon points=\"314,78 306.0,74.0 306.0,82.0\" class=\"arrow b3\"/><rect x=\"320\" y=\"50\" width=\"68\" height=\"54\" rx=\"2\" class=\"box2 b3\"/><text x=\"354.0\" y=\"81.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">A<\/text><text x=\"354\" y=\"118\" font-size=\"11\" text-anchor=\"middle\" class=\"tm b3\">n x n, 줄 합 1<\/text><text x=\"404\" y=\"80\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">x V<\/text><text x=\"240\" y=\"160\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">결과 O 의 모양은 n x d_v 예요<\/text><text x=\"240\" y=\"186\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">자리를 도는 for 문이 없어서 GPU 가 아주 잘해요<\/text><text x=\"240\" y=\"212\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">교수님: 패러럴이 핵심이에요<\/text><\/svg>","caption":"Q 와 K 전치를 곱하고, 소프트맥스하고, V 를 곱해요.","builds":4},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: 쿼리, 키, 밸류를 각각 쌓아 행렬 곱 세 번이면 끝난다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.05,"say":"둘째 점: 자리를 도는 반복문이 없어서 GPU 에서 잘 돌고 RNN 은 그렇지 못하다."},{"x":0.24,"y":0.32,"w":0.47,"h":0.13,"say":"파란 상자 안이 Attention(Q, K, V) 식이에요."},{"x":0.09,"y":0.58,"w":0.76,"h":0.16,"say":"가운데 그림이 Q x K 전치 -> 점수 -> A x V -> O 순서예요."},{"x":0.09,"y":0.74,"w":0.76,"h":0.04,"say":"상자 아래 작은 글씨가 각 행렬의 모양(n x d_k 등)이에요."},{"x":0.49,"y":0.76,"w":0.18,"h":0.04,"say":"A 아래 rows sum to 1 은 줄마다 합이 1 이라는 뜻이에요."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 모든 토큰의 쿼리를 쌓으면 행렬 Q 가 되고, 키를 쌓아 K, 밸류를 쌓아 V 를 만들 수 있어요.","교수님: Q K 전치를 계산하면 바로 n 바이 n 스코어 매트릭스가 나와요.","교수님: GPU 는 매트릭스를 올려놓고 포워드 백워드 치우는 걸 잘하기 때문에 병렬 연산을 아주 잘 활용할 수 있는 구조예요.","교수님: RNN 은 t 를 처리하려면 t-1 까지 다 처리했어야 하는데, 얘는 앞에 있는 거랑 같이 처리할 수가 있다는 거죠."]},{"kind":"bg","src":"기초 다지기 3단원","lines":["(a, b) 모양과 (b, c) 모양을 곱하면 (a, c) 가 돼요. 가운데 b 가 맞아야 곱할 수 있어요.","전치(transpose)는 표를 눕혀서 행과 열을 바꾸는 것이에요."]}],"pass4":[{"kind":"check","q":"토큰이 n 개일 때 점수 행렬의 모양은?","choices":["n x d_k","n x n","d_k x d_k","n x d_v"],"a":1,"why":"모든 토큰이 모든 토큰과 비교되므로 n 줄 n 칸짜리 정사각형 표가 나와요."},{"kind":"exam","src":"N4 Check Yourself","q":"Q6 (Part 2, 일부). Why is attention O(n squared)?","qko":"어텐션의 비용이 왜 n 의 제곱인가요?","solve":["점수 행렬이 n 줄 n 칸이에요","칸 하나가 토큰 한 쌍의 점수라서 칸이 n x n 개예요","그래서 계산도 메모리도 n 의 제곱으로 늘어요","n = 512 면 262,144 칸인데 n = 128,000 이면 약 164억 칸이에요"],"answer":"점수 행렬이 n x n 이기 때문이에요. 자세한 이야기는 p.55 에서 해요."},{"kind":"english","head":"시험 답안 문장","en":"셀프 어텐션은 Q, K, V 를 행렬로 쌓아 한 번의 행렬 곱으로 계산하므로 위치마다 순서대로 돌 필요가 없고, 따라서 GPU 에서 병렬 처리가 가능하다.","ko":"병렬화가 가능한 이유를 반복문이 없다는 말로 설명해요.","tip":"교수님이 패러럴이 핵심이라고 한 바로 그 부분이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["d_k 와 d_v 는 달라도 돼요. 점수는 d_k 로, 결과 칸 수는 d_v 로 정해져요.","**병렬화(Parallelization)**가 된다고 계산량이 줄어드는 건 아니에요. 동시에 할 뿐이에요."]}]},{"p":38,"title":"왜 루트 d_k 로 나눌까요","terms":["Scaled Dot-Product Attention","Softmax","Attention Score","Attention Weight","Gradient","Dot Product","Self-Attention"],"pass1":[{"kind":"say","lines":["오늘 유일하게 새로 생긴 나누기 한 번의 이유를 설명하는 쪽이에요.","칸 수가 많아질수록 내적 값이 크게 퍼져요.","점수가 크면 소프트맥스가 한 칸만 보는 뾰족한 모양이 되고, 그러면 기울기가 사라져요.","루트 d_k 로 나누면 퍼짐이 다시 1 로 돌아와요."]},{"kind":"analogy","head":"확성기 볼륨 줄이기","scene":"볼륨을 너무 키우면 제일 큰 소리만 들리고 나머지는 하나도 안 들려요. 볼륨을 적당히 낮추면 여러 소리를 함께 들을 수 있어요.","map":[["너무 큰 볼륨","나누지 않은 큰 점수"],["들리는 소리 하나","뾰족한 소프트맥스"],["볼륨 낮추기","루트 d_k 로 나누기"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["If q and k have independent unit-variance entries = q 와 k 의 각 칸이 서로 독립이고 분산이 1 이면","their dot product has variance d_k = 그 내적의 분산은 d_k 이다","with d_k = 512 the scores are typically plus or minus 20 or more = d_k 가 512 면 점수가 보통 플러스마이너스 20 이상이다","Huge scores make softmax nearly one-hot = 큰 점수는 소프트맥스를 거의 원-핫으로 만든다","a saturated softmax has almost no gradient = 포화된 소프트맥스는 기울기가 거의 없다","Dividing by root d_k puts the variance back to 1 = 루트 d_k 로 나누면 분산이 다시 1 이 된다"]},{"kind":"compare","head":"차원이 커지면 점수가 얼마나 퍼지나","cols":["d_k","표준편차 = 루트 d_k","점수 범위 느낌"],"rows":[["8","2.83","좁게 모여 있어요"],["64","8.0","조금 퍼져요"],["512","22.63","플러스마이너스 20 을 넘어요"]]}],"pass3":[{"kind":"formula","head":"내적의 분산","tex":"q \\cdot k = \\sum_{m=1}^{d_k} q_m k_m, \\quad \\mathrm{Var}(q \\cdot k) = d_k \\Rightarrow \\mathrm{sd} = \\sqrt{d_k}","parts":[{"sym":"q_m k_m","say":"같은 자리끼리 곱한 것"},{"sym":"\\sum_{m=1}^{d_k}","say":"칸 수 d_k 만큼 더해요"},{"sym":"\\mathrm{Var}","say":"얼마나 넓게 퍼지는지를 재는 값"},{"sym":"\\sqrt{d_k}","say":"퍼짐의 크기, 곧 표준편차"}],"whole":"칸을 많이 더할수록 결과가 크게 흔들려요. 그래서 루트 d_k 로 나눠요."},{"kind":"steps","head":"나누기 전과 후를 숫자로 비교해요","given":"점수 4, 2, 0","steps":["점수가 4, 2, 0 이라고 해 봐요","그대로 소프트맥스하면 0.8668, 0.1173, 0.0159 예요. 첫 칸이 거의 다 가져가요","d_k = 4 이므로 루트 d_k = 2 로 나누면 점수가 2, 1, 0 이 돼요","다시 소프트맥스하면 0.6652, 0.2447, 0.0900 이에요","가장 큰 값이 0.8668 에서 0.6652 로 내려가고 나머지가 살아났어요"],"answer":"나눠 주면 분포가 덜 뾰족해져요. 여러 자리를 함께 볼 수 있어요."},{"kind":"steps","head":"극단적인 경우도 봐요","given":"점수 20, 0, 1 과 d_k = 512","steps":["점수가 20, 0, 1 이라고 해 봐요. d_k = 512 라면 흔한 크기예요","그대로 소프트맥스하면 첫 칸이 거의 1, 나머지는 거의 0 이에요","루트 512 는 약 22.63 이에요","22.63 으로 나누면 점수가 약 0.88, 0, 0.04 가 돼요","소프트맥스하면 0.5420, 0.2239, 0.2341 로 골고루 퍼져요"],"answer":"나누지 않으면 사실상 한 칸만 보는 셈이 돼요. 기울기도 거의 0 이에요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.09,"say":"첫 점: q 와 k 의 칸이 독립이고 분산 1 이면 내적의 분산이 d_k 가 된다."},{"x":0.05,"y":0.28,"w":0.9,"h":0.05,"say":"둘째 점: 큰 점수는 소프트맥스를 거의 원-핫으로 만들고 기울기를 없앤다."},{"x":0.22,"y":0.37,"w":0.26,"h":0.31,"say":"왼쪽 그래프: d_k 가 8, 64, 512 로 커질수록 분포가 넓게 퍼져요."},{"x":0.5,"y":0.37,"w":0.29,"h":0.31,"say":"오른쪽 그래프: 빨강은 안 나눈 것, 초록은 나눈 것이에요."},{"x":0.28,"y":0.72,"w":0.45,"h":0.09,"say":"아래 식이 내적의 분산이 d_k 이고 표준편차가 루트 d_k 라는 뜻이에요."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: q 와 k 의 각 성분이 평균 0, 분산 1 이고 서로 독립이라고 가정하면 내적의 분산이 d_k 가 돼요.","교수님: 값이 너무 커지면 소프트맥스 특성상 큰 값에 너무 몰리게 돼요. 뾰족해지는 거죠.","교수님: 그레디언트가 매우 작아져서 학습 효율이 매우 안 좋습니다.","교수님: 이 슬라이드는 이해가 어렵다면 그냥 스코어 스케일이 너무 커지니까 줄여 준다고 봐도 괜찮아요."]},{"kind":"bg","src":"기초 다지기 6단원","lines":["**소프트맥스(Softmax)**는 점수 차이를 exp 로 키워요. 점수 차이가 2 면 exp 차이는 약 7.4 배예요.","그래서 점수 범위가 커질수록 분포가 훨씬 빨리 뾰족해져요."]}],"pass4":[{"kind":"check","q":"루트 d_k 로 나누지 않으면 생기는 문제는?","choices":["소프트맥스가 포화되어 기울기가 거의 0 이 된다","합이 1 이 되지 않는다","행렬 곱의 모양이 맞지 않는다","밸류가 음수가 된다"],"a":0,"why":"합은 **소프트맥스(Softmax)**가 늘 1 로 만들어 줘요. 문제는 분포가 뾰족해져 **기울기(Gradient)**가 사라지는 것이에요."},{"kind":"english","head":"시험 답안 문장","en":"쿼리와 키의 내적은 분산이 d_k 이므로 차원이 크면 점수가 크게 퍼진다. 큰 점수는 소프트맥스를 포화시켜 기울기를 없애므로 루트 d_k 로 나누어 분산을 1 로 되돌린다.","ko":"분산 d_k, 포화, 기울기 소멸의 세 낱말을 꼭 넣어요.","tip":"분산이 d_k 니까 표준편차는 루트 d_k, 그래서 루트 d_k 로 나눈다."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["d_k 로 나누는 게 아니라 루트 d_k 로 나눠요. 분산이 아니라 표준편차를 맞추는 거예요.","나눈다고 점수의 순서가 바뀌지는 않아요. 순서는 그대로이고 간격만 좁아져요."]}]},{"p":39,"title":"아직 세 가지가 빠졌어요","terms":["Self-Attention","Permutation Equivariance","Positional Encoding","Position-wise Feed-Forward Network (FFN)","Causal Masking","Nonlinearity","Transformer","Language Model (LM)"],"pass1":[{"kind":"say","lines":["**셀프 어텐션(Self-Attention)**만으로는 아직 쌓을 수 있는 층이 아니에요.","구멍이 세 개 있어요. 교수님이 배리어 3개라고 불렀어요.","순서를 모른다, 비선형이 없다, 미래를 훔쳐본다.","이 세 구멍을 각각 한 부품으로 막으면 그게 **트랜스포머(Transformer)** 블록이에요."]},{"kind":"analogy","head":"자전거에 빠진 세 부품","scene":"바퀴만 있다고 자전거가 되지 않아요. 안장, 페달, 브레이크가 있어야 탈 수 있어요.","map":[["바퀴","**셀프 어텐션(Self-Attention)**"],["빠진 세 부품","위치 인코딩, FFN, 인과 마스킹"],["완성된 자전거","**트랜스포머(Transformer)**"]]}],"pass2":[{"kind":"points","head":"배리어 3개와 고치는 부품","items":["배리어 1, 순서를 모른다 -> **위치 인코딩(Positional Encoding)**","배리어 2, 자리마다의 비선형 변환이 없다 -> **위치별 피드포워드 신경망(Position-wise Feed-Forward Network (FFN))**","배리어 3, 미래를 볼 수 있다 -> **인과 마스킹(Causal Masking)**"]},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Three Things Are Still Missing = 아직 세 가지가 빠졌다","not a layer you can stack = 쌓을 수 있는 층이 아니다","No notion of order = 순서 개념이 없다","No elementwise nonlinearity = 칸마다의 비선형성이 없다","It can peek at the future = 미래를 훔쳐볼 수 있다","Barrier to fix, this is the whole design of the Transformer block = 배리어와 그 해결이 곧 트랜스포머 블록의 설계다"]},{"kind":"compare","head":"배리어와 부품 짝 맞추기","cols":["배리어","무엇이 문제인가","고치는 부품"],"rows":[["1. 순서 없음","순서를 바꿔도 결과가 그대로 따라감","**위치 인코딩(Positional Encoding)**"],["2. 비선형 없음","어텐션 층을 쌓아도 결국 선형 변환","**위치별 피드포워드 신경망(Position-wise Feed-Forward Network (FFN))**"],["3. 미래 훔쳐보기","언어 모델 과제가 너무 쉬워져 버림","**인과 마스킹(Causal Masking)**"]]}],"pass3":[{"kind":"formula","head":"배리어 1 을 식으로","tex":"\\mathrm{SelfAttn}(PX) = P\\,\\mathrm{SelfAttn}(X)","parts":[{"sym":"X","say":"토큰들을 쌓은 입력 행렬"},{"sym":"P","say":"순서를 뒤섞는 연산(순열)"},{"sym":"\\mathrm{SelfAttn}(PX)","say":"먼저 섞고 나서 셀프 어텐션"},{"sym":"P\\,\\mathrm{SelfAttn}(X)","say":"먼저 셀프 어텐션하고 나서 섞기"}],"whole":"두 결과가 같아요. 이 성질을 **순열 등변성(Permutation Equivariance)**이라고 해요. 곧 순서를 전혀 모른다는 뜻이에요."},{"kind":"steps","head":"순열 등변성을 숫자로 확인해요","given":"임의의 X 와 순열 P","steps":["토큰 3개짜리 입력 X 를 아무거나 하나 잡아요","1번과 2번 토큰의 자리를 바꾸는 순열 P 를 준비해요","먼저 자리를 바꾸고 셀프 어텐션을 해 봐요","이번에는 셀프 어텐션을 먼저 하고 자리를 바꿔 봐요","두 결과가 소수점까지 똑같아요"],"answer":"셀프 어텐션은 누가 먼저 왔는지를 전혀 모릅니다. 그래서 위치 인코딩이 필요해요."},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.07,"say":"맨 위 한 줄: 셀프 어텐션만으로는 쌓을 수 있는 층이 아니고 구조적 빈틈이 셋 있다."},{"x":0.07,"y":0.32,"w":0.27,"h":0.33,"say":"왼쪽 상자: 1. 순서 개념이 없다. 해결은 positional encoding."},{"x":0.36,"y":0.32,"w":0.27,"h":0.33,"say":"가운데 상자: 2. 칸마다 비선형이 없다. 해결은 position-wise feed-forward net."},{"x":0.65,"y":0.32,"w":0.28,"h":0.33,"say":"오른쪽 상자: 3. 미래를 볼 수 있다. 해결은 causal masking."},{"x":0.18,"y":0.68,"w":0.64,"h":0.11,"say":"아래 큰 식 SelfAttn(PX) = P SelfAttn(X) 가 배리어 1 의 증거예요."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 이 셀프 어텐션 여기까지만으로는 완벽한 트랜스포머 레이어가 아직 아니에요.","교수님: 이 배리어 3개를 기억해 봅시다.","교수님: 순서 정보 때문에 포지셔널 인코딩, 토큰별 비선형 변환 때문에 포지션 와이즈 피드 포워드, 미래 정보 차단 때문에 커즐 마스킹.","교수님: 이 3개의 팬시한 방법을 추가해서 트랜스포머가 되는 거죠."]}],"pass4":[{"kind":"check","q":"셀프 어텐션의 배리어 2 를 고치는 부품은?","choices":["**위치 인코딩(Positional Encoding)**","**위치별 피드포워드 신경망(Position-wise Feed-Forward Network (FFN))**","**인과 마스킹(Causal Masking)**","**멀티 헤드 어텐션(Multi-Head Attention (MHA))**"],"a":1,"why":"비선형이 없다는 문제는 **위치별 피드포워드 신경망(Position-wise Feed-Forward Network (FFN))**이 막아요. **렐루(ReLU)** 가 그 안에 들어 있어요."},{"kind":"exam","src":"N4 Check Yourself","q":"Q5 (Part 2). Name the three barriers of plain self-attention and the component that fixes each.","qko":"맨 셀프 어텐션의 배리어 세 가지와 각각을 고치는 부품을 말해 보세요.","solve":["1. 순서를 모른다 -> 위치 인코딩(positional encoding)","2. 칸마다 비선형이 없다 -> 위치별 FFN(position-wise feed-forward network)","3. 미래를 볼 수 있다 -> 인과 마스킹(causal masking)","이 셋을 더한 것이 트랜스포머 블록의 기본 뼈대예요"],"answer":"순서, 비선형, 미래. 그리고 위치 인코딩, FFN, 마스킹."},{"kind":"english","head":"시험 답안 문장","en":"맨 셀프 어텐션은 순서 정보가 없고, 칸별 비선형이 없으며, 미래 토큰을 볼 수 있다. 각각 위치 인코딩, 위치별 FFN, 인과 마스킹으로 해결한다.","ko":"배리어 세 개와 부품 세 개를 짝지어 한 문장으로 쓰면 만점이에요.","tip":"순-비-미, 위-피-마 로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**순열 등변성(Permutation Equivariance)**은 순서를 무시한다는 뜻이 아니라, 순서를 바꾸면 결과도 똑같이 따라 바뀐다는 뜻이에요. 결국 순서를 구별하지 못한다는 말이에요.","배리어 3 은 **언어 모델(Language Model (LM))**을 학습할 때의 문제예요. 인코더는 오히려 앞뒤를 다 봐도 괜찮아요."]}]},{"p":40,"title":"배리어 1: 위치 인코딩","terms":["Positional Encoding","Sinusoidal Positional Encoding","Embedding","Self-Attention","Permutation Equivariance","Token"],"pass1":[{"kind":"say","lines":["dog bites man 과 man bites dog 는 단어가 똑같아요. 순서만 달라요.","그런데 **셀프 어텐션(Self-Attention)**은 순서를 몰라서 둘을 구별하지 못해요.","그래서 자리마다 벡터 하나를 만들어 **임베딩(Embedding)** 에 더해 줘요. 그게 **위치 인코딩(Positional Encoding)**이에요.","원래 논문은 sin 과 cos 파도로 그 벡터를 만들었어요."]},{"kind":"analogy","head":"같은 옷에 번호표 달기","scene":"체육대회에서 똑같은 체육복을 입은 학생이 둘이면 누가 누군지 몰라요. 가슴에 1번, 3번 번호표를 붙이면 구별이 돼요.","map":[["똑같은 체육복","같은 단어의 임베딩"],["번호표","**위치 인코딩(Positional Encoding)**"],["붙인 뒤의 모습","위치가 섞인 입력 벡터"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["dog bites man vs man bites dog = 개가 사람을 문다 vs 사람이 개를 문다","Give every position a vector = 모든 자리에 벡터를 하나씩 준다","add it to the token embedding before the first layer = 첫 층에 들어가기 전에 토큰 임베딩에 더한다","Now identical words at different positions differ = 이제 같은 단어라도 자리가 다르면 달라진다","sinusoids of geometrically spaced frequencies = 주파수가 기하적으로 벌어지는 사인 파도들","Order is not in the mechanism, so we put it in the input = 순서가 기계 안에 없으니 입력에 넣는다"]},{"kind":"compare","head":"위치 인코딩을 넣기 전과 후","cols":["상황","dog 가 1번 자리","dog 가 3번 자리"],"rows":[["넣기 전","같은 벡터","같은 벡터"],["넣은 후","임베딩 + 1번 자리 벡터","임베딩 + 3번 자리 벡터"]]}],"pass3":[{"kind":"formula","head":"사인 코사인 위치 인코딩","tex":"PE_{pos,\\,2i} = \\sin\\!\\left(\\frac{pos}{10000^{2i/d}}\\right), \\quad PE_{pos,\\,2i+1} = \\cos\\!\\left(\\frac{pos}{10000^{2i/d}}\\right)","parts":[{"sym":"pos","say":"몇 번째 자리인지 (0, 1, 2, ...)"},{"sym":"i","say":"벡터의 몇 번째 칸 쌍인지"},{"sym":"d","say":"임베딩의 전체 칸 수"},{"sym":"10000^{2i/d}","say":"칸마다 파도의 길이를 다르게 만드는 값"},{"sym":"\\sin","say":"짝수 칸에는 사인"},{"sym":"\\cos","say":"홀수 칸에는 코사인"}],"whole":"칸마다 파장이 다른 파도를 배치해서 자리마다 고유한 무늬를 만들어요. 이게 **사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)**이에요."},{"kind":"steps","head":"위치 벡터를 직접 계산해 봐요 (d = 4)","given":"pos = 0, 1, 2 이고 d = 4","steps":["d = 4 이면 칸이 네 개, 쌍은 두 개(i = 0, 1) 예요","i = 0 이면 분모가 10000의 0제곱 = 1 이라 각도가 곧 pos 예요","i = 1 이면 분모가 10000의 0.5제곱 = 100 이라 각도가 pos / 100 이에요","자리 0: sin(0) = 0, cos(0) = 1, sin(0) = 0, cos(0) = 1 이라 (0, 1, 0, 1) 이에요","자리 1: sin(1) = 0.8415, cos(1) = 0.5403, sin(0.01) = 0.01, cos(0.01) = 1.0","자리 2: sin(2) = 0.9093, cos(2) = -0.4161, sin(0.02) = 0.02, cos(0.02) = 0.9998"],"answer":"자리마다 값이 다르니, 같은 dog 여도 1번 자리와 3번 자리의 입력이 달라져요."},{"kind":"figure","head":"같은 단어, 다른 자리","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"22\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">같은 단어, 다른 자리<\/text><rect x=\"40\" y=\"50\" width=\"130\" height=\"28\" rx=\"2\" class=\"box b1\"/><text x=\"105.0\" y=\"68.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">dog 임베딩<\/text><rect x=\"310\" y=\"50\" width=\"130\" height=\"28\" rx=\"2\" class=\"box b1\"/><text x=\"375.0\" y=\"68.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">dog 임베딩<\/text><text x=\"105\" y=\"100\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">+ 자리 0 벡터<\/text><text x=\"375\" y=\"100\" font-size=\"13\" text-anchor=\"middle\" class=\"t b2\">+ 자리 2 벡터<\/text><rect x=\"40\" y=\"114\" width=\"130\" height=\"28\" rx=\"2\" class=\"box2 b3\"/><text x=\"105.0\" y=\"132.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">(0, 1, 0, 1)<\/text><rect x=\"310\" y=\"114\" width=\"130\" height=\"28\" rx=\"2\" class=\"box2 b3\"/><text x=\"375.0\" y=\"131.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tb b3\">(0.9093, -0.4161, 0.02, 0.9998)<\/text><line x1=\"105\" y1=\"148\" x2=\"105.0\" y2=\"167.6\" class=\"e2 b4\"/><polygon points=\"105,174 109.0,166.0 101.0,166.0\" class=\"arrow b4\"/><line x1=\"375\" y1=\"148\" x2=\"375.0\" y2=\"167.6\" class=\"e2 b4\"/><polygon points=\"375,174 379.0,166.0 371.0,166.0\" class=\"arrow b4\"/><text x=\"105\" y=\"196\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">첫 자리 dog<\/text><text x=\"375\" y=\"196\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">셋째 자리 dog<\/text><text x=\"240\" y=\"228\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">더한 값이 달라져서 순서가 살아나요<\/text><\/svg>","caption":"dog 임베딩에 자리 벡터를 더하면 값이 달라져요.","builds":4},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: dog bites man 과 man bites dog 의 대비."},{"x":0.05,"y":0.25,"w":0.9,"h":0.06,"say":"둘째 점: 자리마다 벡터를 주고 첫 층 전에 임베딩에 더한다."},{"x":0.05,"y":0.31,"w":0.9,"h":0.05,"say":"셋째 점: 원래 선택은 주파수가 다른 사인 파도들이었다."},{"x":0.21,"y":0.36,"w":0.28,"h":0.32,"say":"왼쪽 히트맵: 가로가 칸, 세로가 자리예요. 자리마다 무늬가 달라요."},{"x":0.5,"y":0.36,"w":0.28,"h":0.32,"say":"오른쪽 그래프: 칸마다 파장이 다른 세 파도를 보여 줘요."},{"x":0.2,"y":0.72,"w":0.58,"h":0.12,"say":"파란 상자 안의 두 식이 외워야 할 위치 인코딩 공식이에요."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 위치 인코딩이 없으면 각 토큰이 몇 번째 위치에 있는지 알려 주는 장치가 없어요.","교수님: 각 위치마다 서로 다른 포지션 벡터를 만들어서 단어 벡터에 더해 주는 거예요.","교수님: 사인 코사인을 쓴 장점은 추가 학습 파라미터가 없다는 거예요.","교수님: 사인 코사인 성질 때문에 두 위치 사이의 상대적인 거리 정보도 모델이 쉽게 활용할 수 있죠."]},{"kind":"bg","src":"기초 다지기 4단원","lines":["10000의 0제곱은 1 이에요. 어떤 수든 0제곱은 1 이에요.","sin 과 cos 은 -1 과 1 사이를 오가는 물결 모양 함수예요."]}],"pass4":[{"kind":"check","q":"위치 인코딩은 언제 더해지나요?","choices":["첫 층에 들어가기 전, 토큰 임베딩에","소프트맥스 다음에","마지막 층 출력에","밸류에만"],"a":0,"why":"입력 **임베딩(Embedding)** 에 더해서 첫 층으로 보내요. 그래야 모든 층이 순서를 알 수 있어요."},{"kind":"english","head":"시험 답안 문장","en":"셀프 어텐션은 순열 등변성 때문에 순서를 구별하지 못하므로, 자리마다 다른 위치 벡터를 만들어 토큰 임베딩에 더한다. 원래 논문은 파장이 다른 sin 과 cos 을 썼다.","ko":"왜 필요한지, 어떻게 넣는지, 무엇으로 만드는지 세 조각을 다 적어요.","tip":"순서는 기계 안에 없으니 입력에 넣는다, 이 한 줄이 요약이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["위치 인코딩은 이어 붙이는(concat) 게 아니라 더하는(add) 거예요.","**사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)**은 학습하지 않아요. 파라미터가 0 개예요."]}]},{"p":41,"title":"어떤 위치 인코딩을 쓸까요","terms":["Positional Encoding","Sinusoidal Positional Encoding","RoPE","BERT","GPT","Large Language Model (LLM)","Query","Key","Parameter"],"pass1":[{"kind":"say","lines":["**위치 인코딩(Positional Encoding)**을 만드는 방법이 크게 세 가지예요.","고정된 sin 과 cos, 자리마다 학습하는 벡터, 그리고 회전 방식이에요.","요즘 **대규모 언어 모델(Large Language Model (LLM))** 은 거의 다 세 번째인 **로프(RoPE)** 를 써요.","이번 주 범위는 첫 번째예요."]},{"kind":"analogy","head":"주소를 적는 세 가지 방법","scene":"집 위치를 알려 줄 때 고정된 좌표를 쓰거나, 동네마다 붙인 번호를 외우거나, 여기서 몇 걸음 떨어졌는지를 말할 수 있어요.","map":[["고정 좌표","**사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)**"],["동네마다 붙인 번호","학습하는 절대 위치 임베딩"],["몇 걸음 떨어졌는지","**로프(RoPE)**"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Three families, and the field has largely converged on the third = 세 갈래가 있고 학계는 대체로 세 번째로 모였다","Modern LLMs use RoPE = 요즘 대규모 언어 모델은 RoPE 를 쓴다","it rotates q and k by an angle proportional to position = 위치에 비례한 각도로 q 와 k 를 회전시킨다","the attention score depends only on the relative offset i minus j = 어텐션 점수가 상대 거리 i - j 에만 의존한다","That is what lets context windows stretch = 그래서 문맥 창을 길게 늘일 수 있다"]},{"kind":"compare","head":"세 가지 위치 인코딩","cols":["방법","무엇인가","성질","쓰는 곳"],"rows":[["Sinusoidal","고정된 sin, cos 파도","학습 파라미터가 아예 없음","원래 트랜스포머"],["Learned absolute","자리마다 학습하는 벡터 하나","학습 때 정한 길이를 넘지 못함","BERT, GPT-2"],["Relative / RoPE","위치에 비례한 각도로 q, k 회전","학습 길이를 훨씬 넘어서도 잘 됨","T5, LLaMA, 대부분의 LLM"]]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: 세 갈래가 있고 학계는 세 번째로 모였다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.07,"say":"둘째 점: RoPE 는 q 와 k 를 위치에 비례해 회전시켜 상대 거리에만 의존하게 만든다."},{"x":0.07,"y":0.42,"w":0.86,"h":0.05,"say":"표 머리글: method, what it is, property, used by."},{"x":0.07,"y":0.5,"w":0.86,"h":0.06,"say":"첫 줄 Sinusoidal: 고정된 sin, cos 이고 파라미터가 아예 없어요."},{"x":0.07,"y":0.59,"w":0.86,"h":0.06,"say":"둘째 줄 Learned absolute: 자리마다 학습 벡터. 학습 길이를 넘지 못해요."},{"x":0.07,"y":0.68,"w":0.86,"h":0.07,"say":"셋째 줄 Relative / RoPE: 회전 방식. 학습 길이 밖으로도 잘 늘어나요."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 세 번째가 릴레이티브 포지션 계열이고 요새 현대 모델이에요. 제가 회사에 있을 때 가장 많이 했던 연구가 이거예요.","교수님: 포지션 벡터를 임베딩에 더하는 대신 회전의 개념을 도입시키는 거예요.","교수님: 회전시키면 q_i 와 k_j 의 내적에 상대적 거리 i - j 가 자연스럽게 들어가요.","교수님: 요새 대부분의 LLM 은 그냥 RoPE 쓴다고 보시면 되겠습니다. 다만 이번 주까지는 첫 번째 사인 코사인 방식을 볼 거예요."]},{"kind":"bg","src":"기초 다지기 1단원","lines":["벡터를 회전시킨다는 것은 화살표의 방향을 각도만큼 돌리는 것이에요.","길이는 그대로 두고 방향만 바꾸기 때문에 크기가 변하지 않아요."]}],"pass4":[{"kind":"check","q":"학습 파라미터가 하나도 없는 위치 인코딩은?","choices":["**사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)**","학습하는 절대 위치 임베딩","**로프(RoPE)**","인과 마스킹"],"a":0,"why":"**사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)**은 식으로 값을 바로 계산하기 때문에 배울 것이 없어요."},{"kind":"english","head":"시험 답안 문장","en":"사인 코사인 위치 인코딩은 파라미터가 없고, 학습형 절대 위치 임베딩은 학습한 길이를 넘지 못하며, RoPE 는 쿼리와 키를 위치에 비례해 회전시켜 상대 거리만으로 점수를 정하므로 긴 문맥으로 잘 늘어난다.","ko":"세 가지를 한 문장에 성질과 함께 적어요.","tip":"파라미터 없음 / 길이에 묶임 / 길이 밖으로 늘어남, 세 낱말이면 표가 다 떠올라요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**버트(BERT)** 와 **지피티(GPT)** 는 사인 코사인이 아니라 학습형 절대 위치를 썼어요.","**로프(RoPE)** 는 더하기가 아니라 회전이에요. 더하는 방식과 구조가 달라요."]}]},{"p":42,"title":"배리어 2: 피드포워드 층","terms":["Position-wise Feed-Forward Network (FFN)","Nonlinearity","ReLU","Multi-Layer Perceptron (MLP)","Parameter","Attention","Self-Attention","Token"],"pass1":[{"kind":"say","lines":["**셀프 어텐션(Self-Attention)** 뒤에 자리마다 똑같은 작은 신경망을 붙여요. 그게 **위치별 피드포워드 신경망(Position-wise Feed-Forward Network (FFN))**이에요.","같은 2층짜리 **MLP(다층 퍼셉트론)** 를 각 자리에 따로 적용해요. 자리끼리 섞이지 않아요.","역할 분담이에요. **어텐션(Attention)**은 정보를 옮기고, FFN 은 각 토큰을 가공해요.","파라미터가 가장 많이 사는 곳이기도 해요."]},{"kind":"analogy","head":"택배와 공장","scene":"택배가 물건을 이 집 저 집 옮겨 주고, 공장은 각 집에서 받은 재료를 가공해 새 물건을 만들어요.","map":[["택배","**어텐션(Attention)**"],["집집마다 있는 같은 공장","**위치별 피드포워드 신경망(Position-wise Feed-Forward Network (FFN))**"],["가공된 물건","그 자리의 새 표현"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Apply the same two-layer MLP to every position independently = 같은 2층 MLP 를 모든 자리에 따로 적용한다","No mixing across positions happens here = 여기서는 자리끼리 섞이지 않는다","Division of labour = 역할 분담","attention moves information between tokens = 어텐션은 토큰 사이에서 정보를 옮긴다","the FFN transforms each token = FFN 은 각 토큰을 변환한다","It is also where most of the parameters live = 파라미터 대부분이 여기 산다","d_ff is usually 4d = 가운데 차원은 보통 4d 이다"]},{"kind":"compare","head":"어텐션과 FFN 의 역할 분담","cols":["부품","하는 일","자리끼리 섞이나"],"rows":[["**어텐션(Attention)**","토큰 사이에서 정보를 옮겨요","섞여요"],["**위치별 피드포워드 신경망(Position-wise Feed-Forward Network (FFN))**","각 토큰을 **MLP(다층 퍼셉트론)** 로 혼자서 가공해요","안 섞여요"]]}],"pass3":[{"kind":"formula","head":"FFN 식","tex":"\\mathrm{FFN}(x) = \\max(0,\\, xW_1 + b_1)W_2 + b_2, \\quad W_1 \\in \\mathbb{R}^{d \\times 4d}","parts":[{"sym":"x","say":"한 자리의 벡터 하나"},{"sym":"W_1","say":"칸 수를 d 에서 4d 로 늘리는 행렬"},{"sym":"\\max(0, \\cdot)","say":"음수는 0 으로 만드는 **렐루(ReLU)**"},{"sym":"W_2","say":"다시 4d 에서 d 로 줄이는 행렬. 둘이 합쳐 **MLP(다층 퍼셉트론)** 한 개예요"},{"sym":"b_1, b_2","say":"편향 항(bias term)"}],"whole":"넓혔다 좁히는 사다리꼴이에요. 가운데의 max(0, ...) 가 **비선형성(Nonlinearity)**을 만들어요."},{"kind":"steps","head":"파라미터 수를 세어 봐요 (d = 512)","given":"d = 512, d_ff = 2048","steps":["d = 512 이면 d_ff = 4d = 2048 이에요","W1 은 512 곱하기 2048 = 1,048,576 개예요","W2 는 2048 곱하기 512 = 1,048,576 개예요","둘을 더하면 2,097,152 개이고, 이는 8 곱하기 512의 제곱과 같아요","어텐션의 W^Q, W^K, W^V, W^O 는 각각 512 x 512 라서 4 곱하기 512의 제곱 = 1,048,576 개예요","그러니까 FFN 이 어텐션 쪽보다 파라미터가 두 배예요"],"answer":"FFN 이 8d 제곱, 어텐션 투영이 4d 제곱. 파라미터 대부분이 FFN 에 살아요."},{"kind":"figure","head":"어텐션은 옮기고, FFN 은 가공해요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"22\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">어텐션은 옮기고, FFN 은 가공해요<\/text><rect x=\"28\" y=\"170\" width=\"92\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"74.0\" y=\"188.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">x1<\/text><rect x=\"138\" y=\"170\" width=\"92\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"184.0\" y=\"188.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">x2<\/text><rect x=\"248\" y=\"170\" width=\"92\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"294.0\" y=\"188.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">x3<\/text><rect x=\"358\" y=\"170\" width=\"92\" height=\"28\" rx=\"2\" class=\"n b1\"/><text x=\"404.0\" y=\"188.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">x4<\/text><line x1=\"74\" y1=\"168\" x2=\"74.0\" y2=\"148.4\" class=\"e2 b2\"/><polygon points=\"74,142 70.0,150.0 78.0,150.0\" class=\"arrow b2\"/><line x1=\"184\" y1=\"168\" x2=\"184.0\" y2=\"148.4\" class=\"e2 b2\"/><polygon points=\"184,142 180.0,150.0 188.0,150.0\" class=\"arrow b2\"/><line x1=\"294\" y1=\"168\" x2=\"294.0\" y2=\"148.4\" class=\"e2 b2\"/><polygon points=\"294,142 290.0,150.0 298.0,150.0\" class=\"arrow b2\"/><line x1=\"404\" y1=\"168\" x2=\"404.0\" y2=\"148.4\" class=\"e2 b2\"/><polygon points=\"404,142 400.0,150.0 408.0,150.0\" class=\"arrow b2\"/><rect x=\"28\" y=\"112\" width=\"92\" height=\"28\" rx=\"2\" class=\"box2 b2\"/><text x=\"74.0\" y=\"130.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">FFN<\/text><rect x=\"138\" y=\"112\" width=\"92\" height=\"28\" rx=\"2\" class=\"box2 b2\"/><text x=\"184.0\" y=\"130.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">FFN<\/text><rect x=\"248\" y=\"112\" width=\"92\" height=\"28\" rx=\"2\" class=\"box2 b2\"/><text x=\"294.0\" y=\"130.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">FFN<\/text><rect x=\"358\" y=\"112\" width=\"92\" height=\"28\" rx=\"2\" class=\"box2 b2\"/><text x=\"404.0\" y=\"130.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">FFN<\/text><line x1=\"74\" y1=\"110\" x2=\"74.0\" y2=\"90.4\" class=\"e2 b3\"/><polygon points=\"74,84 70.0,92.0 78.0,92.0\" class=\"arrow b3\"/><line x1=\"184\" y1=\"110\" x2=\"184.0\" y2=\"90.4\" class=\"e2 b3\"/><polygon points=\"184,84 180.0,92.0 188.0,92.0\" class=\"arrow b3\"/><line x1=\"294\" y1=\"110\" x2=\"294.0\" y2=\"90.4\" class=\"e2 b3\"/><polygon points=\"294,84 290.0,92.0 298.0,92.0\" class=\"arrow b3\"/><line x1=\"404\" y1=\"110\" x2=\"404.0\" y2=\"90.4\" class=\"e2 b3\"/><polygon points=\"404,84 400.0,92.0 408.0,92.0\" class=\"arrow b3\"/><rect x=\"28\" y=\"54\" width=\"92\" height=\"28\" rx=\"2\" class=\"box b3\"/><text x=\"74.0\" y=\"72.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">h1<\/text><rect x=\"138\" y=\"54\" width=\"92\" height=\"28\" rx=\"2\" class=\"box b3\"/><text x=\"184.0\" y=\"72.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">h2<\/text><rect x=\"248\" y=\"54\" width=\"92\" height=\"28\" rx=\"2\" class=\"box b3\"/><text x=\"294.0\" y=\"72.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">h3<\/text><rect x=\"358\" y=\"54\" width=\"92\" height=\"28\" rx=\"2\" class=\"box b3\"/><text x=\"404.0\" y=\"72.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">h4<\/text><text x=\"240\" y=\"224\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">네 개의 FFN 은 똑같은 가중치를 나눠 써요<\/text><text x=\"240\" y=\"248\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">여기서는 자리끼리 섞이지 않아요<\/text><\/svg>","caption":"네 자리에 똑같은 FFN 을 따로 적용해요.","builds":4},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: 같은 2층 MLP 를 자리마다 독립으로 적용하고, 여기서는 자리끼리 안 섞인다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.07,"say":"둘째 점: 역할 분담과 d_ff 가 보통 4d 라는 사실."},{"x":0.23,"y":0.39,"w":0.53,"h":0.07,"say":"위쪽 파란 상자 h1 ... h4 가 FFN 을 지난 결과예요."},{"x":0.23,"y":0.49,"w":0.53,"h":0.07,"say":"가운데 보라 상자 네 개가 FFN 인데 shared weights 라고 적혀 있어요."},{"x":0.23,"y":0.59,"w":0.53,"h":0.07,"say":"아래 회색 상자 x1 ... x4 가 입력이에요."},{"x":0.14,"y":0.72,"w":0.72,"h":0.09,"say":"아래 큰 식이 FFN(x) = max(0, xW1 + b1)W2 + b2 예요."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 어텐션은 토큰과 토큰 사이에 정보를 주고받는 역할이고, FFN 은 모아 온 정보를 각 토큰에서 더 복잡하게 가공해 주는 역할이에요.","교수님: 논리니어가 없다면 레이어를 깊게 쌓아 봤자 사실 큰 의미가 없는 거죠.","교수님: d_ff 를 보통 4d 정도로 확장했다가 다시 줄이는 사다리꼴 FFN 을 써요.","교수님: 두 행렬 합치면 8d 제곱이고 셀프 어텐션의 프로젝션들이 4d 제곱이니, 트랜스포머에서 FFN 이 차지하는 게 굉장히 커요."]},{"kind":"bg","src":"기초 다지기 9단원","lines":["**렐루(ReLU)** 는 음수를 0 으로 만들고 양수는 그대로 두는 함수예요.","이런 구부러짐이 없으면 층을 몇 개 쌓아도 결국 직선 한 번과 같아요."]}],"pass4":[{"kind":"check","q":"트랜스포머에서 파라미터가 가장 많이 있는 곳은?","choices":["어텐션 투영 행렬","**위치별 피드포워드 신경망(Position-wise Feed-Forward Network (FFN))**","위치 인코딩","층 정규화"],"a":1,"why":"FFN 이 8d 제곱, 어텐션 투영이 4d 제곱이라 FFN 쪽이 두 배예요."},{"kind":"exam","src":"N4 Check Yourself","q":"Q4 (Part 2). Where do most of a Transformer's parameters live, in attention or in the feed-forward layers?","qko":"트랜스포머의 파라미터는 대부분 어디에 있나요, 어텐션인가요 피드포워드인가요?","solve":["어텐션의 W^Q, W^K, W^V, W^O 는 각각 d x d 라서 합이 4d 제곱이에요","FFN 은 d x 4d 와 4d x d 두 개라서 합이 8d 제곱이에요","8d 제곱이 4d 제곱의 두 배예요"],"answer":"피드포워드 쪽이에요. FFN 이 어텐션 투영의 약 두 배를 차지해요."},{"kind":"english","head":"시험 답안 문장","en":"위치별 FFN 은 자리마다 동일한 2층 MLP 를 독립적으로 적용해 비선형 변환을 더하며, 가운데 차원이 4d 라서 트랜스포머 파라미터의 대부분을 차지한다.","ko":"독립 적용, 비선형, 4d, 파라미터 대부분의 네 조각을 넣어요.","tip":"어텐션은 통신, FFN 은 계산. 이 대비로 기억해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["자리마다 따로 적용한다고 해서 가중치가 자리마다 다른 게 아니에요. 가중치는 하나를 함께 써요.","**위치별 피드포워드 신경망(Position-wise Feed-Forward Network (FFN))** 은 자리끼리 정보를 섞지 않아요. 섞는 일은 **어텐션(Attention)** 담당이에요."]}]},{"p":43,"title":"배리어 3: 미래 가리기","terms":["Causal Masking","Autoregressive","Language Model (LM)","Softmax","Attention Score","Attention Weight","Encoder","Decoder","BERT","GPT","Next Token Prediction"],"pass1":[{"kind":"say","lines":["**자기회귀(Autoregressive)** 방식 **언어 모델(Language Model (LM))**은 아직 만들지 않은 토큰을 보면 안 돼요. 보면 너무 쉬워져요.","그래서 미래 자리의 **어텐션 점수(Attention Score)**를 **소프트맥스(Softmax)** 전에 마이너스 무한으로 바꿔요.","exp(마이너스 무한)이 0 이라서 그 칸의 가중치가 정확히 0 이 돼요.","**인코더(Encoder)**는 이 마스크를 쓰지 않고 앞뒤를 다 봐요."]},{"kind":"analogy","head":"시험지 뒷면 가리기","scene":"시험을 보는데 답이 적힌 뒷면이 비쳐 보이면 실력이 늘지 않아요. 검은 종이로 덮어 버리면 앞면만 보고 풀게 돼요.","map":[["비쳐 보이는 답","미래 토큰"],["검은 종이로 덮기","**인과 마스킹(Causal Masking)**"],["앞면만 보고 풀기","**다음 토큰 예측(Next Token Prediction)**"]]}],"pass2":[{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["A language model must not attend to tokens it has not produced yet = 언어 모델은 아직 만들지 않은 토큰에 주목하면 안 된다","otherwise the task is trivial and the model learns nothing = 그러지 않으면 과제가 시시해지고 모델이 아무것도 배우지 못한다","Set the scores for future positions to minus infinity before the softmax = 소프트맥스 전에 미래 자리의 점수를 마이너스 무한으로 둔다","so those weights become exactly zero = 그래서 그 가중치가 정확히 0 이 된다","Encoders skip this and look both ways = 인코더는 이걸 건너뛰고 양쪽을 본다","One triangular mask separates BERT-style from GPT-style models = 삼각형 마스크 하나가 BERT 계열과 GPT 계열을 가른다"]},{"kind":"compare","head":"마스크를 쓰는 쪽과 안 쓰는 쪽","cols":["구분","인코더 방식","디코더 방식"],"rows":[["마스크","안 써요","인과 마스크를 써요"],["보는 범위","앞뒤 전부","자기 자신과 과거만"],["푸는 과제","빈칸 맞히기","**다음 토큰 예측(Next Token Prediction)**"],["대표 모델","**버트(BERT)**","**지피티(GPT)**"]]}],"pass3":[{"kind":"formula","head":"마스크를 식으로","tex":"e_{ij} = \\frac{q_i^{\\top} k_j}{\\sqrt{d_k}}\\ (j \\le i), \\qquad e_{ij} = -\\infty\\ (j > i)","parts":[{"sym":"i","say":"지금 보고 있는 자리(쿼리 쪽)"},{"sym":"j","say":"쳐다보는 대상 자리(키 쪽)"},{"sym":"j \\le i","say":"과거와 자기 자신은 그대로 둬요"},{"sym":"j > i","say":"미래는 마이너스 무한으로 바꿔요"},{"sym":"-\\infty","say":"exp 를 씌우면 0 이 되는 값"}],"whole":"**소프트맥스(Softmax)** 전에 바꿔야 해요. 뒤에 바꾸면 합이 1 이 아니게 돼요."},{"kind":"steps","head":"마스크를 손으로 씌워 봐요","given":"3 x 3 점수 표","steps":["토큰 3개짜리 점수 표를 (2, 1, 0 / 1, 2, 1 / 0, 1, 2) 라고 해요","1번 줄은 자기 자신만 봐요. 2번, 3번 칸을 마이너스 무한으로 바꿔요","1번 줄 소프트맥스는 (1.0, 0, 0) 이에요. 볼 게 하나뿐이니까요","2번 줄은 1번, 2번만 남겨요. 점수 (1, 2) 의 소프트맥스는 (0.2689, 0.7311) 이에요","3번 줄은 다 볼 수 있어요. (0, 1, 2) 의 소프트맥스는 (0.0900, 0.2447, 0.6652) 예요","모든 줄의 합이 정확히 1 이에요"],"answer":"아래 삼각형만 남고 위쪽은 전부 0 이에요. 그래서 삼각 마스크라고 불러요."},{"kind":"figure","head":"인과 마스킹: 오른쪽 위를 지워요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"22\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">인과 마스킹: 오른쪽 위를 지워요<\/text><text x=\"60\" y=\"62\" font-size=\"13\" text-anchor=\"end\" class=\"t b1\">1번<\/text><text x=\"60\" y=\"96\" font-size=\"13\" text-anchor=\"end\" class=\"t b1\">2번<\/text><text x=\"60\" y=\"130\" font-size=\"13\" text-anchor=\"end\" class=\"t b1\">3번<\/text><rect x=\"72\" y=\"46\" width=\"54\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"132\" y=\"46\" width=\"54\" height=\"26\" rx=\"2\" class=\"n4 b1\"/><rect x=\"192\" y=\"46\" width=\"54\" height=\"26\" rx=\"2\" class=\"n4 b1\"/><rect x=\"72\" y=\"80\" width=\"54\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"132\" y=\"80\" width=\"54\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"192\" y=\"80\" width=\"54\" height=\"26\" rx=\"2\" class=\"n4 b1\"/><rect x=\"72\" y=\"114\" width=\"54\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"132\" y=\"114\" width=\"54\" height=\"26\" rx=\"2\" class=\"n b1\"/><rect x=\"192\" y=\"114\" width=\"54\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"99\" y=\"64\" font-size=\"10\" text-anchor=\"middle\" class=\"tl b2\">볼 수 있음<\/text><text x=\"159\" y=\"64\" font-size=\"10\" text-anchor=\"middle\" class=\"tl b2\">차단<\/text><text x=\"219\" y=\"64\" font-size=\"10\" text-anchor=\"middle\" class=\"tl b2\">차단<\/text><text x=\"99\" y=\"98\" font-size=\"10\" text-anchor=\"middle\" class=\"tl b2\">볼 수 있음<\/text><text x=\"159\" y=\"98\" font-size=\"10\" text-anchor=\"middle\" class=\"tl b2\">볼 수 있음<\/text><text x=\"219\" y=\"98\" font-size=\"10\" text-anchor=\"middle\" class=\"tl b2\">차단<\/text><text x=\"99\" y=\"132\" font-size=\"10\" text-anchor=\"middle\" class=\"tl b2\">볼 수 있음<\/text><text x=\"159\" y=\"132\" font-size=\"10\" text-anchor=\"middle\" class=\"tl b2\">볼 수 있음<\/text><text x=\"219\" y=\"132\" font-size=\"10\" text-anchor=\"middle\" class=\"tl b2\">볼 수 있음<\/text><text x=\"240\" y=\"172\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">미래 칸의 점수를 마이너스 무한으로 바꿔요<\/text><text x=\"240\" y=\"196\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">소프트맥스를 지나면 그 칸 가중치가 정확히 0 이에요<\/text><text x=\"240\" y=\"220\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">인코더는 이 마스크를 안 써서 앞뒤를 다 봐요<\/text><\/svg>","caption":"아래 삼각형만 남기고 위는 차단해요.","builds":4},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: 언어 모델은 아직 만들지 않은 토큰을 보면 안 된다."},{"x":0.05,"y":0.25,"w":0.9,"h":0.07,"say":"둘째 점: 소프트맥스 전에 미래 점수를 마이너스 무한으로 둬서 가중치를 0 으로 만든다."},{"x":0.23,"y":0.35,"w":0.19,"h":0.29,"say":"왼쪽 표 Bidirectional (encoder): 칸이 꽉 차 있어요."},{"x":0.5,"y":0.35,"w":0.19,"h":0.29,"say":"오른쪽 표 Causal / masked (decoder): 오른쪽 위가 빗금이에요."},{"x":0.69,"y":0.44,"w":0.12,"h":0.1,"say":"오른쪽 설명: 소프트맥스 전에 점수를 마이너스 무한으로."},{"x":0.18,"y":0.72,"w":0.64,"h":0.09,"say":"아래 식이 j <= i 면 그대로, j > i 면 마이너스 무한이라는 뜻이에요."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 아무 조치도 취하지 않으면 현재 토큰이 자기보다 미래 토큰을 보고 정답 토큰까지 미리 봐 버린다는 거예요.","교수님: 미래 j 가 i 보다 큰 어텐션 스코어는 마이너스 무한으로 바꿔 버립니다.","교수님: 마이너스 무한은 exp 를 치면 거의 0 에 가까운 수이기 때문에 어텐션 웨이트가 0 이 된다.","교수님: 0 이 된다는 건 그쪽 뒤에 있는 밸류를 전혀 보지 않게 된다는 거죠."]}],"pass4":[{"kind":"check","q":"마스크는 언제 씌워야 하나요?","choices":["소프트맥스 전에","소프트맥스 후에","밸류를 곱한 뒤에","순서는 상관없어요"],"a":0,"why":"**소프트맥스(Softmax)** 후에 0 으로 만들면 남은 가중치들의 합이 1 이 아니게 돼요. 반드시 전에 해야 해요."},{"kind":"exam","src":"N4 Check Yourself","q":"Q2 (Part 2). Why must the mask be applied before the softmax and not after?","qko":"왜 마스크를 소프트맥스 전에 씌워야 하고 후에 씌우면 안 되나요?","solve":["소프트맥스는 남은 값들을 나눠서 합이 1 이 되게 만들어요","전에 마이너스 무한을 넣으면 그 칸은 exp 가 0 이라 자연스럽게 빠지고, 나머지 합이 정확히 1 이에요","후에 0 으로 지우면 이미 나눠 준 몫만큼이 사라져서 합이 1 보다 작아져요","그러면 그 뒤의 가중합이 망가져요"],"answer":"소프트맥스 전에 넣어야 남은 가중치의 합이 정확히 1 이 되기 때문이에요."},{"kind":"english","head":"시험 답안 문장","en":"인과 마스킹은 j 가 i 보다 큰 미래 자리의 점수를 소프트맥스 이전에 마이너스 무한으로 바꾸어, 소프트맥스 이후 그 가중치가 정확히 0 이 되게 한다.","ko":"이전이라는 말과 정확히 0 이라는 말을 꼭 넣어요.","tip":"삼각형 마스크, 아래만 남는다. 그림으로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["마스크는 0 을 곱하는 게 아니라 마이너스 무한을 더하는 것이에요.","자기 자신(j = i)은 볼 수 있어요. 가리는 것은 j > i 인 미래뿐이에요.","**자기회귀(Autoregressive)** 생성에서만 필요해요. **다음 토큰 예측(Next Token Prediction)** 과제가 아니면 마스크를 안 써요."]}]},{"p":44,"title":"최소한의 블록","terms":["Transformer","Self-Attention","Positional Encoding","Position-wise Feed-Forward Network (FFN)","Causal Masking","Embedding","Multi-Head Attention (MHA)","Residual Connection","Layer Normalization (LayerNorm)"],"pass1":[{"kind":"say","lines":["배리어 셋을 막았으니 이제 쌓을 수 있는 블록이 됐어요.","**임베딩(Embedding)** 에 **위치 인코딩(Positional Encoding)**을 더하고, 마스크드 어텐션과 FFN 을 지나요.","이 블록을 N 번 쌓으면 거의 트랜스포머예요.","Part 4 에서 더할 셋은 깊게 쌓아도 학습되게 만드는 장치예요."]},{"kind":"analogy","head":"층층이 쌓는 케이크","scene":"같은 모양의 케이크 시트를 몇 겹이든 똑같이 쌓을 수 있어요. 한 겹의 설계가 좋으면 몇 겹을 쌓아도 돼요.","map":[["케이크 시트 한 겹","트랜스포머 블록 하나"],["쌓은 겹 수","N 개의 층"],["시트 사이 크림","잔차 연결과 층 정규화"]]}],"pass2":[{"kind":"points","head":"블록의 순서","items":["1. 입력 **임베딩(Embedding)**: 내용은 있지만 순서가 없어요","2. + **위치 인코딩(Positional Encoding)**: 배리어 1 을 고쳐요","3. 마스크드 **셀프 어텐션(Self-Attention)**: 배리어 3 을 고쳐요","4. 위치별 **위치별 피드포워드 신경망(Position-wise Feed-Forward Network (FFN))**: 배리어 2 를 고쳐요"]},{"kind":"points","head":"슬라이드 영어와 우리말 뜻","items":["Embeddings + positional encoding, masked self-attention, position-wise feed-forward = 임베딩에 위치 인코딩, 마스크드 셀프 어텐션, 위치별 피드포워드","Stack it N times = N 번 쌓아라","This already works = 이것만으로도 이미 동작한다","What Part 4 adds is what makes it trainable at depth = Part 4 가 더하는 것은 깊이 쌓아도 학습되게 만드는 것이다","Three barriers, three components, one stackable block = 배리어 셋, 부품 셋, 쌓을 수 있는 블록 하나"]},{"kind":"points","head":"이 블록이 결국 무엇이 되나요","items":["이 블록을 아주 많이 쌓은 것이 **대규모 언어 모델(Large Language Model (LLM))** 이에요","교수님: 트랜스포머를 좀 크게 쌓으면 그게 **대규모 언어 모델(Large Language Model (LLM))** 이다 이렇게 보셔도 된다","GPT 도 BERT 도 이 블록의 변형이에요"]}],"pass3":[{"kind":"figure","head":"최소 블록 쌓기","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"20\" font-size=\"16\" text-anchor=\"middle\" class=\"tb\">최소 블록 쌓기<\/text><rect x=\"110\" y=\"190\" width=\"260\" height=\"30\" rx=\"2\" class=\"box b1\"/><text x=\"240.0\" y=\"209.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">입력 임베딩<\/text><line x1=\"240\" y1=\"188\" x2=\"240.0\" y2=\"172.4\" class=\"e2 b2\"/><polygon points=\"240,166 236.0,174.0 244.0,174.0\" class=\"arrow b2\"/><rect x=\"110\" y=\"136\" width=\"260\" height=\"30\" rx=\"2\" class=\"box2 b2\"/><text x=\"240.0\" y=\"155.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">+ 위치 인코딩<\/text><text x=\"392\" y=\"156\" font-size=\"11\" text-anchor=\"start\" class=\"tm b2\">배리어 1<\/text><line x1=\"240\" y1=\"134\" x2=\"240.0\" y2=\"118.4\" class=\"e2 b3\"/><polygon points=\"240,112 236.0,120.0 244.0,120.0\" class=\"arrow b3\"/><rect x=\"110\" y=\"82\" width=\"260\" height=\"30\" rx=\"2\" class=\"box2 b3\"/><text x=\"240.0\" y=\"101.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">마스크드 셀프 어텐션<\/text><text x=\"392\" y=\"102\" font-size=\"11\" text-anchor=\"start\" class=\"tm b3\">배리어 3<\/text><line x1=\"240\" y1=\"80\" x2=\"240.0\" y2=\"64.4\" class=\"e2 b4\"/><polygon points=\"240,58 236.0,66.0 244.0,66.0\" class=\"arrow b4\"/><rect x=\"110\" y=\"28\" width=\"260\" height=\"30\" rx=\"2\" class=\"box2 b4\"/><text x=\"240.0\" y=\"47.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">위치별 FFN<\/text><text x=\"392\" y=\"48\" font-size=\"11\" text-anchor=\"start\" class=\"tm b4\">배리어 2<\/text><text x=\"240\" y=\"244\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">이 블록을 N 번 쌓으면 거의 트랜스포머예요<\/text><\/svg>","caption":"아래에서 위로 임베딩, 위치 인코딩, 마스크드 셀프 어텐션, FFN 이에요.","builds":4},{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.05,"y":0.19,"w":0.9,"h":0.05,"say":"첫 점: 임베딩에 위치 인코딩, 마스크드 셀프 어텐션, 위치별 피드포워드를 N 번 쌓아라."},{"x":0.05,"y":0.25,"w":0.9,"h":0.05,"say":"둘째 점: 이것만으로 이미 동작하고, Part 4 는 깊이를 견디게 만든다."},{"x":0.19,"y":0.4,"w":0.36,"h":0.08,"say":"맨 위 보라 상자 Position-wise feed-forward 가 배리어 2 를 고쳐요."},{"x":0.19,"y":0.5,"w":0.36,"h":0.08,"say":"주황 상자 Masked self-attention 이 배리어 3 을 고쳐요."},{"x":0.19,"y":0.6,"w":0.36,"h":0.08,"say":"파란 상자 + Positional encoding 이 배리어 1 을 고쳐요."},{"x":0.19,"y":0.7,"w":0.36,"h":0.08,"say":"맨 아래 회색 상자 Input embeddings 는 내용만 있고 순서가 없어요."}]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 인베딩의 위치를 모르기 때문에 포지셔널 인코딩을 더해 주고, 배리어 1 을 픽스해 줬죠.","교수님: 각 토큰이 자신이 볼 수 있는 다른 토큰들의 정보를 가져와서 문맥이 반영된 새로운 표현으로 바꿔 주죠.","교수님: 중간에 마스크로 미래의 토큰을 보지 않는 배리어 3 을 해결하고요.","교수님: 여기까지가 트랜스포머의 기본 뼈대예요. 이렇게만 해도 트랜스포머라고 할 수 있어요."]},{"kind":"steps","head":"다음 쪽 미리 보기","steps":["Part 4 에서 세 가지를 더해요","**멀티 헤드 어텐션(Multi-Head Attention (MHA))**: 전체 차원 d 를 헤드 h 개로 나눠서 여러 관점으로 봐요. d = 512, h = 8 이면 헤드마다 64 칸이에요","**잔차 연결(Residual Connection)**: 층의 입력을 출력에 그대로 더해서 지름길을 만들어요","**층 정규화(Layer Normalization (LayerNorm))**: 한 토큰의 숫자들을 평균 0, 분산 1 로 맞춰 줘요"],"answer":"이 셋은 성능과 학습 안정성을 위한 장치예요. 기본 뼈대는 이미 완성됐어요."}],"pass4":[{"kind":"check","q":"최소 블록에서 배리어 1(순서 없음)을 고치는 자리는 어디인가요?","choices":["입력 임베딩 바로 다음","셀프 어텐션 다음","FFN 다음","블록 맨 위"],"a":0,"why":"**위치 인코딩(Positional Encoding)**은 첫 층에 들어가기 전, 곧 임베딩 바로 다음에 더해요."},{"kind":"english","head":"시험 답안 문장","en":"최소 트랜스포머 블록은 입력 임베딩에 위치 인코딩을 더하고, 마스크드 셀프 어텐션을 지나, 위치별 피드포워드를 지나는 구조이며, 이를 N 번 쌓는다.","ko":"네 칸을 아래에서 위로 순서대로 쓰면 돼요.","tip":"임베딩 - 위치 - 어텐션 - FFN, 네 칸을 손으로 그려 보며 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**위치 인코딩(Positional Encoding)**은 블록마다 더하는 게 아니라 맨 처음 한 번만 더해요.","**멀티 헤드 어텐션(Multi-Head Attention (MHA))** 가 없어도 동작은 해요. 다만 깊게 쌓으면 학습이 안 돼요."]}]},{"p":45,"title":"Part 4 표지: The Transformer","terms":["Transformer","Multi-Head Attention (MHA)","Residual Connection","Layer Normalization (LayerNorm)"],"pass1":[{"kind":"say","lines":["네 번째 부분 표지예요. 제목은 4 The Transformer 예요.","작은 글씨는 multi-head attention, residuals, LayerNorm, the full stack 이에요.","**멀티 헤드 어텐션(Multi-Head Attention (MHA))**, **잔차 연결(Residual Connection)**, **층 정규화(Layer Normalization (LayerNorm))**, 그리고 전체 구조를 본다는 뜻이에요."]}],"pass2":[{"kind":"points","head":"영어 부제의 뜻","items":["multi-head attention = **멀티 헤드 어텐션(Multi-Head Attention (MHA))**","residuals = **잔차 연결(Residual Connection)**","LayerNorm = **층 정규화(Layer Normalization (LayerNorm))**","the full stack = 전체를 쌓아 올린 모습"]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 여기에 멀티 헤드 어텐션이랑 레지듀얼 커넥션 그리고 레이어 놈, 이렇게 3개의 팬시한 방법을 더 추가해서 배워 보도록 할게요.","교수님: 이건 성능을 높이기 위한 방법이라고 보시면 돼요.","교수님: 트랜스포머를 좀 크게 쌓으면 그게 LLM 이다 이렇게 보셔도 된다."]}],"pass3":[],"pass4":[]},{"p":46,"title":"헤드 하나로는 부족해요","terms":["Multi-Head Attention (MHA)","Head","Self-Attention","Attention Weight","Query","Weighted Sum","Attention","Convolutional Neural Network (CNN)"],"pass1":[{"kind":"say","lines":["4장 **트랜스포머(Transformer)**가 시작됐어요. 여기서 성능을 올리는 장치 세 개를 더해요.","첫 번째가 **멀티 헤드 어텐션(Multi-Head Attention (MHA))**이에요.","**셀프 어텐션(Self-Attention)**을 한 번만 하면 한 가지 방향으로만 평균을 낼 수 있어요."]},{"kind":"figure","head":"한 헤드는 한 곳만 봐요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"20\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">한 번의 가중 평균은 한 가지 질문이에요<\/text><text x=\"60\" y=\"52\" font-size=\"12\" text-anchor=\"middle\" class=\"tm\">질문 자리<\/text><text x=\"150\" y=\"52\" font-size=\"12\" text-anchor=\"middle\" class=\"tm\">chef<\/text><text x=\"240\" y=\"52\" font-size=\"12\" text-anchor=\"middle\" class=\"tm\">store<\/text><text x=\"330\" y=\"52\" font-size=\"12\" text-anchor=\"middle\" class=\"tm\">was<\/text><text x=\"60\" y=\"86\" font-size=\"13\" text-anchor=\"start\" class=\"tb b1\">헤드 1개<\/text><rect x=\"120\" y=\"72\" width=\"60\" height=\"20\" rx=\"2\" class=\"n b1\"/><rect x=\"210\" y=\"72\" width=\"60\" height=\"20\" rx=\"2\" class=\"n b1\"/><rect x=\"300\" y=\"72\" width=\"60\" height=\"20\" rx=\"2\" class=\"n2 b1\"/><text x=\"400\" y=\"86\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">한 줄만 있어요<\/text><line x1=\"20\" y1=\"110\" x2=\"460\" y2=\"110\" class=\"e b2\"/><text x=\"60\" y=\"148\" font-size=\"13\" text-anchor=\"start\" class=\"tb b2\">헤드 A<\/text><rect x=\"120\" y=\"134\" width=\"60\" height=\"20\" rx=\"2\" class=\"n2 b2\"/><rect x=\"210\" y=\"134\" width=\"60\" height=\"20\" rx=\"2\" class=\"n b2\"/><rect x=\"300\" y=\"134\" width=\"60\" height=\"20\" rx=\"2\" class=\"n b2\"/><text x=\"410\" y=\"148\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">문법을 봐요<\/text><text x=\"60\" y=\"184\" font-size=\"13\" text-anchor=\"start\" class=\"tb b3\">헤드 B<\/text><rect x=\"120\" y=\"170\" width=\"60\" height=\"20\" rx=\"2\" class=\"n b3\"/><rect x=\"210\" y=\"170\" width=\"60\" height=\"20\" rx=\"2\" class=\"n3 b3\"/><rect x=\"300\" y=\"170\" width=\"60\" height=\"20\" rx=\"2\" class=\"n3 b3\"/><text x=\"410\" y=\"184\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">가까운 문맥을 봐요<\/text><rect x=\"20\" y=\"212\" width=\"440\" height=\"30\" rx=\"2\" class=\"box2 b4\"/><text x=\"240\" y=\"232\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">한 단어는 동시에 여러 질문을 갖고 있어요<\/text><\/svg>","caption":"빨간 줄은 헤드 하나. 아래 두 줄은 헤드를 나눠서 서로 다른 곳을 본 모습이에요.","builds":4},{"kind":"analogy","head":"사진 한 장에 필터 여러 장","scene":"같은 사진을 볼 때 어떤 필터는 윤곽선을 찾고, 어떤 필터는 색이 바뀌는 곳을 찾아요. 필터마다 역할이 달라요.","map":[["필터 한 장","헤드 한 개"],["윤곽선을 찾는 필터","문법 관계를 보는 헤드"],["색 변화를 찾는 필터","가까운 문맥을 보는 헤드"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["One attention distribution can only average one way","어텐션 분포 하나는 한 가지 방향으로만 평균을 낸다"],["But a word usually needs several different things at once","그런데 한 단어는 보통 여러 가지를 동시에 필요로 한다"],["its syntactic subject, the nearby modifiers","그 단어의 문법상 주어, 가까이 붙은 꾸밈말"],["the coreferent pronoun, the topic of the paragraph","같은 대상을 가리키는 대명사, 문단의 주제"],["One head can only look in one place at a time","헤드 하나는 한 번에 한 곳만 볼 수 있다"]]},{"kind":"points","head":"용어 하나씩","items":["**헤드(Head)**: **어텐션(Attention)**을 한 번 보는 행위 하나예요","**멀티 헤드 어텐션(Multi-Head Attention (MHA))**: 그 행위를 h 개로 나눠서 동시에 하는 것이에요","**어텐션 가중치(Attention Weight)**: 그 자리를 얼마나 볼지 정하는 0 이상의 숫자, 다 더하면 1 이에요"]},{"kind":"check","q":"**헤드(Head)**가 하나뿐이면 무엇이 문제인가요","choices":["한 가지 방향으로만 평균을 낼 수 있어요","계산이 너무 느려요","문장이 짧아져요","소프트맥스를 못 써요"],"a":0,"why":"슬라이드 첫 줄이 바로 그 말이에요. One attention distribution can only average one way."}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.196,"w":0.8,"h":0.04,"say":"첫 점: 어텐션 분포 하나는 한 방향으로만 평균을 낸다."},{"x":0.06,"y":0.244,"w":0.8,"h":0.04,"say":"둘째 점: 주어, 꾸밈말, 대명사, 문단 주제를 한꺼번에 필요로 한다."},{"x":0.23,"y":0.354,"w":0.47,"h":0.038,"say":"그림 제목: 헤드 하나는 한 번에 한 곳만 본다."},{"x":0.09,"y":0.49,"w":0.84,"h":0.056,"say":"single head 줄: 빨간 막대가 was 한 곳에만 서 있어요."},{"x":0.09,"y":0.585,"w":0.84,"h":0.053,"say":"head A: syntax 줄. 문법을 보는 헤드는 chef 에 서 있어요."},{"x":0.09,"y":0.675,"w":0.84,"h":0.053,"say":"head B: local 줄. 가까운 문맥을 보는 헤드는 store 와 was 에 서 있어요."}]},{"kind":"points","head":"예문을 한 번 읽어요","items":["The chef who ran to the store was tired, 토큰이 9개예요","지금 **쿼리(Query)**는 여덟 번째 토큰 was 예요","was 의 주어는 멀리 있는 chef 예요. 이건 문법 관계예요","동시에 바로 앞 store 도 봐야 해요. 이건 가까운 문맥이에요","한 줄짜리 가중치로는 두 가지를 동시에 못 해요"]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 헤드는 그야말로 어텐션을 보는 행위 하나라고 보시면 돼요.","교수님: CNN 에서 컨볼루션 필터 하나하나가 하는 역할이 있잖아요. 헤드도 그런 필터 여러 개처럼 생각하세요.","교수님: 헤드 A 는 문법 관계, 헤드 B 는 가까운 문맥, 헤드 C 는 의미를 보게 나눌 수 있어요."]},{"kind":"bg","src":"기초 다지기 6단원","lines":["**소프트맥스(Softmax)**는 점수를 모두 더해 1 이 되는 확률로 바꿔 줘요.","그래서 **어텐션 가중치(Attention Weight)**는 언제나 한 줄에서 합이 1 이에요.","합이 1 인 줄이 하나뿐이면, 한 곳을 크게 보면 다른 곳은 작아질 수밖에 없어요."]}],"pass4":[{"kind":"check","q":"슬라이드의 예문에서 was 의 문법상 주어는 무엇인가요","choices":["chef","store","who","tired"],"a":0,"why":"The chef ... was tired 이니까 주어는 chef 예요. 그래서 head A: syntax 가 chef 를 봐요."},{"kind":"english","head":"답안 문장","en":"**어텐션(Attention)** 분포 하나는 한 가지 방향으로만 **가중합(Weighted Sum)**을 만들 수 있는데, 한 단어는 문법 관계와 가까운 문맥과 의미를 동시에 필요로 하므로 **헤드(Head)**를 여러 개 둔다.","ko":"한 문장으로 '왜 헤드가 여러 개인가' 를 설명할 수 있어야 해요.","tip":"한 질문에 한 평균, 여러 질문에는 여러 헤드 로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**헤드(Head)**가 여러 개라고 해서 **어텐션(Attention)**을 여러 번 반복하는 게 아니에요. 한 번에 나눠서 같이 해요.","**CNN(합성곱 신경망)**의 필터 비유는 이해를 돕는 비유예요. 계산 방식이 같다는 뜻은 아니에요."]}]},{"p":47,"title":"멀티 헤드 어텐션의 계산","terms":["Multi-Head Attention (MHA)","Head","Query","Key","Value","Self-Attention","Parameter","Transformer","Scaled Dot-Product Attention"],"pass1":[{"kind":"say","lines":["**멀티 헤드 어텐션(Multi-Head Attention (MHA))**이 어떻게 계산되는지 그림으로 봐요.","쪼개고, 각자 어텐션 하고, 옆으로 이어 붙이고, 마지막에 한 번 섞어요.","네 단어로 split, attend, concatenate, project 예요."]},{"kind":"figure","head":"쪼개고 각자 보고 이어 붙여요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"20\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">쪼개고, 각자 보고, 이어 붙이고, 섞어요<\/text><rect x=\"16\" y=\"108\" width=\"56\" height=\"40\" rx=\"2\" class=\"n b1\"/><text x=\"44.0\" y=\"132.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b1\">X<\/text><text x=\"44\" y=\"166\" font-size=\"11\" text-anchor=\"middle\" class=\"tm b1\">n x 512<\/text><rect x=\"100\" y=\"44\" width=\"96\" height=\"34\" rx=\"2\" class=\"n3 b2\"/><text x=\"148\" y=\"66\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">W1 Q K V<\/text><rect x=\"100\" y=\"110\" width=\"96\" height=\"34\" rx=\"2\" class=\"n3 b2\"/><text x=\"148\" y=\"132\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">W2 Q K V<\/text><rect x=\"100\" y=\"176\" width=\"96\" height=\"34\" rx=\"2\" class=\"n3 b2\"/><text x=\"148\" y=\"198\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">W8 Q K V<\/text><line x1=\"74\" y1=\"122\" x2=\"93.8\" y2=\"68.0\" class=\"e b2\"/><polygon points=\"96,62 89.5,68.1 97.0,70.9\" class=\"arrow b2\"/><line x1=\"74\" y1=\"128\" x2=\"89.6\" y2=\"128.0\" class=\"e b2\"/><polygon points=\"96,128 88.0,124.0 88.0,132.0\" class=\"arrow b2\"/><line x1=\"74\" y1=\"134\" x2=\"93.8\" y2=\"188.0\" class=\"e b2\"/><polygon points=\"96,194 97.0,185.1 89.5,187.9\" class=\"arrow b2\"/><rect x=\"214\" y=\"44\" width=\"76\" height=\"34\" rx=\"2\" class=\"n2 b3\"/><text x=\"252.0\" y=\"65.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b3\">헤드 1<\/text><rect x=\"214\" y=\"110\" width=\"76\" height=\"34\" rx=\"2\" class=\"n2 b3\"/><text x=\"252.0\" y=\"131.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b3\">헤드 2<\/text><rect x=\"214\" y=\"176\" width=\"76\" height=\"34\" rx=\"2\" class=\"n2 b3\"/><text x=\"252.0\" y=\"197.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b3\">헤드 8<\/text><text x=\"252\" y=\"100\" font-size=\"11\" text-anchor=\"middle\" class=\"tm b3\">n x 64<\/text><line x1=\"198\" y1=\"61\" x2=\"205.6\" y2=\"61.0\" class=\"e b3\"/><polygon points=\"212,61 204.0,57.0 204.0,65.0\" class=\"arrow b3\"/><line x1=\"198\" y1=\"127\" x2=\"205.6\" y2=\"127.0\" class=\"e b3\"/><polygon points=\"212,127 204.0,123.0 204.0,131.0\" class=\"arrow b3\"/><line x1=\"198\" y1=\"193\" x2=\"205.6\" y2=\"193.0\" class=\"e b3\"/><polygon points=\"212,193 204.0,189.0 204.0,197.0\" class=\"arrow b3\"/><rect x=\"316\" y=\"92\" width=\"60\" height=\"72\" rx=\"2\" class=\"n b4\"/><text x=\"346.0\" y=\"132.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b4\">concat<\/text><line x1=\"292\" y1=\"61\" x2=\"311.4\" y2=\"104.2\" class=\"e2 b4\"/><polygon points=\"314,110 314.4,101.1 307.1,104.3\" class=\"arrow b4\"/><line x1=\"292\" y1=\"127\" x2=\"307.6\" y2=\"127.7\" class=\"e2 b4\"/><polygon points=\"314,128 306.2,123.6 305.8,131.6\" class=\"arrow b4\"/><line x1=\"292\" y1=\"193\" x2=\"311.2\" y2=\"153.7\" class=\"e2 b4\"/><polygon points=\"314,148 306.9,153.4 314.1,156.9\" class=\"arrow b4\"/><rect x=\"396\" y=\"108\" width=\"60\" height=\"40\" rx=\"2\" class=\"n4 b5\"/><text x=\"426.0\" y=\"132.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b5\">W^O<\/text><line x1=\"378\" y1=\"128\" x2=\"387.6\" y2=\"128.0\" class=\"e2 b5\"/><polygon points=\"394,128 386.0,124.0 386.0,132.0\" class=\"arrow b5\"/><text x=\"240\" y=\"246\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b5\">다시 n x 512 로 돌아와요. 계산량은 그대로예요<\/text><\/svg>","caption":"같은 입력 X 를 헤드마다 자기 W^Q, W^K, W^V 로 줄여서 봐요. 결과를 이어 붙이고 W^O 로 섞어요.","builds":5},{"kind":"points","head":"한 줄 요약","items":["**멀티 헤드 어텐션(Multi-Head Attention (MHA))**은 **셀프 어텐션(Self-Attention)** 하나를 h 조각으로 나눈 것이에요","원 논문은 d = 512, h = 8, 그래서 헤드마다 64차원이에요"]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Project Q, K, V into h lower-dimensional subspaces","Q, K, V 를 더 낮은 차원의 공간 h 개로 투영한다"],["run attention in each independently","각 공간에서 어텐션을 따로 돌린다"],["concatenate, and project back","옆으로 이어 붙이고, 다시 원래 차원으로 투영한다"],["Original paper: d = 512, h = 8, so each head works in 64 dimensions","원 논문은 d = 512, h = 8 이라 헤드마다 64차원에서 일한다"],["h heads, each in d/h dimensions, then one shared output projection","헤드 h 개, 각자 d/h 차원, 그다음 공유 출력 투영 하나"]]},{"kind":"points","head":"용어 하나씩","items":["**쿼리(Query)**: 내가 무엇을 찾는지 담은 벡터. X 에 W^Q 를 곱해 만들어요","**키(Key)**: 나는 이런 정보가 있다고 광고하는 이름표. X 에 W^K 를 곱해요","**밸류(Value)**: 뽑히면 실제로 건네줄 내용. X 에 W^V 를 곱해요","**파라미터(Parameter)**: 학습하면서 값이 바뀌는 숫자들. 여기서는 W^Q, W^K, W^V, W^O 예요"]},{"kind":"steps","head":"split, attend, concatenate, project 를 순서대로","given":"d = 512, h = 8","steps":["입력 X 는 토큰 n 개가 각자 512칸을 가진 표예요","헤드 i 는 자기만의 W^Q, W^K, W^V 로 X 를 64칸으로 줄여요","줄어든 64칸에서 **스케일드 닷프로덕트 어텐션(Scaled Dot-Product Attention)**을 그대로 해요","헤드마다 n x 64 짜리 결과가 나와요","8개를 옆으로 이어 붙이면 64 x 8 = 512, 원래 폭으로 돌아와요","마지막에 W^O 를 곱해서 헤드들의 정보를 섞어 줘요"],"answer":"결과는 다시 n x 512. 겉모양은 셀프 어텐션 한 번과 똑같아요."}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.197,"w":0.84,"h":0.036,"say":"첫 점: Q, K, V 를 h 개의 낮은 차원 공간으로 투영해 따로 어텐션."},{"x":0.06,"y":0.247,"w":0.5,"h":0.034,"say":"둘째 점: 원 논문 d = 512, h = 8, 헤드마다 64차원."},{"x":0.13,"y":0.485,"w":0.08,"h":0.078,"say":"왼쪽 회색 상자가 입력 X 예요. n x d 라고 적혀 있어요."},{"x":0.26,"y":0.37,"w":0.24,"h":0.29,"say":"가운데 세 줄이 헤드마다의 W^Q, W^K, W^V 예요. 번호가 1, 2, 3."},{"x":0.51,"y":0.367,"w":0.11,"h":0.297,"say":"head 1, head 2, head 3 상자. 오른쪽 위에 each head: n x d/h."},{"x":0.69,"y":0.449,"w":0.08,"h":0.146,"say":"concat 상자에서 이어 붙이고, 그 오른쪽 진한 상자가 W^O 예요."}]},{"kind":"formula","head":"멀티 헤드 어텐션의 식","tex":"\\mathrm{MultiHead}(X)=\\mathrm{Concat}(\\mathrm{head}_1,\\dots,\\mathrm{head}_h)\\,W^{O}","parts":[{"sym":"X","say":"입력. 토큰 n 개가 각자 d 칸을 가진 표예요"},{"sym":"\\mathrm{head}_i","say":"i 번째 **헤드(Head)**의 결과. n x (d/h) 짜리예요"},{"sym":"\\mathrm{Concat}","say":"결과들을 옆으로 이어 붙이기. 폭이 다시 d 가 돼요"},{"sym":"W^{O}","say":"마지막에 한 번 곱해서 헤드들의 정보를 섞어 주는 표"},{"sym":"h","say":"헤드 개수. 원 논문은 8 이에요"}],"whole":"헤드마다 따로 본 결과를 이어 붙이고 W^O 로 한 번 섞으면 멀티 헤드 어텐션이에요."},{"kind":"formula","head":"헤드 하나의 식","tex":"\\mathrm{head}_i=\\mathrm{Attention}(XW_i^{Q},\\,XW_i^{K},\\,XW_i^{V}),\\quad W_i^{Q}\\in\\mathbb{R}^{d\\times d/h}","parts":[{"sym":"XW_i^{Q}","say":"헤드 i 의 쿼리. X 를 자기 W^Q 로 64칸까지 줄인 것"},{"sym":"XW_i^{K}","say":"헤드 i 의 키. 같은 X 인데 다른 표를 곱해요"},{"sym":"XW_i^{V}","say":"헤드 i 의 밸류"},{"sym":"\\mathbb{R}^{d\\times d/h}","say":"W^Q 의 크기. 512줄 x 64칸 이라는 뜻이에요"},{"sym":"i","say":"헤드 번호. 1부터 h 까지예요"}],"whole":"헤드마다 다른 W 를 써서 같은 문장을 다른 각도로 봐요."},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 각 헤드는 X 를 보긴 보는데, 자기들만의 W^Q, W^K, W^V 로 자기만의 Q, K, V 를 만듭니다.","교수님: 중요한 점은 각각의 헤드가 서로 다른 행렬을 쓴다는 거예요.","교수님: 마지막 W^O 는 헤드들의 정보를 혼합해 주는 믹싱, 블렌딩 역할이라고 생각하세요."]},{"kind":"bg","src":"기초 다지기 3단원","lines":["(n, 512) 짜리 표에 (512, 64) 짜리 표를 곱하면 (n, 64) 가 나와요.","이어 붙이기는 표를 옆으로 붙여 칸 수를 늘리는 것이에요.","64칸짜리 8개를 붙이면 512칸이 돼요. 숫자가 딱 맞아요."]},{"kind":"points","head":"실습과 이어지는 곳","items":["Lab 3 Part 4 에서 트랜스포머 블록을 직접 만들어요","Part 5 에서는 실제 **헤드(Head)**들이 무엇을 보는지 그림으로 확인해요","교수님이 수업에서 건너뛴 부분이라 혼자 복습하라고 했어요"]}],"pass4":[{"kind":"check","q":"d = 512, h = 8 일 때 헤드 하나가 다루는 차원은","choices":["64","512","8","4096"],"a":0,"why":"512 를 8 로 나눈 64 예요. 헤드 수를 늘리면 헤드마다의 차원은 줄어들어요."},{"kind":"check","q":"**멀티 헤드 어텐션(Multi-Head Attention (MHA))**에서 마지막에 W^O 를 곱하는 이유는","choices":["이어 붙인 헤드들의 정보를 섞어 주려고","차원을 8배로 늘리려고","소프트맥스를 한 번 더 씌우려고","마스킹을 하려고"],"a":0,"why":"교수님 말: W^O 는 헤드들의 정보를 혼합해 주는 믹싱, 블렌딩 역할이에요."},{"kind":"english","head":"답안 문장","en":"**멀티 헤드 어텐션(Multi-Head Attention (MHA))**은 Q, K, V 를 h 개의 d/h 차원 공간에서 **어텐션(Attention)**한 뒤, 이어 붙이고 W^O 를 곱한다.","ko":"split, attend, concatenate, project 네 단어를 그대로 문장으로 풀면 돼요.","tip":"쪼개기, 각자 보기, 이어 붙이기, 섞기 로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**헤드(Head)** 개수를 늘려도 전체 차원 d 는 그대로예요. d 를 h 배로 키우는 게 아니에요.","헤드마다 **쿼리(Query)**, **키(Key)**, **밸류(Value)**를 만드는 표가 따로 있어요. 같은 표를 나눠 쓰는 게 아니에요."]}]},{"p":48,"title":"멀티 헤드는 공짜예요","terms":["Multi-Head Attention (MHA)","Head","Parameter","Query","Key","Value","BERT","Self-Attention","Position-wise Feed-Forward Network (FFN)"],"pass1":[{"kind":"say","lines":["**멀티 헤드 어텐션(Multi-Head Attention (MHA))**의 가장 놀라운 점이에요.","헤드를 8개로 늘려도 계산량과 파라미터 수가 전혀 늘지 않아요.","차원을 나눠 쓰기 때문이에요. 서로 다른 관점 8개가 사실상 공짜예요."]},{"kind":"analogy","head":"한 시간을 나눠 쓰기","scene":"공부 한 시간을 한 과목에만 쓸 수도 있고, 8과목에 7분 30초씩 나눠 쓸 수도 있어요. 쓰는 시간 총합은 똑같아요.","map":[["전체 한 시간","전체 차원 d = 512"],["과목 하나","헤드 하나"],["과목마다 7분 30초","헤드마다 64차원"]]},{"kind":"points","head":"한 줄 요약","items":["**헤드(Head)** 수 h 를 늘려도 총 **파라미터(Parameter)** 수는 그대로예요","그래서 h > 1 을 쓸지 말지는 아무도 논쟁하지 않아요"]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Because each head uses d/h dimensions","각 헤드가 d/h 차원만 쓰기 때문에"],["the total compute and the total parameter count are the same","전체 계산량과 전체 파라미터 수가 똑같다"],["as a single head of full width","폭이 전부인 헤드 하나를 쓸 때와"],["So h different views are, in effect, free","그래서 h 개의 다른 관점이 사실상 공짜다"],["Free capacity is rare in deep learning","딥러닝에서 공짜로 얻는 능력은 드물다"]]},{"kind":"points","head":"**헤드(Head)**들이 실제로 배우는 것 (슬라이드, BERT 연구)","items":["어떤 헤드는 바로 앞 토큰이나 바로 뒤 토큰을 따라가요","어떤 헤드는 문법상 걸리는 관계를 따라가요","어떤 헤드는 드물게 나오는 단어를 가리켜요","놀랄 만큼 많은 헤드가 거의 아무것도 안 배워서 잘라내도 돼요"]},{"kind":"check","q":"**멀티 헤드 어텐션(Multi-Head Attention (MHA))**에서 h 를 8로 늘리면 계산량은","choices":["거의 그대로예요","8배가 돼요","64배가 돼요","8분의 1이 돼요"],"a":0,"why":"헤드마다 차원이 d/h 로 줄어들기 때문에 총합이 같아요."}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.197,"w":0.87,"h":0.071,"say":"첫 점: 각 헤드가 d/h 차원을 쓰므로 전체 계산량과 파라미터 수가 같다."},{"x":0.06,"y":0.285,"w":0.3,"h":0.032,"say":"둘째 점: 그래서 h 개의 다른 관점은 사실상 공짜다."},{"x":0.06,"y":0.332,"w":0.87,"h":0.067,"say":"셋째 점: BERT 로 연구한 헤드들의 역할. 마지막은 잘라내도 되는 헤드."},{"x":0.12,"y":0.607,"w":0.76,"h":0.07,"say":"가운데 식: head_i = Attention(XW^Q, XW^K, XW^V), W^Q 는 d x d/h."},{"x":0.26,"y":0.863,"w":0.48,"h":0.03,"say":"맨 아래: 공짜로 얻는 능력은 드물다, 그래서 h > 1 은 논쟁거리가 아니다."}]},{"kind":"steps","head":"파라미터 수를 직접 세어 봐요 (싱글 헤드)","given":"d = 512","steps":["d = 512 인 헤드 하나를 쓴다고 해요","W^Q 는 512줄 x 512칸이라 512 x 512 = 262144 개","W^K, W^V 도 똑같이 262144 개씩","셋을 더하면 3 x 262144 = 786432 개","출력 표 W^O 도 512 x 512 = 262144 개","전부 더하면 786432 + 262144 = 1048576 개"],"answer":"싱글 헤드 어텐션의 파라미터는 약 105만 개예요."},{"kind":"steps","head":"파라미터 수를 직접 세어 봐요 (헤드 8개)","given":"d = 512, h = 8, d/h = 64","steps":["헤드 하나의 W^Q 는 512줄 x 64칸이라 512 x 64 = 32768 개","헤드 하나에 W^Q, W^K, W^V 가 있으니 3 x 32768 = 98304 개","헤드가 8개니까 8 x 98304 = 786432 개","싱글 헤드의 786432 와 정확히 같아요","W^O 도 똑같이 512 x 512 = 262144 개","합치면 786432 + 262144 = 1048576 개"],"answer":"헤드 8개도 약 105만 개. 싱글 헤드와 한 개도 다르지 않아요."},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 512를 다 처리하는 게 아니라 8개 헤드가 각각 512 나누기 8 로 차원을 확 줄여서 계산합니다.","교수님: 헤드를 여러 번 했다고 계산량이 더 많아지는 건 아니에요. 계산 수는 똑같다.","교수님: 다만 헤드가 너무 많아지면 차원이 너무 줄어서 표현력이 약해져요. 4나 8 정도가 적당합니다."]},{"kind":"bg","src":"기초 다지기 3단원","lines":["행렬의 파라미터 수는 줄 수 x 칸 수예요.","512 x 64 = 32768 이고, 이것을 8번 더하면 512 x 512 = 262144 와 같아요.","나눠서 여러 번 하나, 한 번에 크게 하나 숫자의 총합은 같아요."]}],"pass4":[{"kind":"check","q":"헤드 8개짜리와 싱글 헤드의 파라미터 수를 비교하면","choices":["똑같아요","헤드 8개가 8배 많아요","헤드 8개가 8분의 1이에요","헤드 8개가 2배 많아요"],"a":0,"why":"둘 다 약 105만 개예요. 512 x 64 x 8 = 512 x 512 이기 때문이에요."},{"kind":"check","q":"**BERT(버트)** 연구가 밝힌 **헤드(Head)**들의 모습이 아닌 것은","choices":["모든 헤드가 똑같이 중요해요","앞뒤 토큰을 따라가는 헤드가 있어요","문법 관계를 따라가는 헤드가 있어요","거의 안 배워서 잘라내도 되는 헤드가 많아요"],"a":0,"why":"슬라이드는 반대로 말해요. 놀랄 만큼 많은 헤드가 거의 아무것도 안 배워요."},{"kind":"english","head":"답안 문장","en":"각 **헤드(Head)**가 d/h 차원만 쓰기 때문에 h 개의 헤드를 써도 총 계산량과 총 **파라미터(Parameter)** 수가 폭 d 짜리 헤드 하나와 같아서, 서로 다른 관점을 사실상 공짜로 얻는다.","ko":"d/h 로 나눠 쓴다는 점이 핵심이에요.","tip":"나눠서 쓰니까 총합은 그대로 로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["공짜인 것은 **파라미터(Parameter)** 수와 계산량이에요. **헤드(Head)**를 늘리면 헤드 하나의 표현력은 줄어들어요.","이 쪽 파라미터 수는 **어텐션(Attention)** 부분만 센 거예요. **FFN(위치별 피드포워드 신경망)**은 이보다 두 배 많아요."]}]},{"p":49,"title":"잔차 연결","terms":["Residual Connection","Identity Path","Gradient","Vanishing Gradient","Exploding Gradient","Jacobian","Transformer","BERT","Parameter"],"pass1":[{"kind":"say","lines":["두 번째 장치는 **잔차 연결(Residual Connection)**이에요.","서브층의 입력을 그 출력에 그냥 더해 줘요. 한 줄이면 끝나는 장치예요.","그러면 층은 전체를 배울 필요가 없고 '얼마나 바꿀지' 만 배우면 돼요."]},{"kind":"figure","head":"기울기에게 고속도로를 깔아 줘요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"20\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">기울기에게 고속도로를 깔아 줘요<\/text><text x=\"56\" y=\"66\" font-size=\"13\" text-anchor=\"start\" class=\"tb b1\">잔차 없음<\/text><rect x=\"140\" y=\"48\" width=\"52\" height=\"30\" rx=\"2\" class=\"n b1\"/><text x=\"166.0\" y=\"67.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">f1<\/text><rect x=\"212\" y=\"48\" width=\"52\" height=\"30\" rx=\"2\" class=\"n b1\"/><text x=\"238.0\" y=\"67.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">f2<\/text><rect x=\"284\" y=\"48\" width=\"52\" height=\"30\" rx=\"2\" class=\"n b1\"/><text x=\"310.0\" y=\"67.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">f3<\/text><rect x=\"356\" y=\"48\" width=\"52\" height=\"30\" rx=\"2\" class=\"n b1\"/><text x=\"382.0\" y=\"67.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">f4<\/text><line x1=\"192\" y1=\"63\" x2=\"203.6\" y2=\"63.0\" class=\"e b1\"/><polygon points=\"210,63 202.0,59.0 202.0,67.0\" class=\"arrow b1\"/><line x1=\"264\" y1=\"63\" x2=\"275.6\" y2=\"63.0\" class=\"e b1\"/><polygon points=\"282,63 274.0,59.0 274.0,67.0\" class=\"arrow b1\"/><line x1=\"336\" y1=\"63\" x2=\"347.6\" y2=\"63.0\" class=\"e b1\"/><polygon points=\"354,63 346.0,59.0 346.0,67.0\" class=\"arrow b1\"/><text x=\"240\" y=\"96\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">기울기가 네 상자를 모두 통과해야 해요<\/text><line x1=\"20\" y1=\"112\" x2=\"460\" y2=\"112\" class=\"e b2\"/><text x=\"56\" y=\"162\" font-size=\"13\" text-anchor=\"start\" class=\"tb b2\">잔차 있음<\/text><rect x=\"140\" y=\"144\" width=\"52\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><text x=\"166.0\" y=\"163.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b2\">f1<\/text><rect x=\"212\" y=\"144\" width=\"52\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><text x=\"238.0\" y=\"163.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b2\">f2<\/text><rect x=\"284\" y=\"144\" width=\"52\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><text x=\"310.0\" y=\"163.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b2\">f3<\/text><rect x=\"356\" y=\"144\" width=\"52\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><text x=\"382.0\" y=\"163.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b2\">f4<\/text><line x1=\"192\" y1=\"159\" x2=\"203.6\" y2=\"159.0\" class=\"e b2\"/><polygon points=\"210,159 202.0,155.0 202.0,163.0\" class=\"arrow b2\"/><line x1=\"264\" y1=\"159\" x2=\"275.6\" y2=\"159.0\" class=\"e b2\"/><polygon points=\"282,159 274.0,155.0 274.0,163.0\" class=\"arrow b2\"/><line x1=\"336\" y1=\"159\" x2=\"347.6\" y2=\"159.0\" class=\"e b2\"/><polygon points=\"354,159 346.0,155.0 346.0,163.0\" class=\"arrow b2\"/><line x1=\"140\" y1=\"132\" x2=\"257.6\" y2=\"132.0\" class=\"e2 b3\"/><polygon points=\"264,132 256.0,128.0 256.0,136.0\" class=\"arrow b3\"/><line x1=\"284\" y1=\"132\" x2=\"401.6\" y2=\"132.0\" class=\"e2 b3\"/><polygon points=\"408,132 400.0,128.0 400.0,136.0\" class=\"arrow b3\"/><text x=\"240\" y=\"196\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">위로 건너뛰는 길이 따로 있어요<\/text><rect x=\"20\" y=\"212\" width=\"440\" height=\"32\" rx=\"2\" class=\"box2 b4\"/><text x=\"240\" y=\"233\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b4\">x(l) = x(l-1) + Sublayer(x(l-1))<\/text><\/svg>","caption":"위는 잔차가 없어서 기울기가 상자를 다 통과해야 해요. 아래는 건너뛰는 길이 따로 있어요.","builds":4},{"kind":"analogy","head":"지도 위의 고속도로","scene":"시내 길로만 가면 신호등마다 서느라 힘이 빠져요. 옆에 고속도로가 하나 있으면 멀리까지 그대로 갈 수 있어요.","map":[["신호등이 많은 시내 길","서브층을 하나하나 지나가는 길"],["옆에 난 고속도로","항등 경로"],["멀리까지 힘이 남아 있음","1층까지 기울기가 살아서 도착함"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Add the input of a sublayer to its output","서브층의 입력을 그 출력에 더한다"],["The layer then only has to learn the change","그러면 층은 바뀌는 만큼만 배우면 된다"],["not the whole mapping","전체 대응 관계를 배우는 게 아니라"],["The identity path makes the Jacobian I + df/dx","항등 경로가 야코비안을 I + 함수의 미분으로 만든다"],["the gradient reaches layer 1 even in a 96-layer stack","96층을 쌓아도 기울기가 1층까지 닿는다"],["Without this, deep Transformers simply do not train","이것이 없으면 깊은 트랜스포머는 아예 학습되지 않는다"]]},{"kind":"points","head":"용어 하나씩","items":["**잔차 연결(Residual Connection)**: 서브층의 입력을 출력에 그대로 더해 주는 지름길이에요","**항등 경로(Identity Path)**: 아무 계산도 안 하고 그냥 지나가는 길이에요","**야코비안(Jacobian)**: 벡터를 벡터로 보내는 함수의 미분을 표로 적은 것이에요","**기울기 소실(Vanishing Gradient)**: 기울기가 곱해지다 0 에 가까워지는 문제예요"]},{"kind":"steps","head":"무엇이 달라지는지 한 줄씩","steps":["원래는 서브층 하나를 지나면 x(l) = f(x(l-1)) 이에요","잔차를 붙이면 x(l) = x(l-1) + f(x(l-1)) 이 돼요","f 는 이제 '완성된 값' 이 아니라 '고칠 양' 만 만들면 돼요","f 가 아무것도 안 해도 입력이 그대로 위로 올라가요","그래서 층을 많이 쌓아도 최소한 망가지지는 않아요"],"answer":"잔차 연결은 x + f(x). 더하기 하나가 전부예요."}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.197,"w":0.8,"h":0.036,"say":"첫 점: 서브층 입력을 출력에 더하면 층은 바뀌는 양만 배우면 된다."},{"x":0.06,"y":0.243,"w":0.8,"h":0.07,"say":"둘째 점: 항등 경로가 야코비안을 I + df/dx 로 만들어 96층에서도 학습된다."},{"x":0.12,"y":0.44,"w":0.73,"h":0.053,"say":"without residual 줄: f1 에서 f4 까지 한 줄로만 이어져 있어요."},{"x":0.12,"y":0.513,"w":0.73,"h":0.044,"say":"가운데 초록 곡선이 건너뛰는 잔차 경로예요."},{"x":0.12,"y":0.561,"w":0.73,"h":0.056,"say":"with residual 줄: 오른쪽 식이 x(l) = x(l-1) + f(x(l-1)) 이에요."},{"x":0.14,"y":0.721,"w":0.72,"h":0.076,"say":"큰 식: x(l) = x(l-1) + Sublayer(x(l-1))."}]},{"kind":"formula","head":"잔차 연결의 식","tex":"x_{\\ell}=x_{\\ell-1}+\\mathrm{Sublayer}(x_{\\ell-1})","parts":[{"sym":"x_{\\ell-1}","say":"이 서브층에 들어온 값"},{"sym":"\\mathrm{Sublayer}","say":"셀프 어텐션이나 피드포워드 같은 서브층"},{"sym":"+","say":"여기 이 더하기 하나가 잔차 연결의 전부예요"},{"sym":"x_{\\ell}","say":"서브층을 지난 뒤의 값"}],"whole":"들어온 값을 그대로 더해 주니, 서브층은 고칠 양만 만들면 돼요."},{"kind":"steps","head":"기울기가 얼마나 남는지 손으로 세어 봐요","given":"층마다 미분 0.5, 층 수 10과 96","steps":["층마다 미분이 0.5 라고 해 봐요. 곱해지면서 내려가요","잔차가 없으면 10층을 지나면 0.5 를 열 번 곱해요","0.5 의 10제곱 = 0.0009766, 1024분의 1 이에요","96층이면 0.5 를 96번 곱해서 거의 0 이 돼요","잔차가 있으면 층마다 1 + 0.5 = 1.5 가 돼요","항등 경로만 따라가는 길은 1 을 96번 곱해도 그대로 1 이에요"],"answer":"잔차가 없으면 1024분의 1, 있으면 최소한 1 이 남아요. 기울기가 죽지 않아요."},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 그레이디언트가 쭉 흐를 때 계속 쌓으면 베니싱하거나 익스플로딩 하는 경우가 있죠.","교수님: 그래서 하이웨이 패스를 하나 그냥 해서 더해주는 거예요.","교수님: 아이덴티티 경로를 통해 기울기가 직접 전달되는 통로가 있어서 훨씬 안정적입니다.","교수님: BERT 는 12개의 레이어를 쌓는단 말이죠. 깊은 트랜스포머 학습이 편해진 게 잔차 연결이에요."]},{"kind":"bg","src":"기초 다지기 7단원","lines":["연쇄 법칙은 맞물린 톱니바퀴예요. 층을 지날 때마다 미분이 곱해져요.","1보다 작은 수를 계속 곱하면 0 으로 가고, 1보다 큰 수를 계속 곱하면 폭발해요.","더하기가 하나 있으면 미분에 1 이 남아서 **기울기 소실(Vanishing Gradient)**과 **기울기 폭발(Exploding Gradient)**을 둘 다 눌러 줘요."]}],"pass4":[{"kind":"check","q":"**잔차 연결(Residual Connection)**이 없으면 깊은 **트랜스포머(Transformer)**는","choices":["아예 학습이 안 돼요","조금 느려질 뿐이에요","파라미터가 늘어나요","문장이 짧아져요"],"a":0,"why":"슬라이드: Without this, deep Transformers simply do not train."},{"kind":"check","q":"**잔차 연결(Residual Connection)**이 있을 때 **야코비안(Jacobian)**의 모양은","choices":["I + 함수의 미분","함수의 미분만","0","함수의 미분의 제곱"],"a":0,"why":"항등 경로 때문에 단위 행렬 I 가 더해져요. 그래서 기울기가 살아남아요."},{"kind":"exam","src":"예상 문제","q":"잔차 연결이 깊은 신경망 학습에 도움이 되는 이유를 야코비안으로 설명하시오.","qko":"왜 더하기 하나가 그렇게 중요한지 수식으로 설명해 보세요.","solve":["잔차가 없으면 x(l) = f(x(l-1)) 이라 야코비안은 함수의 미분 하나뿐이에요","층을 지날 때마다 이 미분이 곱해져서 1보다 작으면 0 으로 사라져요","잔차를 붙이면 x(l) = x(l-1) + f(x(l-1)) 이 돼요","야코비안이 I + 함수의 미분이 되어서 항상 1 이 섞여 있어요","그래서 96층을 쌓아도 기울기가 1층까지 닿아요"],"answer":"항등 경로가 야코비안에 I 를 더해 주어서 기울기 소실을 막아요."},{"kind":"english","head":"답안 문장","en":"**잔차 연결(Residual Connection)** 덕분에 **야코비안(Jacobian)**이 I + 함수의 미분이 되어, 96층에서도 **기울기(Gradient)**가 1층까지 닿는다.","ko":"입력을 더한다, 변화량만 배운다, 야코비안에 I 가 생긴다 세 가지를 쓰면 돼요.","tip":"더하기 하나 = 고속도로 하나 로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**잔차 연결(Residual Connection)**은 새로 배우는 **파라미터(Parameter)**가 없어요. 더하기일 뿐이라 공짜예요.","더하려면 입력과 출력의 칸 수가 같아야 해요. 그래서 트랜스포머는 층마다 폭을 d 로 유지해요."]}]},{"p":50,"title":"층 정규화 LayerNorm","terms":["Layer Normalization (LayerNorm)","Parameter","Token","Gradient","Residual Connection","Transformer","Exploding Gradient"],"pass1":[{"kind":"say","lines":["세 번째 장치는 **LayerNorm(층 정규화)**이에요.","**토큰(Token)** 하나가 가진 숫자들을 평균 0, 분산 1 로 맞춰 줘요.","그러면 값이 너무 커지거나 작아지지 않아서 학습이 안정돼요."]},{"kind":"figure","head":"들쭉날쭉한 숫자를 가지런히","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"120\" y=\"20\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">정규화 전<\/text><text x=\"360\" y=\"20\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">정규화 후<\/text><line x1=\"40\" y1=\"140\" x2=\"220\" y2=\"140\" class=\"e b1\"/><rect x=\"50\" y=\"84\" width=\"22\" height=\"56\" rx=\"2\" class=\"n b1\"/><rect x=\"80\" y=\"56\" width=\"22\" height=\"84\" rx=\"2\" class=\"n b1\"/><rect x=\"110\" y=\"100\" width=\"22\" height=\"40\" rx=\"2\" class=\"n b1\"/><rect x=\"140\" y=\"68\" width=\"22\" height=\"72\" rx=\"2\" class=\"n b1\"/><rect x=\"170\" y=\"112\" width=\"22\" height=\"28\" rx=\"2\" class=\"n b1\"/><rect x=\"200\" y=\"44\" width=\"22\" height=\"96\" rx=\"2\" class=\"n b1\"/><text x=\"130\" y=\"160\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">평균이 한쪽으로 치우쳤어요<\/text><line x1=\"232\" y1=\"96\" x2=\"251.6\" y2=\"96.0\" class=\"e2 b2\"/><polygon points=\"258,96 250.0,92.0 250.0,100.0\" class=\"arrow b2\"/><line x1=\"280\" y1=\"96\" x2=\"460\" y2=\"96\" class=\"e b2\"/><rect x=\"290\" y=\"70\" width=\"22\" height=\"26\" rx=\"2\" class=\"n2 b2\"/><rect x=\"320\" y=\"56\" width=\"22\" height=\"40\" rx=\"2\" class=\"n2 b2\"/><rect x=\"350\" y=\"96\" width=\"22\" height=\"22\" rx=\"2\" class=\"n2 b2\"/><rect x=\"380\" y=\"66\" width=\"22\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"410\" y=\"96\" width=\"22\" height=\"34\" rx=\"2\" class=\"n2 b2\"/><rect x=\"440\" y=\"50\" width=\"22\" height=\"46\" rx=\"2\" class=\"n2 b2\"/><text x=\"370\" y=\"152\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">평균 0, 분산 1 이 됐어요<\/text><rect x=\"20\" y=\"184\" width=\"440\" height=\"28\" rx=\"2\" class=\"box2 b3\"/><text x=\"240\" y=\"203\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">토큰 하나의 숫자들만 가지고 계산해요<\/text><text x=\"240\" y=\"236\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">다른 토큰과도, 배치와도 섞지 않아요<\/text><text x=\"240\" y=\"258\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">그래서 학습 때와 추론 때가 똑같아요<\/text><\/svg>","caption":"왼쪽은 크기가 제각각이고 평균이 치우쳐 있어요. 오른쪽은 평균 0, 분산 1 로 맞춘 모습이에요.","builds":4},{"kind":"analogy","head":"반마다 다른 시험을 같은 자로 재기","scene":"A반 시험은 평균 80점, B반 시험은 평균 40점이면 점수를 그대로 비교할 수 없어요. 반 평균과 퍼진 정도로 나눠서 같은 자로 만들어요.","map":[["한 반의 점수들","토큰 하나의 숫자들"],["반 평균으로 빼기","평균 0 으로 옮기기"],["퍼진 정도로 나누기","분산 1 로 맞추기"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Normalise each token's feature vector to mean 0 and variance 1","각 토큰의 특징 벡터를 평균 0, 분산 1 로 정규화한다"],["then rescale with learned gamma and beta","그다음 학습한 감마와 베타로 다시 크기를 조절한다"],["Note what it does not do","무엇을 하지 않는지도 보라"],["it never mixes across tokens or across the batch","토큰끼리도, 배치끼리도 절대 섞지 않는다"],["so it behaves identically at training and inference","그래서 학습 때와 추론 때가 똑같이 동작한다"],["Keeps activations in a sane range so the residual stream does not explode","값을 제정신인 범위로 유지해서 잔차 흐름이 터지지 않게 한다"]]},{"kind":"points","head":"용어 하나씩","items":["**LayerNorm(층 정규화)**: 토큰 하나의 숫자들만 가지고 평균 0, 분산 1 로 맞추는 것이에요","평균: 다 더해서 개수로 나눈 값이에요. 기호는 뮤예요","분산: 평균에서 얼마나 떨어져 있는지의 제곱 평균이에요. 기호는 시그마 제곱이에요","감마와 베타: 다시 늘리고 옮기는 **파라미터(Parameter)**예요. 모델이 학습으로 정해요"]},{"kind":"check","q":"**LayerNorm(층 정규화)**은 무엇을 섞지 않나요","choices":["다른 토큰이나 다른 문장과 섞지 않아요","자기 숫자끼리 섞지 않아요","감마와 베타를 섞지 않아요","층끼리 섞지 않아요"],"a":0,"why":"토큰 하나 안에서만 계산해요. 그래서 문장 길이가 달라져도 똑같이 동작해요."}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.199,"w":0.85,"h":0.032,"say":"첫 점: 토큰의 특징 벡터를 평균 0, 분산 1 로. 감마와 베타로 다시 조절."},{"x":0.06,"y":0.244,"w":0.85,"h":0.068,"say":"둘째 점: 토큰끼리도 배치끼리도 섞지 않아서 학습과 추론이 같다."},{"x":0.19,"y":0.348,"w":0.27,"h":0.285,"say":"왼쪽 그래프 before: 평균 3.7, 표준편차 1.9. 빨간 점선이 평균이에요."},{"x":0.56,"y":0.348,"w":0.28,"h":0.285,"say":"오른쪽 after: 평균 0, 표준편차 1. 0 을 중심으로 위아래로 갈려요."},{"x":0.27,"y":0.664,"w":0.5,"h":0.026,"say":"작은 글씨: 두 그래프의 눈금이 다르다는 점에 주의하라고 적혀 있어요."},{"x":0.14,"y":0.721,"w":0.72,"h":0.082,"say":"아래 식: LN(x) = 감마 곱하기 (x - 뮤) 나누기 루트(시그마제곱 + 입실론) + 베타."}]},{"kind":"formula","head":"LayerNorm 의 식","tex":"\\mathrm{LN}(x)=\\gamma\\odot\\frac{x-\\mu}{\\sqrt{\\sigma^{2}+\\varepsilon}}+\\beta,\\qquad \\mu=\\frac{1}{d}\\sum_{m}x_{m}","parts":[{"sym":"x","say":"토큰 하나의 숫자 d 개"},{"sym":"\\mu","say":"그 d 개의 평균. 다 더해서 d 로 나눈 값"},{"sym":"\\sigma^{2}","say":"그 d 개의 분산. 평균에서 떨어진 거리의 제곱 평균"},{"sym":"\\varepsilon","say":"0 으로 나누는 것을 막는 아주 작은 수"},{"sym":"\\gamma","say":"칸마다 다시 늘려 주는 학습 파라미터"},{"sym":"\\beta","say":"칸마다 다시 옮겨 주는 학습 파라미터"},{"sym":"\\odot","say":"같은 자리끼리 곱하기"}],"whole":"평균을 빼고 퍼진 정도로 나눈 뒤, 감마로 늘리고 베타로 옮겨요."},{"kind":"steps","head":"숫자 네 개로 직접 해 봐요","given":"x = (2, 4, 4, 10)","steps":["토큰 하나의 숫자가 2, 4, 4, 10 이라고 해요","평균은 (2 + 4 + 4 + 10) 나누기 4 = 5 예요","평균에서 뺀 값은 -3, -1, -1, 5 예요","제곱해서 평균: (9 + 1 + 1 + 25) 나누기 4 = 9, 이게 분산이에요","분산 9 의 제곱근은 3 이에요. 이것으로 나눠요","결과는 -1, -0.333, -0.333, 1.667 이에요"],"answer":"평균은 0, 분산은 1 이 됐어요. 감마 2, 베타 1 이면 -1, 0.333, 0.333, 4.333 이 돼요."},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 배치 놈과 다르게 레이어 놈은 각 d 차원만 정규화해 주는 거예요.","교수님: 평균 뮤와 분산을 구한 다음 평균 0, 분산 1 로 맞춰 주고 감마와 베타를 곱해 줍니다.","교수님: 학습할 때랑 추론할 때 들어오는 토큰 정보가 많이 다르잖아요. 그걸 정규화해 주는 거예요.","교수님: 정규화를 깊게 다루지는 않을게요. 이해가 어려우면 이런 게 있다고 보셔도 됩니다."]},{"kind":"bg","src":"기초 다지기 1단원","lines":["벡터는 숫자를 한 줄로 늘어놓은 것이에요. 여기서는 토큰 하나가 가진 512개 숫자예요.","평균을 빼면 중심이 0 으로 옮겨지고, 표준편차로 나누면 퍼진 폭이 1 이 돼요.","512개를 모두 이렇게 바꿔도 서로의 순위는 그대로예요."]}],"pass4":[{"kind":"check","q":"다음 중 LayerNorm 의 설명으로 틀린 것은","choices":["배치 안의 여러 문장 통계를 함께 써요","토큰 하나의 숫자들만 써요","감마와 베타는 학습으로 정해져요","문장 길이가 달라져도 똑같이 동작해요"],"a":0,"why":"배치와 섞지 않는다는 것이 LayerNorm 의 핵심이에요."},{"kind":"check","q":"x = (2, 4, 4, 10) 을 정규화하면 첫 값은","choices":["-1","0","1","-3"],"a":0,"why":"평균 5, 표준편차 3 이니까 (2 - 5) 나누기 3 = -1 이에요."},{"kind":"english","head":"답안 문장","en":"**LayerNorm(층 정규화)**은 각 **토큰(Token)**의 특징 벡터를 평균 0, 분산 1 로 정규화한 뒤 학습된 감마와 베타로 다시 조절하며, 다른 토큰이나 배치와 섞지 않아 학습과 추론에서 동일하게 동작한다.","ko":"무엇을 하는지와 무엇을 하지 않는지를 같이 써야 만점이에요.","tip":"토큰 하나 안에서만 = 길이가 달라도 안전 으로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**LayerNorm(층 정규화)**은 **잔차 연결(Residual Connection)**을 대신하는 게 아니에요. 둘은 함께 쓰여요.","정규화한 뒤 감마와 베타로 다시 늘리는 단계를 빼먹으면 안 돼요. 표현력이 사라져요.","슬라이드의 왼쪽과 오른쪽 그래프는 눈금이 달라요. 막대 높이를 직접 비교하면 안 돼요."]}]},{"p":51,"title":"Pre-LN 과 Post-LN","terms":["Layer Normalization (LayerNorm)","Residual Connection","Transformer","Large Language Model (LLM)","Learning Rate","Gradient"],"pass1":[{"kind":"say","lines":["**LayerNorm(층 정규화)**을 어디에 두느냐로 두 가지 방식이 나뉘어요.","더한 다음에 두면 Post-LN, 서브층에 넣기 전에 두면 Pre-LN 이에요.","2017년 원 논문은 Post-LN 이고, 요즘 모델은 대부분 Pre-LN 이에요."]},{"kind":"figure","head":"더하기 전인가, 더한 다음인가","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"120\" y=\"22\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">Post-LN (2017 원 논문)<\/text><text x=\"360\" y=\"22\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">Pre-LN (요즘 방식)<\/text><rect x=\"76\" y=\"180\" width=\"100\" height=\"28\" rx=\"2\" class=\"n3 b1\"/><text x=\"126.0\" y=\"198.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">서브층<\/text><text x=\"126\" y=\"232\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b1\">x<\/text><line x1=\"126\" y1=\"226\" x2=\"126.0\" y2=\"216.4\" class=\"e b1\"/><polygon points=\"126,210 122.0,218.0 130.0,218.0\" class=\"arrow b1\"/><rect x=\"76\" y=\"136\" width=\"100\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"126.0\" y=\"153.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b1\">더하기<\/text><line x1=\"126\" y1=\"178\" x2=\"126.0\" y2=\"170.4\" class=\"e b1\"/><polygon points=\"126,164 122.0,172.0 130.0,172.0\" class=\"arrow b1\"/><line x1=\"40\" y1=\"222\" x2=\"40\" y2=\"149\" class=\"e2 b2\"/><line x1=\"40\" y1=\"149\" x2=\"67.6\" y2=\"149.0\" class=\"e2 b2\"/><polygon points=\"74,149 66.0,145.0 66.0,153.0\" class=\"arrow b2\"/><rect x=\"76\" y=\"92\" width=\"100\" height=\"28\" rx=\"2\" class=\"n2 b2\"/><text x=\"126.0\" y=\"110.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">LayerNorm<\/text><line x1=\"126\" y1=\"134\" x2=\"126.0\" y2=\"128.4\" class=\"e b2\"/><polygon points=\"126,122 122.0,130.0 130.0,130.0\" class=\"arrow b2\"/><text x=\"126\" y=\"74\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">LN(x + f(x))<\/text><line x1=\"240\" y1=\"40\" x2=\"240\" y2=\"250\" class=\"e b3\"/><rect x=\"316\" y=\"180\" width=\"100\" height=\"28\" rx=\"2\" class=\"n2 b3\"/><text x=\"366.0\" y=\"198.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b3\">LayerNorm<\/text><text x=\"366\" y=\"232\" font-size=\"13\" text-anchor=\"middle\" class=\"tm b3\">x<\/text><line x1=\"366\" y1=\"226\" x2=\"366.0\" y2=\"216.4\" class=\"e b3\"/><polygon points=\"366,210 362.0,218.0 370.0,218.0\" class=\"arrow b3\"/><rect x=\"316\" y=\"136\" width=\"100\" height=\"28\" rx=\"2\" class=\"n3 b3\"/><text x=\"366.0\" y=\"154.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b3\">서브층<\/text><line x1=\"366\" y1=\"178\" x2=\"366.0\" y2=\"172.4\" class=\"e b3\"/><polygon points=\"366,166 362.0,174.0 370.0,174.0\" class=\"arrow b3\"/><rect x=\"316\" y=\"96\" width=\"100\" height=\"26\" rx=\"2\" class=\"n b4\"/><text x=\"366.0\" y=\"113.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tl b4\">더하기<\/text><line x1=\"366\" y1=\"134\" x2=\"366.0\" y2=\"130.4\" class=\"e b4\"/><polygon points=\"366,124 362.0,132.0 370.0,132.0\" class=\"arrow b4\"/><line x1=\"286\" y1=\"222\" x2=\"286\" y2=\"109\" class=\"e2 b4\"/><line x1=\"286\" y1=\"109\" x2=\"307.6\" y2=\"109.0\" class=\"e2 b4\"/><polygon points=\"314,109 306.0,105.0 306.0,113.0\" class=\"arrow b4\"/><text x=\"366\" y=\"74\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b4\">x + f(LN(x))<\/text><\/svg>","caption":"왼쪽 Post-LN 은 더한 다음 정규화해요. 오른쪽 Pre-LN 은 먼저 정규화하고 서브층에 넣어요.","builds":4},{"kind":"analogy","head":"빨래를 언제 개나요","scene":"빨래를 개서 바구니에 넣을 수도 있고, 바구니에 다 모은 다음에 갤 수도 있어요. 순서만 바뀌는데 바구니가 훨씬 깔끔해져요.","map":[["바구니","잔차 경로"],["먼저 개고 넣기","Pre-LN"],["모은 다음에 개기","Post-LN"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["The 2017 paper normalised after the residual addition","2017년 논문은 잔차를 더한 뒤에 정규화했다"],["It works, but needs a careful learning-rate warmup","되기는 되는데 조심스러운 학습률 워밍업이 필요하다"],["or training diverges","아니면 학습이 발산한다"],["Putting LayerNorm before the sublayer keeps the residual path completely clean","LayerNorm 을 서브층 앞에 두면 잔차 경로가 완전히 깨끗해진다"],["Every modern LLM does this","요즘 LLM 은 다 이렇게 한다"],["A two-line change that made 100-layer stacks routine","두 줄 바꿔서 100층 쌓기를 평범한 일로 만든 변화"]]},{"kind":"compare","head":"두 방식 비교","cols":["","Post-LN","Pre-LN"],"rows":[["식","LN(x + f(x))","x + f(LN(x))"],["정규화 위치","더한 다음","서브층에 넣기 전"],["잔차 경로","정규화를 거쳐요","손대지 않아 깨끗해요"],["쓰는 곳","2017년 원 논문","요즘 **LLM(대규모 언어 모델)** 들"],["주의","학습률 워밍업이 꼭 필요해요","그대로 깊게 쌓기 쉬워요"]]},{"kind":"points","head":"용어 하나씩","items":["**학습률(Learning Rate)**: 한 걸음의 보폭이에요. 3주차에 배웠어요","워밍업: 처음에는 보폭을 아주 작게 시작해 서서히 키우는 것이에요","발산: 손실이 줄지 않고 커져서 학습이 터지는 것이에요"]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.187,"w":0.83,"h":0.066,"say":"첫 점: 2017년 논문은 잔차를 더한 뒤 정규화. 워밍업이 없으면 발산."},{"x":0.06,"y":0.276,"w":0.78,"h":0.028,"say":"둘째 점: LayerNorm 을 앞에 두면 잔차 경로가 깨끗하다. 요즘 LLM 이 다 이 방식."},{"x":0.21,"y":0.399,"w":0.27,"h":0.405,"say":"왼쪽 상자 Post-LN: x 에서 서브층, 더하기, 그 위에 LayerNorm."},{"x":0.28,"y":0.43,"w":0.14,"h":0.035,"say":"왼쪽 위 식 LN(x + f(x)) 이 Post-LN 이에요."},{"x":0.49,"y":0.399,"w":0.26,"h":0.405,"say":"오른쪽 Pre-LN: x 에서 LayerNorm, 서브층, 그다음 더하기."},{"x":0.57,"y":0.43,"w":0.14,"h":0.035,"say":"오른쪽 위 식 x + f(LN(x)) 가 Pre-LN 이에요."}]},{"kind":"formula","head":"두 방식의 식","tex":"\\text{Post-LN: } \\mathrm{LN}\\big(x+f(x)\\big)\\qquad \\text{Pre-LN: } x+f\\big(\\mathrm{LN}(x)\\big)","parts":[{"sym":"x","say":"이 서브층에 들어온 값"},{"sym":"f","say":"서브층. 셀프 어텐션이거나 피드포워드예요"},{"sym":"\\mathrm{LN}","say":"층 정규화"},{"sym":"x+f(\\mathrm{LN}(x))","say":"Pre-LN. 바깥의 x 가 아무것도 안 거치고 그대로 남아요"}],"whole":"Pre-LN 은 더해지는 x 가 손대지 않은 값이라 잔차 경로가 완전히 깨끗해요."},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 2017년 제가 설명하고 있는 트랜스포머에서는 이 Post-LN 방법을 사용했어요.","교수님: 여러 실험을 했을 때 Pre-LN 이 좋다는 게 많이 밝혀져서 요즘 LLM 은 대부분 Pre-LN 을 써요.","교수님: 사실 최근에는 RMSNorm 같은 것도 많이 쓰거든요. 그래서 '다 쓴다' 보다는 '흔하다' 로 봐 주세요.","교수님: 트랜스포머에서는 Post-LN 이 쓰였다, 이 정도로만 보면 될 것 같아요."]},{"kind":"bg","src":"기초 다지기 8단원","lines":["**학습률(Learning Rate)**은 경사 하강법의 보폭이에요. 크면 빨리 가지만 튕겨 나갈 수 있어요.","워밍업은 처음 몇백 걸음 동안 보폭을 0 에서부터 천천히 키우는 방법이에요.","Post-LN 은 이 워밍업 없이 큰 보폭으로 시작하면 바로 학습이 터져요."]}],"pass4":[{"kind":"check","q":"2017년 원 논문이 쓴 방식은","choices":["Post-LN","Pre-LN","둘 다","둘 다 아님"],"a":0,"why":"원 논문은 잔차를 더한 다음 정규화하는 Post-LN 이에요. 요즘은 Pre-LN 이 흔해요."},{"kind":"check","q":"Pre-LN 의 장점은","choices":["잔차 경로가 정규화를 안 거쳐 깨끗해요","파라미터가 줄어요","계산이 절반이 돼요","마스킹이 필요 없어요"],"a":0,"why":"슬라이드: keeps the residual path completely clean."},{"kind":"english","head":"답안 문장","en":"Post-LN 은 **잔차 연결(Residual Connection)**을 더한 뒤 정규화해 LN(x + f(x)) 이고, Pre-LN 은 x + f(LN(x)) 이다.","ko":"두 식을 그대로 쓸 수 있으면 끝이에요.","tip":"Post 는 더한 뒤, Pre 는 넣기 전 으로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["Pre 와 Post 는 서브층 기준이에요. Pre-LN 은 서브층 앞, Post-LN 은 잔차 더하기 뒤예요.","교수님이 직접 말을 완화했어요. 모든 **LLM(대규모 언어 모델)**이 Pre-LN 인 것은 아니고, 흔하다는 뜻이에요."]}]},{"p":52,"title":"인코더 블록과 디코더 블록","terms":["Encoder","Decoder","Self-Attention","Multi-Head Attention (MHA)","Residual Connection","Layer Normalization (LayerNorm)","Position-wise Feed-Forward Network (FFN)","Causal Masking","Cross-Attention","Transformer","Token"],"pass1":[{"kind":"say","lines":["이제 배운 부품을 조립해요. 블록은 딱 두 종류예요.","**인코더(Encoder)** 블록은 **셀프 어텐션(Self-Attention)**과 피드포워드 두 층이에요.","**디코더(Decoder)** 블록은 거기에 마스킹과 **크로스 어텐션(Cross-Attention)**이 더 붙어요."]},{"kind":"figure","head":"블록 두 개가 전부예요","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"112\" y=\"20\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">인코더 블록<\/text><rect x=\"24\" y=\"178\" width=\"176\" height=\"26\" rx=\"2\" class=\"n2 b1\"/><text x=\"112.0\" y=\"195.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">멀티 헤드 셀프 어텐션<\/text><rect x=\"24\" y=\"144\" width=\"176\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"112.0\" y=\"161.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">Add and Norm<\/text><rect x=\"24\" y=\"110\" width=\"176\" height=\"26\" rx=\"2\" class=\"n3 b1\"/><text x=\"112.0\" y=\"127.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">피드포워드<\/text><rect x=\"24\" y=\"76\" width=\"176\" height=\"26\" rx=\"2\" class=\"n b1\"/><text x=\"112.0\" y=\"93.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b1\">Add and Norm<\/text><text x=\"112\" y=\"220\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">양방향. 원문 전체를 봐요<\/text><line x1=\"240\" y1=\"34\" x2=\"240\" y2=\"250\" class=\"e b2\"/><text x=\"368\" y=\"20\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">디코더 블록<\/text><rect x=\"280\" y=\"212\" width=\"176\" height=\"24\" rx=\"2\" class=\"n2 b2\"/><text x=\"368.0\" y=\"228.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">마스킹된 셀프 어텐션<\/text><rect x=\"280\" y=\"182\" width=\"176\" height=\"24\" rx=\"2\" class=\"n b2\"/><text x=\"368.0\" y=\"198.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">Add and Norm<\/text><rect x=\"280\" y=\"152\" width=\"176\" height=\"24\" rx=\"2\" class=\"n4 b3\"/><text x=\"368.0\" y=\"168.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b3\">크로스 어텐션<\/text><rect x=\"280\" y=\"122\" width=\"176\" height=\"24\" rx=\"2\" class=\"n b3\"/><text x=\"368.0\" y=\"138.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b3\">Add and Norm<\/text><rect x=\"280\" y=\"92\" width=\"176\" height=\"24\" rx=\"2\" class=\"n3 b3\"/><text x=\"368.0\" y=\"108.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b3\">피드포워드<\/text><rect x=\"280\" y=\"62\" width=\"176\" height=\"24\" rx=\"2\" class=\"n b3\"/><text x=\"368.0\" y=\"78.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b3\">Add and Norm<\/text><text x=\"368\" y=\"254\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">인과적. 자기가 쓴 것까지만 봐요<\/text><\/svg>","caption":"왼쪽 인코더 블록은 서브층 2개, 오른쪽 디코더 블록은 서브층 3개예요.","builds":4},{"kind":"points","head":"한 줄 요약","items":["**인코더(Encoder)** 블록: 셀프 어텐션 -> Add & Norm -> 피드포워드 -> Add & Norm","**디코더(Decoder)** 블록: 위에다 마스킹된 셀프 어텐션과 **크로스 어텐션(Cross-Attention)**을 더한 것"]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Encoder block: self-attention, Add & Norm, feed-forward, Add & Norm","인코더 블록은 셀프 어텐션, 더하고 정규화, 피드포워드, 더하고 정규화"],["Bidirectional","양방향이다. 앞뒤를 다 본다"],["Decoder block: the same, plus a masked self-attention at the bottom","디코더 블록은 같은데 아래에 마스킹된 셀프 어텐션이 더 있다"],["and a cross-attention in the middle","그리고 가운데에 크로스 어텐션이 있다"],["bidirectional, sees the whole source","양방향, 원문 전체를 본다"],["causal, sees only what it has written","인과적, 자기가 써 놓은 것만 본다"]]},{"kind":"points","head":"Add & Norm 이 무슨 뜻인가요","items":["Add 는 **잔차 연결(Residual Connection)**이에요. 서브층 입력을 출력에 더해요","Norm 은 **LayerNorm(층 정규화)**이에요. 더한 값을 평균 0, 분산 1 로 맞춰요","즉 Add & Norm 한 칸은 앞에서 배운 두 장치를 한 번에 적은 것이에요"]},{"kind":"steps","head":"인코더 블록을 순서대로 지나가 봐요","steps":["**토큰(Token)** n 개가 각각 d 칸을 가진 표가 들어와요","**멀티 헤드 어텐션(Multi-Head Attention (MHA))**로 서로를 봐요. 마스크가 없어서 앞뒤를 다 봐요","Add & Norm: 입력을 더하고 정규화해요","**FFN(위치별 피드포워드 신경망)**이 토큰마다 따로 깊게 처리해요","Add & Norm 을 한 번 더 해요","나온 표를 다음 블록에 그대로 넘겨요"],"answer":"인코더 블록은 서브층 2개. 이것을 N 번 쌓아요."},{"kind":"check","q":"**디코더(Decoder)** 블록에만 있고 **인코더(Encoder)** 블록에는 없는 것은","choices":["마스킹된 셀프 어텐션과 크로스 어텐션","피드포워드","Add & Norm","잔차 연결"],"a":0,"why":"인코더는 미래 토큰을 봐도 상관없어서 마스크가 없어요."}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.199,"w":0.65,"h":0.032,"say":"첫 점: 인코더 블록은 셀프 어텐션, Add & Norm, 피드포워드, Add & Norm."},{"x":0.06,"y":0.248,"w":0.73,"h":0.032,"say":"둘째 점: 디코더 블록은 여기에 마스킹과 크로스 어텐션이 더 붙는다."},{"x":0.07,"y":0.5,"w":0.34,"h":0.31,"say":"왼쪽 주황 점선 상자가 인코더 블록. 맨 아래가 멀티 헤드 셀프 어텐션."},{"x":0.07,"y":0.79,"w":0.34,"h":0.028,"say":"인코더 아래 글씨: bidirectional, 원문 전체를 본다."},{"x":0.5,"y":0.592,"w":0.3,"h":0.047,"say":"디코더 가운데 초록 상자가 CROSS-attention 이에요."},{"x":0.5,"y":0.725,"w":0.3,"h":0.049,"say":"디코더 맨 아래가 MASKED self-attention 이에요."}]},{"kind":"compare","head":"두 블록의 서브층을 세어 봐요","cols":["블록","서브층","마스크","보는 범위"],"rows":[["인코더 블록","셀프 어텐션, 피드포워드 (2개)","없어요","원문 전체"],["디코더 블록","마스킹 셀프, 크로스, 피드포워드 (3개)","맨 아래에 있어요","자기가 쓴 것까지"]]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 인코더 쪽은 미래의 토큰을 봐도 상관이 없단 말이죠. 그래서 마스크가 없고요.","교수님: 인코더는 양방향 셀프 어텐션, 디코더는 마스킹 셀프 어텐션 형태다.","교수님: 번역할 때 I love you 에 대한 정보가 있어야 디코더가 생성해 나갈 거 아니에요.","교수님: 그래서 인코더에 있는 정보를 끌어오는 크로스 어텐션을 해 줍니다."]},{"kind":"bg","src":"기초 다지기 9단원","lines":["**FFN(위치별 피드포워드 신경망)**은 뉴런 층 두 개짜리 아주 작은 신경망이에요.","속 차원을 4d 로 넓혔다가 다시 d 로 줄여요. 그 사이에 비선형 함수가 들어가요.","토큰마다 따로 적용하기 때문에 순서와 아무 상관이 없어요."]}],"pass4":[{"kind":"check","q":"인코더 블록이 양방향인 이유는","choices":["원문은 미래 토큰을 봐도 되니까","계산이 빨라서","파라미터가 적어서","마스크를 못 만들어서"],"a":0,"why":"교수님: 인코더 쪽은 미래의 토큰을 봐도 상관이 없어서 마스크가 없어요."},{"kind":"exam","src":"예상 문제","q":"트랜스포머 인코더 블록과 디코더 블록의 구성을 각각 쓰고 차이를 설명하시오.","qko":"블록 두 개를 아래에서 위로 그대로 적어 보세요.","solve":["인코더 블록: 멀티 헤드 셀프 어텐션 -> Add & Norm -> 피드포워드 -> Add & Norm","디코더 블록: 마스킹된 셀프 어텐션 -> Add & Norm -> 크로스 어텐션 -> Add & Norm -> 피드포워드 -> Add & Norm","차이 1: 디코더는 맨 아래에 인과 마스킹이 있어요","차이 2: 디코더 가운데에 크로스 어텐션이 있어요","인코더는 양방향, 디코더는 인과적이에요"],"answer":"서브층이 인코더는 2개, 디코더는 3개예요."},{"kind":"english","head":"답안 문장","en":"**인코더(Encoder)** 블록은 서브층 2개로 양방향, **디코더(Decoder)** 블록은 마스킹 **셀프 어텐션(Self-Attention)**과 **크로스 어텐션(Cross-Attention)**을 더한 서브층 3개예요.","ko":"서브층 개수와 마스크 유무를 반드시 함께 써요.","tip":"인코더 2층, 디코더 3층 으로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["Add & Norm 은 새 부품이 아니에요. **잔차 연결(Residual Connection)**과 **LayerNorm(층 정규화)**을 한 칸에 적은 것이에요.","**인과 마스킹(Causal Masking)**은 디코더 맨 아래 셀프 어텐션에만 걸려요. 크로스 어텐션에는 걸지 않아요."]}]},{"p":53,"title":"크로스 어텐션이 둘을 잇는다","terms":["Cross-Attention","Self-Attention","Query","Key","Value","Encoder","Decoder","Attention","Context Vector","Machine Translation (MT)","Information Bottleneck","Dot Product"],"pass1":[{"kind":"say","lines":["**디코더(Decoder)** 블록 가운데 서브층이 **크로스 어텐션(Cross-Attention)**이에요.","**쿼리(Query)**는 디코더에서 나오고, **키(Key)**와 **밸류(Value)**는 인코더 출력에서 가져와요.","2장에서 배운 2015년 어텐션이 그대로 돌아온 거예요. 원이 여기서 닫혀요."]},{"kind":"figure","head":"쿼리는 디코더, 키와 밸류는 인코더","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"20\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">쿼리는 디코더, 키와 밸류는 인코더<\/text><rect x=\"20\" y=\"46\" width=\"180\" height=\"30\" rx=\"2\" class=\"box b1\"/><text x=\"110.0\" y=\"65.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">인코더 출력 H<\/text><text x=\"110\" y=\"92\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">원문 문장 전체<\/text><rect x=\"280\" y=\"46\" width=\"180\" height=\"30\" rx=\"2\" class=\"box2 b1\"/><text x=\"370.0\" y=\"65.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">디코더 상태 S<\/text><text x=\"370\" y=\"92\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">지금까지 쓴 번역문<\/text><rect x=\"20\" y=\"108\" width=\"84\" height=\"28\" rx=\"2\" class=\"n3 b2\"/><text x=\"62.0\" y=\"126.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">K = H W^K<\/text><rect x=\"116\" y=\"108\" width=\"84\" height=\"28\" rx=\"2\" class=\"n3 b2\"/><text x=\"158.0\" y=\"126.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">V = H W^V<\/text><line x1=\"80\" y1=\"78\" x2=\"65.5\" y2=\"100.6\" class=\"e b2\"/><polygon points=\"62,106 69.7,101.4 63.0,97.1\" class=\"arrow b2\"/><line x1=\"140\" y1=\"78\" x2=\"154.5\" y2=\"100.6\" class=\"e b2\"/><polygon points=\"158,106 157.0,97.1 150.3,101.4\" class=\"arrow b2\"/><rect x=\"320\" y=\"108\" width=\"96\" height=\"28\" rx=\"2\" class=\"n2 b2\"/><text x=\"368.0\" y=\"126.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tl b2\">Q = S W^Q<\/text><line x1=\"370\" y1=\"78\" x2=\"368.5\" y2=\"99.6\" class=\"e2 b2\"/><polygon points=\"368,106 372.6,98.3 364.6,97.7\" class=\"arrow b2\"/><rect x=\"120\" y=\"170\" width=\"240\" height=\"32\" rx=\"2\" class=\"n4 b3\"/><text x=\"240.0\" y=\"190.9\" font-size=\"14\" text-anchor=\"middle\" class=\"tl b3\">Attention(Q, K, V)<\/text><line x1=\"62\" y1=\"138\" x2=\"163.8\" y2=\"166.3\" class=\"e b3\"/><polygon points=\"170,168 163.4,162.0 161.2,169.7\" class=\"arrow b3\"/><line x1=\"158\" y1=\"138\" x2=\"214.2\" y2=\"165.2\" class=\"e b3\"/><polygon points=\"220,168 214.5,160.9 211.1,168.1\" class=\"arrow b3\"/><line x1=\"368\" y1=\"138\" x2=\"315.7\" y2=\"165.1\" class=\"e2 b3\"/><polygon points=\"310,168 318.9,167.9 315.3,160.8\" class=\"arrow b3\"/><text x=\"240\" y=\"232\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">2장에서 배운 2015년 어텐션 그대로예요<\/text><text x=\"240\" y=\"256\" font-size=\"13\" text-anchor=\"middle\" class=\"t b4\">표기만 Q, K, V 로 바뀌었어요<\/text><\/svg>","caption":"왼쪽 인코더 출력에서 K 와 V 를, 오른쪽 디코더 상태에서 Q 를 만들어 어텐션해요.","builds":4},{"kind":"analogy","head":"시험 볼 때 교과서 다시 펼치기","scene":"2장에서 쓴 비유 그대로예요. 답을 한 줄 쓸 때마다 교과서에서 필요한 쪽을 다시 펼쳐 봐요.","map":[["지금 쓰고 있는 답","디코더 상태에서 만든 쿼리"],["교과서의 쪽 번호","인코더 출력에서 만든 키"],["그 쪽에 적힌 내용","인코더 출력에서 만든 밸류"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["In the decoder's middle sublayer the queries come from the decoder","디코더의 가운데 서브층에서 쿼리는 디코더에서 온다"],["but the keys and values come from the encoder output","그런데 키와 밸류는 인코더 출력에서 온다"],["This is literally the 2015 attention of section 2","이것은 말 그대로 2장의 2015년 어텐션이다"],["rewritten in Q / K / V notation","Q / K / V 표기로 다시 쓴 것뿐이다"],["The circle closes here","원이 여기서 닫힌다"],["Self-attention looks inward, cross-attention looks across","셀프 어텐션은 안을 보고, 크로스 어텐션은 건너편을 본다"]]},{"kind":"compare","head":"셀프 어텐션과 크로스 어텐션","cols":["","셀프 어텐션","크로스 어텐션"],"rows":[["쿼리 출처","같은 시퀀스","디코더"],["키, 밸류 출처","같은 시퀀스","인코더 출력"],["보는 방향","자기 안쪽","건너편"],["계산 방법","같아요","같아요"]]},{"kind":"points","head":"용어 하나씩","items":["**크로스 어텐션(Cross-Attention)**: 쿼리와 키, 밸류가 서로 다른 쪽에서 나오는 어텐션이에요","**셀프 어텐션(Self-Attention)**: 쿼리, 키, 밸류가 모두 같은 시퀀스에서 나오는 어텐션이에요","**문맥 벡터(Context Vector)**: 밸류들의 가중 평균. 여기서도 똑같이 만들어져요"]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.199,"w":0.85,"h":0.032,"say":"첫 점: 쿼리는 디코더에서, 키와 밸류는 인코더 출력에서 온다."},{"x":0.06,"y":0.248,"w":0.75,"h":0.032,"say":"둘째 점: 이것이 바로 2장의 2015년 어텐션이다. 원이 여기서 닫힌다."},{"x":0.14,"y":0.358,"w":0.27,"h":0.066,"say":"왼쪽 위 주황 상자: Encoder output H, 위 글씨는 원문 문장 전체."},{"x":0.6,"y":0.358,"w":0.26,"h":0.066,"say":"오른쪽 위 초록 상자: Decoder state S, 지금까지 만든 번역문."},{"x":0.14,"y":0.484,"w":0.27,"h":0.058,"say":"왼쪽 아래 두 상자: K = H W^K 와 V = H W^V."},{"x":0.34,"y":0.605,"w":0.32,"h":0.063,"say":"가운데 파란 상자 Attention(Q, K, V) 로 세 화살표가 모여요."}]},{"kind":"formula","head":"크로스 어텐션의 Q, K, V","tex":"Q=S\\,W^{Q}\\ \\text{(decoder)},\\qquad K=H\\,W^{K},\\ V=H\\,W^{V}\\ \\text{(encoder)}","parts":[{"sym":"S","say":"디코더 상태. 지금까지 쓴 번역문의 표현이에요"},{"sym":"H","say":"인코더 출력. 원문 문장 전체의 표현이에요"},{"sym":"Q=S\\,W^{Q}","say":"쿼리는 디코더 쪽에서 만들어요"},{"sym":"K=H\\,W^{K}","say":"키는 인코더 쪽에서 만들어요"},{"sym":"V=H\\,W^{V}","say":"밸류도 인코더 쪽에서 만들어요"}],"whole":"Q 만 디코더, K 와 V 는 인코더. 이 한 가지가 셀프 어텐션과의 유일한 차이예요."},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 크로스 어텐션은 쿼리는 디코더 상태에서 나오고 키랑 밸류는 인코더 출력에서 가져옵니다.","교수님: 2장에서 배운 그 개념이죠. 인코더와 디코더 블록을 연결해 주는 게 크로스 어텐션입니다.","교수님: 셀프 어텐션은 쿼리 키 밸류가 각각의 시퀀스에서 따로따로 나옵니다.","교수님: 계산 방법은 같다, 다만 Q, K, V 가 어디서 나오냐에 차이가 있다."]},{"kind":"bg","src":"기초 다지기 2단원","lines":["**어텐션(Attention)** 계산은 **내적(Dot Product)**으로 점수를 내고, 소프트맥스로 합을 1 로 만들고, 가중합을 하는 것이에요.","크로스 어텐션도 이 순서가 똑같아요. 재료를 어디서 가져오는지만 달라요.","그래서 새로 외울 계산이 하나도 없어요."]}],"pass4":[{"kind":"check","q":"**크로스 어텐션(Cross-Attention)**에서 **키(Key)**와 **밸류(Value)**가 나오는 곳은","choices":["인코더 출력","디코더 상태","임베딩 층","출력 소프트맥스"],"a":0,"why":"쿼리만 디코더에서 나와요. 키와 밸류는 인코더 출력에서 나와요."},{"kind":"exam","src":"예상 문제","q":"셀프 어텐션과 크로스 어텐션의 차이를 Q, K, V 의 출처로 설명하시오.","qko":"계산은 같고 재료만 다르다는 점을 써 보세요.","solve":["두 어텐션 모두 점수, 소프트맥스, 가중합 계산은 완전히 같아요","셀프 어텐션은 Q, K, V 가 모두 같은 시퀀스에서 나와요","크로스 어텐션은 Q 가 디코더, K 와 V 가 인코더 출력에서 나와요","그래서 셀프는 안쪽을, 크로스는 건너편을 봐요"],"answer":"차이는 오직 Q, K, V 를 어디서 만드는가입니다."},{"kind":"english","head":"답안 문장","en":"**크로스 어텐션(Cross-Attention)**은 **쿼리(Query)**가 **디코더(Decoder)**, **키(Key)**와 **밸류(Value)**가 **인코더(Encoder)**에서 나온다는 점만 다르다.","ko":"계산은 2장에서 **정보 병목(Information Bottleneck)**을 없앤 그 **어텐션(Attention)**과 똑같아요. 출처만 달라요.","tip":"Q 는 디코더, K 와 V 는 인코더 로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**크로스 어텐션(Cross-Attention)**은 새로운 계산이 아니에요. **기계 번역(Machine Translation (MT))**에서 쓰던 2015년 어텐션 그대로예요.","키와 밸류는 항상 같은 쪽에서 나와요. 키만 인코더, 밸류만 디코더 같은 건 없어요."]}]},{"p":54,"title":"트랜스포머 전체 구조","terms":["Transformer","Encoder","Decoder","Positional Encoding","Embedding","Multi-Head Attention (MHA)","Cross-Attention","Causal Masking","Softmax","Position-wise Feed-Forward Network (FFN)","Residual Connection","Layer Normalization (LayerNorm)","Self-Attention"],"pass1":[{"kind":"say","lines":["오늘 배운 모든 부품이 이 한 장에 다 들어 있어요.","슬라이드의 모든 상자가 우리가 지난 몇 시간 동안 만든 것들이에요.","슬라이드가 시키는 것은 하나예요. 노트를 덮고 이 그림을 다시 그려 보세요."]},{"kind":"figure","head":"전체 구조 한 장","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"110\" y=\"18\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">인코더 x N<\/text><rect x=\"20\" y=\"208\" width=\"172\" height=\"24\" rx=\"2\" class=\"n b1\"/><text x=\"106.0\" y=\"223.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b1\">입력 임베딩 + 위치 인코딩<\/text><rect x=\"20\" y=\"178\" width=\"172\" height=\"24\" rx=\"2\" class=\"n2 b1\"/><text x=\"106.0\" y=\"193.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b1\">멀티 헤드 셀프 어텐션<\/text><rect x=\"20\" y=\"148\" width=\"172\" height=\"24\" rx=\"2\" class=\"n b1\"/><text x=\"106.0\" y=\"163.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b1\">Add and Norm<\/text><rect x=\"20\" y=\"118\" width=\"172\" height=\"24\" rx=\"2\" class=\"n3 b1\"/><text x=\"106.0\" y=\"133.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b1\">피드포워드<\/text><rect x=\"20\" y=\"88\" width=\"172\" height=\"24\" rx=\"2\" class=\"n b1\"/><text x=\"106.0\" y=\"103.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b1\">Add and Norm<\/text><text x=\"110\" y=\"252\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">원문 문장<\/text><text x=\"370\" y=\"18\" font-size=\"14\" text-anchor=\"middle\" class=\"tb\">디코더 x N<\/text><rect x=\"284\" y=\"208\" width=\"172\" height=\"24\" rx=\"2\" class=\"n b2\"/><text x=\"370.0\" y=\"223.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b2\">출력 임베딩 + 위치 인코딩<\/text><rect x=\"284\" y=\"178\" width=\"172\" height=\"24\" rx=\"2\" class=\"n2 b2\"/><text x=\"370.0\" y=\"193.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b2\">마스킹된 셀프 어텐션<\/text><rect x=\"284\" y=\"148\" width=\"172\" height=\"24\" rx=\"2\" class=\"n4 b2\"/><text x=\"370.0\" y=\"163.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b2\">멀티 헤드 크로스 어텐션<\/text><rect x=\"284\" y=\"118\" width=\"172\" height=\"24\" rx=\"2\" class=\"n3 b2\"/><text x=\"370.0\" y=\"133.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b2\">피드포워드<\/text><rect x=\"284\" y=\"88\" width=\"172\" height=\"24\" rx=\"2\" class=\"n b2\"/><text x=\"370.0\" y=\"103.85\" font-size=\"11\" text-anchor=\"middle\" class=\"tl b2\">Add and Norm<\/text><text x=\"370\" y=\"252\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">지금까지 쓴 번역문<\/text><line x1=\"194\" y1=\"100\" x2=\"276.5\" y2=\"148.7\" class=\"e2 b3\"/><polygon points=\"282,152 277.1,144.5 273.1,151.4\" class=\"arrow b3\"/><text x=\"240\" y=\"126\" font-size=\"11\" text-anchor=\"middle\" class=\"tm b3\">키와 밸류<\/text><rect x=\"284\" y=\"50\" width=\"172\" height=\"24\" rx=\"2\" class=\"box2 b4\"/><text x=\"370.0\" y=\"66.2\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b4\">Linear + Softmax<\/text><line x1=\"370\" y1=\"86\" x2=\"370.0\" y2=\"82.4\" class=\"e b4\"/><polygon points=\"370,76 366.0,84.0 374.0,84.0\" class=\"arrow b4\"/><text x=\"370\" y=\"38\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b4\">다음 토큰 확률<\/text><\/svg>","caption":"왼쪽이 인코더 N 층, 오른쪽이 디코더 N 층. 인코더 출력이 크로스 어텐션의 키와 밸류로 건너가요.","builds":4},{"kind":"points","head":"한 줄 요약","items":["아래에서 위로: **임베딩(Embedding)** + **위치 인코딩(Positional Encoding)** -> 블록 N 번 -> Linear + **소프트맥스(Softmax)**","그리기 시험이 바로 이 쪽이에요"]}],"pass2":[{"kind":"steps","head":"아래에서 위로 한 칸씩 읽어요 (인코더)","steps":["입력 **임베딩(Embedding)**에 **위치 인코딩(Positional Encoding)**를 더해요. 순서를 알려 주는 단계예요","**멀티 헤드 어텐션(Multi-Head Attention (MHA))** **셀프 어텐션(Self-Attention)**. 마스크가 없어요","Add & Norm (**잔차 연결(Residual Connection)** + **LayerNorm(층 정규화)**)","**FFN(위치별 피드포워드 신경망)**","Add & Norm 을 한 번 더","이 블록을 N 번 반복하고, 마지막 출력을 디코더로 보내요"],"answer":"인코더 출력 H 가 크로스 어텐션의 키와 밸류가 돼요."},{"kind":"steps","head":"아래에서 위로 한 칸씩 읽어요 (디코더)","steps":["출력 **임베딩(Embedding)**에 **위치 인코딩(Positional Encoding)**를 더해요","마스킹된 **멀티 헤드 어텐션(Multi-Head Attention (MHA))** **셀프 어텐션(Self-Attention)**. **인과 마스킹(Causal Masking)**이 걸려요","Add & Norm","멀티 헤드 **크로스 어텐션(Cross-Attention)**. 키와 밸류는 인코더에서 와요","Add & Norm, 그다음 피드포워드, 다시 Add & Norm","맨 위에서 Linear 를 지나 **소프트맥스(Softmax)**로 다음 토큰의 확률을 내요"],"answer":"디코더는 블록 N 번을 지나 마지막에 어휘 크기의 확률을 만들어요."},{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Every box on this diagram is something we built in the last hours","이 그림의 모든 상자는 지난 몇 시간 동안 우리가 만든 것이다"],["Encoder x N","인코더 블록을 N 번 쌓는다"],["keys and values from the encoder","키와 밸류는 인코더에서 온다"],["Close your notes and try to redraw this","노트를 덮고 이것을 다시 그려 보라"],["that is the test","그것이 바로 시험이다"]]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.199,"w":0.5,"h":0.032,"say":"첫 점: 이 그림의 모든 상자를 오늘 다 만들었다."},{"x":0.25,"y":0.481,"w":0.23,"h":0.285,"say":"왼쪽 주황 점선이 인코더 스택. 맨 아래가 입력 임베딩 + 위치 인코딩."},{"x":0.52,"y":0.367,"w":0.24,"h":0.399,"say":"오른쪽 초록 점선이 디코더 스택. 맨 아래가 출력 임베딩 + 위치 인코딩."},{"x":0.39,"y":0.418,"w":0.09,"h":0.044,"say":"가운데 초록 화살표에 keys and values from the encoder 라고 적혀 있어요."},{"x":0.53,"y":0.308,"w":0.21,"h":0.032,"say":"디코더 맨 위 진한 상자가 Linear + softmax 예요."},{"x":0.79,"y":0.491,"w":0.17,"h":0.41,"say":"오른쪽 작은 그림이 2017년 원 논문의 그림이에요."}]},{"kind":"points","head":"상자마다 어디서 배웠는지","items":["**위치 인코딩(Positional Encoding)**: 셀프 어텐션이 순서를 몰라서 넣었어요","마스킹된 **셀프 어텐션(Self-Attention)**: 미래를 못 보게 하려고 넣었어요","**FFN(위치별 피드포워드 신경망)**: 토큰마다 깊은 비선형 처리를 하려고 넣었어요","**멀티 헤드 어텐션(Multi-Head Attention (MHA))**, **잔차 연결(Residual Connection)**, **LayerNorm(층 정규화)**: 오늘 4장에서 더한 세 가지예요","**크로스 어텐션(Cross-Attention)**: 인코더 정보를 디코더로 끌어오려고 넣었어요"]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 이제 진짜 다 배웠습니다. 지금까지 배운 구성 요소들을 트랜스포머 블록으로 조립해 보면.","교수님: 오늘 배운 인코더와 디코더를 구성하는 모든 요소들이 다 이 슬라이드에 있어요.","교수님: 이 슬라이드를 배우기 위해서 지금까지 달려왔다고 보시면 될 것 같습니다.","교수님: Attention Is All You Need 논문은 무조건 꼭 읽어 보시길 매우 추천드립니다."]},{"kind":"bg","src":"기초 다지기 10단원","lines":["Linear 는 행렬 곱 한 번이에요. d 칸을 어휘 크기 칸으로 바꿔요.","그 위에 **소프트맥스(Softmax)**를 씌우면 어휘의 각 토큰이 나올 확률이 돼요.","3주차 언어 모델에서 본 마지막 단계와 똑같아요."]}],"pass4":[{"kind":"check","q":"인코더 출력이 디코더에서 맡는 역할은","choices":["크로스 어텐션의 키와 밸류","디코더의 쿼리","위치 인코딩","소프트맥스의 입력"],"a":0,"why":"슬라이드의 초록 화살표에 keys and values from the encoder 라고 적혀 있어요."},{"kind":"exam","src":"예상 문제","q":"트랜스포머 전체 구조를 아래에서 위로 그리시오.","qko":"인코더 쪽과 디코더 쪽을 나란히 그리고 화살표를 하나 그으면 돼요.","solve":["양쪽 맨 아래에 임베딩 + 위치 인코딩을 그려요","인코더: 멀티 헤드 셀프 어텐션, Add & Norm, 피드포워드, Add & Norm","디코더: 마스킹된 셀프 어텐션, Add & Norm, 크로스 어텐션, Add & Norm, 피드포워드, Add & Norm","인코더 맨 위에서 디코더 크로스 어텐션으로 화살표를 긋고 키와 밸류라고 적어요","두 스택 옆에 x N 을 적고, 디코더 위에 Linear + softmax 를 올려요"],"answer":"이 그림을 혼자 그릴 수 있으면 4강은 끝난 거예요."},{"kind":"english","head":"답안 문장","en":"**트랜스포머(Transformer)**는 **임베딩(Embedding)**와 **위치 인코딩(Positional Encoding)** 위에 **인코더(Encoder)** 블록과 **디코더(Decoder)** 블록을 N 개씩 쌓은 구조이다.","ko":"맨 위에서 Linear 와 **소프트맥스(Softmax)**로 다음 토큰 확률을 내요. 구조를 한 문장에 담아 보세요.","tip":"임베딩, 블록 N개, Linear + softmax 세 덩어리로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["x N 은 같은 블록을 N 개 쌓는다는 뜻이에요. 같은 블록을 N 번 돌리는 게 아니라 서로 다른 N 개예요.","**위치 인코딩(Positional Encoding)**는 맨 아래에서 한 번만 더해요. 블록마다 다시 더하지 않아요."]}]},{"p":55,"title":"치러야 할 값, 이차 비용","terms":["Quadratic Cost","Self-Attention","Attention Score","Parallelization","Recurrent Neural Network (RNN)","Convolutional Neural Network (CNN)","Large Language Model (LLM)","Token","Query","Key","Dot Product"],"pass1":[{"kind":"say","lines":["좋은 것만 있는 방법은 없어요. **트랜스포머(Transformer)**가 치르는 값이 이것이에요.","**셀프 어텐션(Self-Attention)**은 n 개의 토큰이 서로를 다 봐야 해서 n x n 짜리 점수 표를 만들어요.","그래서 계산도 메모리도 길이의 제곱으로 커져요. 이것이 **이차 비용(Quadratic Cost)**이에요."]},{"kind":"figure","head":"길이가 2배면 표는 4배","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"20\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">길이가 2배면 점수 표는 4배예요<\/text><text x=\"80\" y=\"48\" font-size=\"13\" text-anchor=\"middle\" class=\"tb\">n = 2<\/text><rect x=\"40\" y=\"60\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b1\"/><rect x=\"72\" y=\"60\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b1\"/><rect x=\"40\" y=\"92\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b1\"/><rect x=\"72\" y=\"92\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b1\"/><text x=\"72\" y=\"142\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">칸 4개<\/text><text x=\"230\" y=\"48\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">n = 4<\/text><rect x=\"166\" y=\"60\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"198\" y=\"60\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"230\" y=\"60\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"262\" y=\"60\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"166\" y=\"92\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"198\" y=\"92\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"230\" y=\"92\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"262\" y=\"92\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"166\" y=\"124\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"198\" y=\"124\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"230\" y=\"124\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"262\" y=\"124\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"166\" y=\"156\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"198\" y=\"156\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"230\" y=\"156\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><rect x=\"262\" y=\"156\" width=\"30\" height=\"30\" rx=\"2\" class=\"n2 b2\"/><text x=\"230\" y=\"206\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">칸 16개<\/text><text x=\"390\" y=\"80\" font-size=\"13\" text-anchor=\"middle\" class=\"t b3\">길이 2배<\/text><text x=\"390\" y=\"104\" font-size=\"15\" text-anchor=\"middle\" class=\"tb b3\">칸 4배<\/text><rect x=\"320\" y=\"128\" width=\"140\" height=\"52\" rx=\"2\" class=\"box2 b3\"/><text x=\"390\" y=\"150\" font-size=\"12\" text-anchor=\"middle\" class=\"t b3\">n = 512 이면 26만 칸<\/text><text x=\"390\" y=\"170\" font-size=\"12\" text-anchor=\"middle\" class=\"tb b3\">n = 128000 이면 164억 칸<\/text><text x=\"240\" y=\"238\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">계산도 메모리도 n 의 제곱으로 늘어나요<\/text><\/svg>","caption":"n = 2 이면 칸이 4개, n = 4 이면 칸이 16개. 길이가 2배가 되면 칸은 4배가 돼요.","builds":4},{"kind":"analogy","head":"반 친구들 악수하기","scene":"10명이면 서로 악수하는 짝이 얼마 안 되는데, 100명이 되면 훨씬 더 많이 늘어나요. 사람 수가 10배면 악수는 100배쯤이에요.","map":[["한 사람","토큰 하나"],["악수 한 번","어텐션 점수 한 칸"],["사람이 늘면 악수는 제곱으로","길이가 늘면 비용은 제곱으로"]]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["The score matrix is n x n","점수 행렬이 n 곱하기 n 이다"],["so both compute and memory grow with the square of the sequence length","그래서 계산도 메모리도 길이의 제곱으로 자란다"],["At n = 512 this is cheap","n = 512 에서는 싸다"],["At n = 128,000 it is the single biggest engineering problem in LLMs","n = 128,000 에서는 LLM 최대의 공학 문제다"],["FlashAttention, sliding windows, linear attention and state-space models","FlashAttention, 슬라이딩 윈도우, 선형 어텐션, 상태공간 모델"],["all attack exactly this","모두 정확히 이 문제를 공격한다"]]},{"kind":"points","head":"용어 하나씩","items":["**이차 비용(Quadratic Cost)**: 길이가 2배면 일이 4배가 되는 비용. **LLM(대규모 언어 모델)** 최대의 공학 문제예요","**어텐션 점수(Attention Score)**: **쿼리(Query)**와 **키(Key)**의 **내적(Dot Product)**으로 만든 날것 숫자예요","O(n 제곱): 길이 n 에 대해 제곱으로 자란다는 표시예요","**병렬화(Parallelization)**: 여러 계산을 한꺼번에 하기. 이건 트랜스포머가 얻은 것이에요"]},{"kind":"check","q":"셀프 어텐션의 점수 표 크기는","choices":["n x n","n x d","d x d","n x 1"],"a":0,"why":"모든 쿼리가 모든 키와 만나야 하니까 n 줄 n 칸이에요."}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.199,"w":0.68,"h":0.032,"say":"첫 점: 점수 행렬이 n x n 이라 계산도 메모리도 제곱으로 커진다."},{"x":0.06,"y":0.244,"w":0.87,"h":0.068,"say":"둘째 점: n = 512 는 싸고 n = 128,000 은 LLM 최대의 공학 문제."},{"x":0.11,"y":0.348,"w":0.33,"h":0.361,"say":"왼쪽 그래프: 초록은 RNN 의 O(n x d), 빨강은 어텐션의 O(n 제곱)."},{"x":0.52,"y":0.386,"w":0.36,"h":0.253,"say":"오른쪽 표: RNN, CNN, 셀프 어텐션의 경로 길이, 순차 연산, 층당 계산량."},{"x":0.52,"y":0.6,"w":0.36,"h":0.04,"say":"셀프 어텐션 줄: 경로 길이 O(1), 순차 연산 O(1), 계산 O(n 제곱 x d)."},{"x":0.14,"y":0.747,"w":0.72,"h":0.057,"say":"아래 식: scores 가 n x n 이라 계산은 O(n 제곱 d), 메모리는 O(n 제곱)."}]},{"kind":"compare","head":"슬라이드 표를 그대로 읽어요","cols":["모델","최대 경로 길이","순차 연산","층당 계산량"],"rows":[["RNN","O(n)","O(n)","O(n x d 제곱)"],["CNN (폭 k)","O(n / k)","O(1)","O(k x n x d 제곱)"],["셀프 어텐션","O(1)","O(1)","O(n 제곱 x d)"]]},{"kind":"steps","head":"n = 512 와 n = 128000 을 직접 세어 봐요","given":"n = 512 와 n = 128000","steps":["n = 512 이면 점수 표 칸 수는 512 x 512 = 262144 개","약 26만 개예요. 요즘 GPU 에는 아무것도 아니에요","n = 128000 이면 128000 x 128000 이에요","= 16,384,000,000 개, 약 164억 칸이에요","길이는 128000 나누기 512 = 250배 늘었을 뿐인데","칸 수는 250 의 제곱 = 62500배가 됐어요"],"answer":"길이 250배에 비용은 62500배. 이것이 이차 비용이에요."},{"kind":"steps","head":"RNN 과 비교해 봐요 (d = 512)","given":"n = 512, d = 512","steps":["RNN 은 자리마다 한 번씩만 계산해요. n x d = 512 x 512 = 262144","셀프 어텐션은 n 제곱 x d = 512 x 512 x 512 = 134217728","나누면 134217728 나누기 262144 = 512 배예요","대신 RNN 은 순차 연산이 O(n) 이라 512번을 줄 서서 기다려요","셀프 어텐션의 순차 연산은 O(1) 이라 한 번에 끝나요"],"answer":"계산량은 더 쓰지만 기다리는 횟수는 훨씬 적어요. 이게 맞바꾸기예요."},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 이 세상에 노 프리 런치라고 하는데, 진짜 그냥 좋은 방향으로만 가는 건 없어요.","교수님: 병렬로 가면 시간 복잡도는 확 줄어들지만 메모리는 훨씬 더 많이 써야 해요.","교수님: RNN 은 O(n) 메모리면 되는데 어텐션은 n 제곱이 필요하니까요.","교수님: 512 토큰은 금방 되는데, 128k 짜리 긴 소설을 다 넣으면 메모리도 계산도 엄청나게 커집니다."]},{"kind":"bg","src":"기초 다지기 3단원","lines":["n x n 표는 줄이 n 개, 칸이 n 개인 표예요. 칸 수는 n 곱하기 n 이에요.","n 이 2배가 되면 줄도 2배, 칸도 2배라서 전체는 4배가 돼요.","이것이 '제곱으로 자란다' 는 말의 뜻이에요."]}],"pass4":[{"kind":"check","q":"길이가 250배 늘어나면 어텐션 점수 표의 칸 수는","choices":["62500배","250배","500배","그대로"],"a":0,"why":"250 의 제곱이 62500 이에요. 128000 나누기 512 가 250 이에요."},{"kind":"check","q":"**이차 비용(Quadratic Cost)** 문제를 푸는 연구로 슬라이드가 든 것이 아닌 것은","choices":["교사 강요","FlashAttention","슬라이딩 윈도우","선형 어텐션"],"a":0,"why":"교사 강요는 학습 방법이에요. 슬라이드가 든 것은 FlashAttention, 슬라이딩 윈도우, 선형 어텐션, 상태공간 모델이에요."},{"kind":"english","head":"답안 문장","en":"**셀프 어텐션(Self-Attention)**은 n 개의 **쿼리(Query)**가 n 개의 **키(Key)**와 모두 비교되어 n x n 표를 만들어 **이차 비용(Quadratic Cost)**이 된다.","ko":"계산은 O(n 제곱 x d), 메모리는 O(n 제곱) 이에요. **어텐션 점수(Attention Score)** 표가 n x n 이라서예요.","tip":"n 개가 n 개를 다 본다 = n 제곱 으로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**병렬화(Parallelization)**는 얻은 것이고 **이차 비용(Quadratic Cost)**은 잃은 것이에요. 맞바꾸기예요.","RNN 이 무조건 더 싼 게 아니에요. RNN 은 순차 연산 O(n) 때문에 시간이 오래 걸려요."]}]},{"p":56,"title":"정말 잘 됐나요, WMT 결과","terms":["Transformer","BLEU","Machine Translation (MT)","Recurrent Neural Network (RNN)","Convolutional Neural Network (CNN)","Parallelization"],"pass1":[{"kind":"say","lines":["2017년 **트랜스포머(Transformer)** 논문이 낸 **기계 번역(Machine Translation (MT))** 성적이에요.","WMT 2014 영어에서 독일어로 번역하는 과제예요.","이전 방법을 모두 이겼고, 학습 비용은 훨씬 적었어요."]},{"kind":"compare","head":"WMT 2014 영어 -> 독일어 결과 (슬라이드 막대)","cols":["모델","BLEU (높을수록 좋음)","학습 비용 (GPU 일수)"],"rows":[["GNMT (RNN)","24.6","96"],["ConvSeq2Seq (CNN)","25.2","175"],["Transformer base","27.3","3.3"],["Transformer big","28.4","8.3"]]},{"kind":"points","head":"한 줄 요약","items":["**BLEU(블루 점수)**는 24.6 에서 28.4 로 올랐어요","학습 비용은 96 GPU 일에서 3.3 GPU 일로 줄었어요","더 좋으면서 동시에 더 쌌기 때문에 1년 만에 판이 바뀌었어요"]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["WMT 2014 English to German","WMT 2014 영어에서 독일어로"],["the Transformer beat every previous system, including large ensembles","트랜스포머가 큰 앙상블까지 포함해 이전 시스템을 모두 이겼다"],["and trained in a fraction of the time","게다가 학습 시간은 아주 일부밖에 안 걸렸다"],["The cost column is the part people underestimated","사람들이 과소평가한 것은 비용 쪽이다"],["cheaper training means more experiments, which means faster progress","학습이 싸면 실험을 더 많이 하고, 그러면 더 빨리 발전한다"]]},{"kind":"points","head":"용어 하나씩","items":["**BLEU(블루 점수)**: 번역문이 사람 번역과 n-gram 이 얼마나 겹치는지 재는 점수예요","앙상블: 모델 여러 개의 답을 합쳐서 쓰는 방법이에요","GPU 일수: GPU 한 대를 하루 돌린 것을 1 로 세는 학습 비용 단위예요"]},{"kind":"check","q":"**BLEU(블루 점수)**는 높을수록 어떤가요","choices":["좋아요","나빠요","상관없어요","0 이 제일 좋아요"],"a":0,"why":"사람 번역과 많이 겹칠수록 높아요. 2주차와 이번 주에 계속 나왔어요."}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.199,"w":0.87,"h":0.07,"say":"첫 점: 큰 앙상블까지 다 이겼고, 학습 시간은 아주 일부였다."},{"x":0.06,"y":0.287,"w":0.87,"h":0.029,"say":"둘째 점: 사람들이 과소평가한 것은 비용 쪽이다."},{"x":0.1,"y":0.386,"w":0.35,"h":0.399,"say":"왼쪽 막대: BLEU 24.6, 25.2, 27.3, 28.4. 진한 두 개가 트랜스포머."},{"x":0.52,"y":0.386,"w":0.41,"h":0.399,"say":"오른쪽 막대: 학습 비용 96, 175, 3.3, 8.3 GPU 일. 세로축이 로그예요."},{"x":0.25,"y":0.863,"w":0.5,"h":0.03,"say":"맨 아래: 더 좋고 동시에 더 쌌다, 그래서 1년 만에 분야가 옮겨 갔다."}]},{"kind":"steps","head":"숫자로 차이를 세어 봐요","given":"슬라이드 막대의 숫자","steps":["BLEU 는 GNMT 24.6 에서 Transformer big 28.4 로 올랐어요","차이는 28.4 빼기 24.6 = 3.8 점이에요","학습 비용은 GNMT 96 GPU 일, Transformer base 3.3 GPU 일이에요","96 나누기 3.3 = 약 29.1 배 싸요","ConvSeq2Seq 175 와 Transformer big 8.3 을 비교하면 약 21.1 배예요","GNMT 96 과 Transformer big 8.3 을 비교하면 약 11.6 배예요"],"answer":"점수는 3.8 점 올리면서 비용은 20배에서 30배 줄였어요."},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 기존 RNN 이나 CNN 기반이 24, 25 이렇게 됐는데 트랜스포머가 27, 28까지 올렸어요.","교수님: 초창기 트랜스포머 치고는 이 정도면 꽤 큰 차이로 올린 거예요.","교수님: RNN 은 토큰을 순서대로 처리해야 하는데 트랜스포머는 시퀀스 전체를 큰 행렬 연산으로 한꺼번에 처리해요.","교수님: 그래서 계산 비용이 줄어들 수 있다는 거죠."]},{"kind":"bg","src":"기초 다지기 5단원","lines":["**BLEU(블루 점수)**는 0 에서 100 사이 점수예요. 사람 번역과 n-gram 이 겹치는 비율로 계산해요.","번역 과제에서 1점만 올려도 큰 차이라고 봐요.","그래서 3.8 점 차이는 아주 큰 격차예요."]}],"pass4":[{"kind":"check","q":"Transformer base 의 학습 비용은 GNMT 의 몇 분의 1쯤인가요","choices":["약 29분의 1","약 2분의 1","약 3배","같아요"],"a":0,"why":"96 나누기 3.3 = 약 29.1 이에요."},{"kind":"exam","src":"예상 문제","q":"WMT 2014 영어 독일어 결과에서 트랜스포머가 중요한 이유를 두 가지로 쓰시오.","qko":"점수와 비용, 두 축을 같이 봐야 해요.","solve":["첫째, 성능이 올랐어요. BLEU 24.6 에서 28.4 로 3.8 점 올랐어요","둘째, 학습 비용이 줄었어요. 96 GPU 일에서 3.3 GPU 일로 약 29배 줄었어요","큰 앙상블 모델까지 이겼다는 점도 함께 써요","싸지면 실험을 더 많이 할 수 있고, 그래서 발전이 빨라져요"],"answer":"더 좋으면서 동시에 더 싸다는 점이 분야를 1년 만에 바꾼 이유예요."},{"kind":"english","head":"답안 문장","en":"**트랜스포머(Transformer)**는 WMT 2014 영어 독일어에서 **BLEU(블루 점수)** 28.4 로 이전 방법을 모두 이겼다.","ko":"**RNN(순환 신경망)** 기반은 24.6, **CNN(합성곱 신경망)** 기반은 25.2 였어요. 비용도 96 에서 3.3 GPU 일로 줄었어요.","tip":"24.6, 25.2, 27.3, 28.4 를 순서대로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["오른쪽 비용 그래프의 세로축은 로그예요. 막대 길이를 그대로 비율로 읽으면 안 돼요.","**BLEU(블루 점수)**는 높을수록 좋고, 학습 비용은 낮을수록 좋아요. 방향이 반대예요."]}]},{"p":57,"title":"트랜스포머가 이긴 이유 네 가지","terms":["Transformer","LSTM","Parallelization","Self-Attention","BERT","GPT","Token","Recurrent Neural Network (RNN)"],"pass1":[{"kind":"say","lines":["**트랜스포머(Transformer)**가 **LSTM(장단기 메모리)**보다 똑똑해 보이는 구조는 아니에요.","이긴 이유는 네 가지 성질이 서로 곱해져서 커졌기 때문이에요.","병렬화, 짧은 경로, 잘 쌓임, 과제와 무관함. 이 네 개예요."]},{"kind":"figure","head":"네 가지 성질","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"22\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">트랜스포머가 이긴 네 가지 이유<\/text><rect x=\"16\" y=\"48\" width=\"104\" height=\"90\" rx=\"2\" class=\"box2 b1\"/><text x=\"68\" y=\"74\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b1\">병렬화<\/text><text x=\"68\" y=\"100\" font-size=\"12\" text-anchor=\"middle\" class=\"t b1\">모든 자리를<\/text><text x=\"68\" y=\"118\" font-size=\"12\" text-anchor=\"middle\" class=\"t b1\">한꺼번에<\/text><rect x=\"136\" y=\"48\" width=\"104\" height=\"90\" rx=\"2\" class=\"box2 b2\"/><text x=\"188\" y=\"74\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b2\">짧은 경로<\/text><text x=\"188\" y=\"100\" font-size=\"12\" text-anchor=\"middle\" class=\"t b2\">어떤 두 토큰도<\/text><text x=\"188\" y=\"118\" font-size=\"12\" text-anchor=\"middle\" class=\"t b2\">한 층에서 만나요<\/text><rect x=\"256\" y=\"48\" width=\"104\" height=\"90\" rx=\"2\" class=\"box2 b3\"/><text x=\"308\" y=\"74\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b3\">잘 쌓여요<\/text><text x=\"308\" y=\"100\" font-size=\"12\" text-anchor=\"middle\" class=\"t b3\">같은 블록을<\/text><text x=\"308\" y=\"118\" font-size=\"12\" text-anchor=\"middle\" class=\"t b3\">12층, 96층<\/text><rect x=\"376\" y=\"48\" width=\"104\" height=\"90\" rx=\"2\" class=\"box2 b4\"/><text x=\"428\" y=\"74\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">과제 무관<\/text><text x=\"428\" y=\"100\" font-size=\"12\" text-anchor=\"middle\" class=\"t b4\">글, 그림, 소리<\/text><text x=\"428\" y=\"118\" font-size=\"12\" text-anchor=\"middle\" class=\"t b4\">같은 블록<\/text><line x1=\"20\" y1=\"162\" x2=\"460\" y2=\"162\" class=\"e b5\"/><text x=\"240\" y=\"190\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b5\">같은 블록이 BERT, GPT, ViT, AlphaFold 가 됐어요<\/text><text x=\"240\" y=\"222\" font-size=\"13\" text-anchor=\"middle\" class=\"t b5\">2017년에는 번역용이었는데<\/text><text x=\"240\" y=\"244\" font-size=\"13\" text-anchor=\"middle\" class=\"t b5\">지금은 AI 거의 전부를 돌려요<\/text><\/svg>","caption":"슬라이드의 네 상자를 그대로 옮긴 것이에요. 아래는 같은 블록이 어디까지 갔는지예요.","builds":5},{"kind":"points","head":"한 줄 요약","items":["**병렬화(Parallelization)**: 모든 자리를 한꺼번에 계산해요","짧은 경로: 어떤 두 토큰도 한 층에서 만나요","잘 쌓임: 똑같은 블록을 12층이나 96층으로","과제 무관: 글, 그림, 소리, 단백질까지 같은 블록"]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["The architecture is not obviously smarter than an LSTM","이 구조가 LSTM 보다 딱히 똑똑한 것은 아니다"],["It won because of four properties that compound","네 가지 성질이 서로 곱해지며 커져서 이겼다"],["Parallelism: all positions are computed at once","병렬성: 모든 자리가 한꺼번에 계산된다"],["Short paths: any two tokens meet in a single layer","짧은 경로: 어떤 두 토큰도 한 층 안에서 만난다"],["Scales cleanly: one uniform block, stacked 12x or 96x","깔끔한 확장: 똑같은 블록 하나를 12번이나 96번 쌓는다"],["Task-agnostic: text, vision, audio, proteins, same block","과제 무관: 글, 시각, 소리, 단백질에 같은 블록"]]},{"kind":"points","head":"용어 하나씩","items":["**병렬화(Parallelization)**: 여러 계산을 한꺼번에 동시에 하기예요","**LSTM(장단기 메모리)**: 게이트를 달아 기억을 오래 들고 가게 만든 **RNN(순환 신경망)**이에요","compound: 이자가 불어나듯 서로 곱해져서 효과가 커진다는 뜻이에요"]},{"kind":"check","q":"네 가지 성질에 들어가지 않는 것은","choices":["메모리를 적게 쓴다","병렬화","짧은 경로","과제와 무관"],"a":0,"why":"메모리는 오히려 이차 비용 때문에 더 써요. 이건 값을 치르는 쪽이에요."}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.199,"w":0.75,"h":0.032,"say":"첫 점: LSTM 보다 딱히 똑똑하지는 않은데 네 성질이 겹쳐서 이겼다."},{"x":0.07,"y":0.415,"w":0.21,"h":0.249,"say":"첫 상자 Parallelism: 모든 자리가 한꺼번에 계산된다."},{"x":0.29,"y":0.415,"w":0.21,"h":0.249,"say":"둘째 상자 Short paths: 어떤 두 토큰도 한 층에서 만난다."},{"x":0.51,"y":0.415,"w":0.21,"h":0.249,"say":"셋째 상자 Scales cleanly: 같은 블록을 12번이나 96번 쌓는다."},{"x":0.72,"y":0.415,"w":0.21,"h":0.249,"say":"넷째 상자 Task-agnostic: 글, 시각, 소리, 단백질에 같은 블록."},{"x":0.09,"y":0.694,"w":0.82,"h":0.03,"say":"아래 글씨: 같은 블록이 BERT(2018), GPT(2018-), ViT(2020), AlphaFold(2021) 가 됐다."}]},{"kind":"compare","head":"네 가지 성질과 그 근거","cols":["성질","왜 그런가"],"rows":[["병렬화","RNN 처럼 앞 계산을 기다리지 않고 한 번의 행렬 곱으로 처리해요"],["짧은 경로","셀프 어텐션은 최대 경로 길이가 O(1) 이에요"],["잘 쌓임","잔차 연결과 LayerNorm 덕분에 깊게 쌓아도 학습돼요"],["과제 무관","토큰 시퀀스로 바꿀 수 있으면 무엇이든 같은 블록을 써요"]]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 첫 번째는 병렬화고요. RNN 처럼 앞 토큰의 계산을 기다리지 않아도 됩니다.","교수님: 두 번째는 짧은 경로죠. 멀리 떨어진 두 토큰도 한 레이어 안에서 직접 연결됩니다.","교수님: 세 번째는 확장성이에요. 트랜스포머 블록이 레고 블록처럼 생겨서 계속 쌓을 수 있어요.","교수님: 네 번째는 태스크 어그노스틱. 어그노스틱은 상관이 없다는 뜻이에요."]},{"kind":"bg","src":"기초 다지기 10단원","lines":["GPU 는 큰 행렬 곱 하나를 아주 빠르게 해요. 대신 순서대로 하나씩 하는 일은 느려요.","**트랜스포머(Transformer)**는 문장 전체를 큰 행렬 곱으로 만들어서 GPU 의 장점에 딱 맞아요.","그래서 GPU 가 좋아질수록 트랜스포머가 더 유리해졌어요."]}],"pass4":[{"kind":"check","q":"슬라이드가 든 같은 블록의 후손이 아닌 것은","choices":["word2vec","BERT","GPT","AlphaFold"],"a":0,"why":"word2vec 은 2주차에 배운 단어 벡터 방법이에요. 트랜스포머 이전이에요."},{"kind":"exam","src":"예상 문제","q":"트랜스포머가 널리 쓰이게 된 네 가지 성질을 쓰고 각각 설명하시오.","qko":"네 개를 이름과 한 줄 설명으로 적으면 돼요.","solve":["병렬화: 모든 위치를 한꺼번에 계산해서 GPU 를 잘 쓴다","짧은 경로: 아무리 멀리 떨어진 두 토큰도 한 층에서 직접 연결된다","확장성: 똑같은 블록을 12층, 96층으로 깔끔하게 쌓을 수 있다","과제 무관: 글, 그림, 소리, 단백질까지 같은 블록으로 처리한다"],"answer":"이 네 가지가 서로 곱해지며 커져서 트랜스포머가 이겼어요."},{"kind":"english","head":"답안 문장","en":"**트랜스포머(Transformer)**가 이긴 이유는 **병렬화(Parallelization)**, 짧은 경로, 깔끔한 확장성, 과제 무관성 네 가지이다.","ko":"두 **토큰(Token)**가 한 층에서 만나고, 같은 블록을 12층이나 96층으로 쌓을 수 있어요.","tip":"병렬, 짧은 경로, 확장, 무관 네 글자씩 끊어 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**트랜스포머(Transformer)**가 **LSTM(장단기 메모리)**보다 '똑똑해서' 이긴 게 아니에요. 슬라이드가 직접 아니라고 말해요.","과제 무관은 아무 데이터나 바로 넣어도 된다는 뜻이 아니에요. 토큰 시퀀스로 바꿀 수 있으면 같은 블록을 쓴다는 뜻이에요."]}]},{"p":58,"title":"Check Yourself 2: 스스로 확인하기","terms":["Self-Attention","Cross-Attention","Causal Masking","Softmax","Scaled Dot-Product Attention","Position-wise Feed-Forward Network (FFN)","Parameter","Permutation Equivariance","Positional Encoding","Quadratic Cost","Query","Key","Value","Attention Score","Multi-Head Attention (MHA)"],"pass1":[{"kind":"say","lines":["4장까지 다 들었는지 확인하는 쪽이에요. 여섯 문제예요.","교수님이 수업에서 여섯 개 답을 하나하나 말해 주었어요.","시험 대비 1순위 쪽이에요. 여섯 개를 말로 설명할 수 있으면 4강은 끝이에요."]},{"kind":"points","head":"여섯 문제를 우리말로","items":["1. **셀프 어텐션(Self-Attention)**과 2장의 어텐션은 정확히 무엇이 다른가","2. 마스크는 왜 **소프트맥스(Softmax)** 앞에 걸어야 하는가","3. 왜 루트 d_k 로 나누는가, 안 나누면 무엇이 잘못되는가","4. **트랜스포머(Transformer)**의 **파라미터(Parameter)**는 어텐션과 **FFN(위치별 피드포워드 신경망)** 중 어디에 더 많은가","5. 순수 **셀프 어텐션(Self-Attention)**의 세 가지 벽과 각각의 해결책은","6. 어텐션은 왜 O(n 제곱) 인가, 피하려는 연구 한 줄기를 들어라"]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["What exactly is the difference between self-attention and the attention of section 2","셀프 어텐션과 2장의 어텐션은 정확히 무엇이 다른가"],["Why must the mask be applied before the softmax and not after","왜 마스크를 소프트맥스 뒤가 아니라 앞에 걸어야 하는가"],["Why divide by the square root of d_k, and what goes wrong if you forget","왜 루트 d_k 로 나누고, 잊으면 무엇이 잘못되는가"],["Where do most of a Transformer's parameters live","트랜스포머의 파라미터는 대부분 어디에 있는가"],["Name the three barriers of plain self-attention and the component that fixes each","순수 셀프 어텐션의 세 가지 벽과 각각을 고치는 부품을 대라"],["Why is attention O(n squared), and name one line of work that tries to avoid it","어텐션은 왜 O(n 제곱) 인가, 이를 피하려는 연구 한 줄기를 대라"]]}],"pass3":[{"kind":"look","head":"슬라이드의 여섯 문제를 짚어 읽어요","boxes":[{"x":0.06,"y":0.211,"w":0.6,"h":0.034,"say":"1번: 셀프 어텐션과 2장 어텐션의 차이. p.53 에서 답을 봤어요."},{"x":0.06,"y":0.276,"w":0.52,"h":0.034,"say":"2번: 마스크를 왜 소프트맥스 앞에 거는가."},{"x":0.06,"y":0.339,"w":0.46,"h":0.034,"say":"3번: 왜 루트 d_k 로 나누는가."},{"x":0.06,"y":0.403,"w":0.69,"h":0.034,"say":"4번: 파라미터가 어텐션에 많은가 피드포워드에 많은가."},{"x":0.06,"y":0.468,"w":0.62,"h":0.034,"say":"5번: 순수 셀프 어텐션의 세 가지 벽과 해결책."},{"x":0.06,"y":0.532,"w":0.53,"h":0.034,"say":"6번: 어텐션이 O(n 제곱) 인 이유와 피하려는 연구."}]},{"kind":"steps","head":"4번 답을 숫자로 확인해 봐요","given":"d = 512, d_ff = 4d = 2048","steps":["어텐션 쪽: W^Q, W^K, W^V, W^O 네 개예요","d = 512 이면 4 x 512 x 512 = 1048576, 약 105만 개","FFN 은 속 차원을 4d = 2048 로 넓혔다 줄여요","올라가는 표: 512 x 2048 = 1048576","내려오는 표: 2048 x 512 = 1048576, 합쳐서 2097152","약 210만 개. 어텐션의 정확히 두 배예요"],"answer":"FFN 이 어텐션보다 파라미터가 더 많아요. 두 배예요."},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님(1번): 계산 방법은 같다. 다만 쿼리 키 밸류가 어디서 나오냐에 차이가 있다.","교수님(2번): 마스크는 점수를 음의 무한대로 바꾸는 것이고, 소프트맥스를 쳤을 때 0 이 되게 하려는 거니까 당연히 앞이죠.","교수님(3번): d_k 가 커지면 점수의 분산이 커지고, 소프트맥스가 거의 원-핫이 돼서 기울기가 작아져요.","교수님(4번): 이 논문에서는 d_ff 를 4d 로 설정했으니까 FFN 이 어텐션 프로젝션보다 훨씬 많습니다."]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님(5번): 첫째는 순서를 모른다, 그래서 위치 인코딩. 원 논문은 사인 코사인을 씁니다.","교수님(5번): 둘째는 각 토큰을 깊게 비선형 처리하는 부분이 부족하다, 그래서 위에 FFN 을 둡니다.","교수님(5번): 셋째는 미래 토큰을 봐 버릴 수 있다, 그래서 인과 마스킹을 했다.","교수님(6번): n 개의 쿼리와 n 개의 키가 전부 비교돼야 해서 n x n 을 계산해야 합니다."]}],"pass4":[{"kind":"exam","src":"N4 Check Yourself","q":"Q1 ~ Q3 (Part 2)","qko":"교수님이 수업에서 말해 준 답을 한 줄씩 정리해요.","solve":["1. 계산은 똑같고, **쿼리(Query)**, **키(Key)**, **밸류(Value)**가 어디서 나오는지만 달라요","1. 2장의 **크로스 어텐션(Cross-Attention)**은 Q 가 디코더, K 와 V 가 인코더. **셀프 어텐션(Self-Attention)**은 셋 다 같은 시퀀스","2. **인과 마스킹(Causal Masking)**은 **어텐션 점수(Attention Score)**를 음의 무한대로 바꾸는 것이라, **소프트맥스(Softmax)** 뒤에 하면 이미 0 이 아닌 값이 섞여요","2. 소프트맥스 앞에 걸어야 그 자리의 가중치가 정확히 0 이 돼요","3. d_k 가 커지면 내적 점수의 분산이 커져서 소프트맥스가 거의 원-핫이 돼요","3. 그러면 기울기가 작아지고 표현력도 약해져요. 그래서 루트 d_k 로 나눠 스케일을 맞춰요"],"answer":"1번은 Q, K, V 의 출처, 2번은 0 을 만들기 위해, 3번은 분산을 맞추기 위해예요."},{"kind":"exam","src":"N4 Check Yourself","q":"Q4 ~ Q6 (Part 2)","qko":"나머지 세 문제의 답이에요.","solve":["4. **FFN(위치별 피드포워드 신경망)**이 어텐션보다 많아요. d_ff 를 4d 로 잡기 때문이에요","4. d = 512 면 어텐션 약 105만 개, FFN 약 210만 개로 두 배예요","5. 벽 1은 순서를 모름(**순열 등변성(Permutation Equivariance)**) -> **위치 인코딩(Positional Encoding)**","5. 벽 2는 토큰별 비선형 처리 부족 -> **FFN(위치별 피드포워드 신경망)**","5. 벽 3은 미래 토큰을 봄 -> **인과 마스킹(Causal Masking)**","6. n 개 쿼리가 n 개 키와 전부 비교돼서 n x n 이에요. 슬라이딩 윈도우 어텐션 같은 연구가 있어요"],"answer":"5번 세 벽은 순서, 비선형, 미래 엿보기. 해결은 위치 인코딩, FFN, 마스킹이에요."},{"kind":"check","q":"마스크를 소프트맥스 뒤에 걸면 무엇이 잘못되나요","choices":["가중치 합이 1 이 안 되고 미래 정보가 이미 섞여요","계산이 느려져요","파라미터가 늘어나요","아무 문제 없어요"],"a":0,"why":"교수님: 음의 무한대로 바꾸는 이유가 소프트맥스를 쳤을 때 0 이 되게 하려는 거니까 당연히 앞에 해야죠."},{"kind":"check","q":"**트랜스포머(Transformer)**의 **파라미터(Parameter)**가 더 많은 쪽은","choices":["**FFN(위치별 피드포워드 신경망)**","어텐션 프로젝션","위치 인코딩","LayerNorm 의 감마와 베타"],"a":0,"why":"d_ff = 4d 이기 때문에 FFN 이 어텐션의 두 배예요. 교수님이 직접 답한 문제예요."},{"kind":"english","head":"답안 문장","en":"**셀프 어텐션(Self-Attention)**의 세 벽은 순서, 비선형, 미래 엿보기. 답은 **위치 인코딩(Positional Encoding)**, **FFN(위치별 피드포워드 신경망)**, **인과 마스킹(Causal Masking)**.","ko":"5번은 세 쌍을 짝지어 외우면 그대로 답안이 돼요.","tip":"순서-위치, 깊이-FFN, 미래-마스크 로 외워요."},{"kind":"warn","head":"시험에 나올 만한 곳","items":["Check Yourself 는 교수님이 직접 낸 문제이고, 여섯 개 답을 수업에서 다 말해 줬어요.","슬라이드 맨 아래가 말해요. 블록을 외워서 그릴 수 있으면 실습 준비가 된 거예요.","3번의 '분산이 커진다' 와 4번의 '4d' 는 숫자로 물어볼 수 있어요."]}]},{"p":59,"title":"마무리: 오늘 배운 것, Lab 3, 팀 프로젝트","terms":["Sequence-to-Sequence Model","Information Bottleneck","Attention","Softmax","Weighted Sum","Self-Attention","Query","Key","Value","Scaled Dot-Product Attention","Positional Encoding","Position-wise Feed-Forward Network (FFN)","Causal Masking","Transformer","Multi-Head Attention (MHA)","Residual Connection","Layer Normalization (LayerNorm)","Quadratic Cost","Pre-training","Recurrent Neural Network (RNN)","Encoder","Decoder"],"pass1":[{"kind":"say","lines":["오늘 하루를 네 줄로 정리하는 쪽이에요.","**시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**, **어텐션(Attention)**, **셀프 어텐션(Self-Attention)**, **트랜스포머(Transformer)** 순서로 달려왔어요.","그리고 Lab 3 과 팀 프로젝트 안내, 다음 주 **사전 학습(Pre-training)** 예고가 있어요."]},{"kind":"figure","head":"오늘 하루를 한 줄로","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 480 270\"><text x=\"240\" y=\"20\" font-size=\"15\" text-anchor=\"middle\" class=\"tb\">오늘 하루를 한 줄로 이으면<\/text><rect x=\"16\" y=\"48\" width=\"104\" height=\"34\" rx=\"2\" class=\"box b1\"/><text x=\"68.0\" y=\"69.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b1\">seq2seq<\/text><text x=\"68\" y=\"100\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">벡터 하나가<\/text><text x=\"68\" y=\"118\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b1\">병목이에요<\/text><line x1=\"124\" y1=\"65\" x2=\"141.6\" y2=\"65.0\" class=\"e2 b2\"/><polygon points=\"148,65 140.0,61.0 140.0,69.0\" class=\"arrow b2\"/><rect x=\"152\" y=\"48\" width=\"104\" height=\"34\" rx=\"2\" class=\"box b2\"/><text x=\"204.0\" y=\"69.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b2\">어텐션<\/text><text x=\"204\" y=\"100\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">점수 소프트맥스<\/text><text x=\"204\" y=\"118\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b2\">가중합<\/text><line x1=\"260\" y1=\"65\" x2=\"277.6\" y2=\"65.0\" class=\"e2 b3\"/><polygon points=\"284,65 276.0,61.0 276.0,69.0\" class=\"arrow b3\"/><rect x=\"288\" y=\"48\" width=\"104\" height=\"34\" rx=\"2\" class=\"box b3\"/><text x=\"340.0\" y=\"69.55\" font-size=\"13\" text-anchor=\"middle\" class=\"tb b3\">셀프 어텐션<\/text><text x=\"340\" y=\"100\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">Q K V 가 모두<\/text><text x=\"340\" y=\"118\" font-size=\"12\" text-anchor=\"middle\" class=\"tm b3\">같은 문장에서<\/text><rect x=\"16\" y=\"150\" width=\"448\" height=\"44\" rx=\"2\" class=\"box2 b4\"/><text x=\"240\" y=\"170\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">트랜스포머 = 셀프 어텐션 + 멀티 헤드<\/text><text x=\"240\" y=\"188\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b4\">+ 잔차 연결 + LayerNorm<\/text><text x=\"240\" y=\"224\" font-size=\"13\" text-anchor=\"middle\" class=\"t b5\">값은 n 제곱 비용으로 치러요<\/text><text x=\"240\" y=\"248\" font-size=\"14\" text-anchor=\"middle\" class=\"tb b5\">다음 주는 사전 학습이에요<\/text><\/svg>","caption":"병목을 어텐션이 풀고, 어텐션이 셀프 어텐션이 되고, 거기에 세 장치를 더해 트랜스포머가 됐어요.","builds":5},{"kind":"points","head":"네 줄 요약","items":["**시퀀스-투-시퀀스 모델(Sequence-to-Sequence Model)**: RNN 두 개와 다리 벡터 하나, 그 벡터가 **정보 병목(Information Bottleneck)**이에요","**어텐션(Attention)**: 점수 -> **소프트맥스(Softmax)** -> **가중합(Weighted Sum)**으로 **문맥 벡터(Context Vector)**를 만들어요","**셀프 어텐션(Self-Attention)**: 한 시퀀스에서 Q, K, V 를 만들고 **스케일드 닷프로덕트 어텐션(Scaled Dot-Product Attention)**을 써요","**트랜스포머(Transformer)**: **멀티 헤드 어텐션(Multi-Head Attention (MHA))** + **잔차 연결(Residual Connection)** + **LayerNorm(층 정규화)**, 값은 O(n 제곱)"]}],"pass2":[{"kind":"compare","head":"슬라이드 영어와 우리말 뜻","cols":["영어 원문","뜻"],"rows":[["Seq2Seq: two RNNs, one bridge vector, and that vector is a bottleneck","seq2seq 은 RNN 두 개와 다리 벡터 하나인데 그 벡터가 병목이다"],["Attention: score, softmax, weighted sum, removes the bottleneck","어텐션은 점수, 소프트맥스, 가중합이고 병목을 없앤다"],["learns alignment for free","정렬을 공짜로 배운다"],["Self-attention: Q/K/V from one sequence, scaled dot product","셀프 어텐션은 한 시퀀스에서 Q/K/V 를 만들고 스케일드 내적을 쓴다"],["needs positional encoding, an FFN and a mask","위치 인코딩, FFN, 마스크가 필요하다"],["Transformer: multi-head + residual + LayerNorm, O(n squared) is the price","트랜스포머는 멀티 헤드 + 잔차 + LayerNorm 이고 값은 n 제곱이다"]]},{"kind":"points","head":"Lab 3 과 팀 프로젝트","items":["Lab 3 (1시간): NumPy 와 PyTorch 로 셀프 어텐션을 바닥부터 만들어요","Q/K/V, 마스크, **멀티 헤드 어텐션(Multi-Head Attention (MHA))**, 실제 어텐션 지도 보기까지 해요","팀 프로젝트: 4명 한 조를 만들고 조원과 한 줄짜리 주제를 다음 주까지 보내요"]},{"kind":"points","head":"다음 주 예고","items":["다음 주 주제는 **사전 학습(Pre-training)**이에요","블록은 오늘 것과 똑같고, 모든 것에 대해 학습시켜요","슬라이드 표현으로 the same block, trained on everything 이에요"]}],"pass3":[{"kind":"look","head":"슬라이드를 짚어 읽어요","boxes":[{"x":0.06,"y":0.211,"w":0.55,"h":0.034,"say":"첫 줄 Seq2Seq: RNN 두 개, 다리 벡터 하나, 그게 병목이다."},{"x":0.06,"y":0.276,"w":0.7,"h":0.034,"say":"둘째 줄 Attention: 점수, 소프트맥스, 가중합. 병목 제거, 정렬 학습."},{"x":0.06,"y":0.339,"w":0.78,"h":0.034,"say":"셋째 줄 Self-attention: Q/K/V, 스케일드 내적, 위치 인코딩과 FFN 과 마스크."},{"x":0.06,"y":0.403,"w":0.7,"h":0.034,"say":"넷째 줄 Transformer: 멀티 헤드 + 잔차 + LayerNorm, O(n 제곱) 이 값."},{"x":0.06,"y":0.468,"w":0.87,"h":0.082,"say":"다섯째 줄 Lab 3: NumPy 와 PyTorch 로 셀프 어텐션을 바닥부터."},{"x":0.06,"y":0.586,"w":0.68,"h":0.034,"say":"여섯째 줄 Project: 4인 조를 만들고 조원과 한 줄 주제를 다음 주까지."}]},{"kind":"compare","head":"네 챕터를 한 표로","cols":["챕터","핵심","남은 문제"],"rows":[["1. seq2seq","인코더 RNN 과 디코더 RNN","고정 크기 벡터가 정보 병목"],["2. 어텐션","점수, 소프트맥스, 가중합","아직 RNN 이라 순차 계산"],["3. 셀프 어텐션","Q, K, V 가 한 시퀀스에서, 병렬 계산","**순열 등변성(Permutation Equivariance)**, 비선형, 미래 엿보기"],["4. 트랜스포머","멀티 헤드, 잔차, LayerNorm","O(n 제곱) 이차 비용"]]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 인코더 RNN 이 고정 크기 벡터 하나로 정보를 다 전달하는 병목을 어텐션이 해결해 줬고요.","교수님: 어텐션에서 셀프 어텐션으로 나아가서 병렬적인 개념을 적용했고요.","교수님: 마지막으로 멀티 헤드 어텐션이랑 잔차, 레이어 놈까지 배워봤습니다.","교수님: 트랜스포머라는 개념을 완벽하게 다 설명을 드렸습니다."]},{"kind":"prof","when":"4주차 월요일 2교시","lines":["교수님: 이 Attention Is All You Need 논문은 인공지능 학과로서 매우 중요한 논문입니다.","교수님: 회사 면접에서 가장 기억에 남는 논문이 뭐냐고 물으면 저는 이 논문을 추천할 수 있어요.","교수님: 읽어서 이해를 하면 제 수업도 이해가 되고 시험도 나중에 잘 볼 수 있어요.","교수님: 실습은 풀 코드 아웃풋까지 찍어서 올려놨으니 복습을 나중에 해 보시면 좋겠습니다."]},{"kind":"prof","when":"4주차 월요일 3교시","lines":["교수님(팀 프로젝트): 4인 1조, 자유 주제로 숏 페이퍼 한 편 쓰는 느낌입니다.","교수님: 문제 정의, 가설과 메인 실험 하나, 추가 분석 최소 3개 이상, 리미테이션으로 구성해요.","교수님: 메인 실험 하나에 최소 3개 이상 분석을 해주셔야 좋은 점수를 받습니다.","교수님: 리미테이션은 약점을 숨기는 부분이 아니라 실험을 얼마나 잘 이해했는지 보여 주는 항목이에요."]}],"pass4":[{"kind":"check","q":"오늘 **트랜스포머(Transformer)**에 더한 세 가지 장치는","choices":["**멀티 헤드 어텐션(Multi-Head Attention (MHA))**, **잔차 연결(Residual Connection)**, **LayerNorm(층 정규화)**","위치 인코딩, FFN, 마스크","쿼리, 키, 밸류","점수, 소프트맥스, 가중합"],"a":0,"why":"4장에서 더한 세 가지예요. 두 번째 보기는 3장에서 더한 것이에요."},{"kind":"check","q":"다음 주에 배울 주제는","choices":["**사전 학습(Pre-training)**","토큰화","빔 서치","경사 하강법"],"a":0,"why":"슬라이드 맨 아래: Next week: pretraining, the same block, trained on everything."},{"kind":"exam","src":"예상 문제","q":"seq2seq 에서 트랜스포머까지의 발전 과정을 네 단계로 설명하시오.","qko":"오늘 배운 순서를 그대로 쓰면 돼요.","solve":["1단계 seq2seq: 인코더 RNN 과 디코더 RNN, 고정 크기 벡터 하나가 정보 병목이었어요","2단계 어텐션: 점수, 소프트맥스, 가중합으로 병목을 없애고 정렬도 공짜로 배웠어요","3단계 셀프 어텐션: Q, K, V 를 한 시퀀스에서 만들어 병렬 계산이 가능해졌어요","3단계의 세 가지 벽은 위치 인코딩, FFN, 인과 마스킹으로 막았어요","4단계 트랜스포머: 멀티 헤드, 잔차 연결, LayerNorm 을 더해 깊게 쌓을 수 있게 됐어요"],"answer":"병목 -> 어텐션 -> 셀프 어텐션 -> 트랜스포머. 값은 O(n 제곱) 이에요."},{"kind":"english","head":"답안 문장","en":"**트랜스포머(Transformer)**는 **셀프 어텐션(Self-Attention)**에 세 장치를 더해 깊게 쌓을 수 있게 만든 구조이다.","ko":"세 장치는 **멀티 헤드 어텐션(Multi-Head Attention (MHA))**, **잔차 연결(Residual Connection)**, **LayerNorm(층 정규화)** 이에요.","tip":"얻은 것은 병렬, 치른 값은 **이차 비용(Quadratic Cost)**. 이렇게 짝으로 외워요."},{"kind":"warn","head":"잊지 말 것","items":["팀 프로젝트는 4명 한 조이고, 조원과 한 줄 주제를 다음 주까지 보내야 해요.","Lab 3 은 수업에서 건너뛰었어요. 교수님이 출력까지 찍어 올려놨으니 혼자 복습하세요.","Attention Is All You Need 논문을 꼭 읽어 보라고 교수님이 여러 번 강조했어요."]}]}]};
